<script setup lang="ts">
import { ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)

const cancel = () => vfm.closeAll()
const props = defineProps<{ roomId: string }>()

const deleteRoom = async () => {
  isLoading.value = true
  try {
    await imkit.hideMessagesFromUserInRoom(props.roomId)
    await imkit.updateRoomPrefs({
      roomId: props.roomId,
      prefs: {
        hidden: true
      }
    })
    vfm.closeAll()
    if (imkit.selectedRoomId === props.roomId) {
      imkit.$patch({
        selectedRoomId: ''
      })
    }
  } catch (error) {
    console.error('Error deleting room:', error)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('chatroomDeleteConfirmationTitle')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('delete')"
    confirm-test-id="delete-room-confirm-action"
    :loading="isLoading"
    @cancel="cancel"
    @confirm="deleteRoom"
  >
    {{ $t('chatroomDeleteConfirmationMessage') }}
  </ConfirmDialogShell>
</template>
