import { watch } from 'vue'
import {
  applyHostCapabilities,
  applyKeyboardTransitionEnd
} from './runtime/hostKeyboardTransition'
import { getImkitStore } from './stores/imkit'

export type ImkitWebviewEvent =
  | { type: 'imkit:enterRoom'; roomId: string }
  | { type: 'imkit:leaveRoom'; roomId: string }

type WebkitMessageHandler = { postMessage: (msg: unknown) => void }

declare global {
  interface Window {
    webkit?: {
      messageHandlers?: Record<string, WebkitMessageHandler | undefined>
    }
    imkit?: { postMessage?: (json: string) => void }
    ReactNativeWebView?: { postMessage: (msg: string) => void }
  }
}

function dispatch(event: ImkitWebviewEvent): void {
  const json = JSON.stringify(event)
  // iOS WKWebView message handlers deserialize a structured object natively,
  // so iOS receives the raw event; Android/Flutter/RN bridges accept strings
  // only and receive `json`. The shape difference is intentional — do not
  // "normalize" without updating the native iOS handler contract.
  const targets: Array<[label: string, send: () => void]> = [
    [
      'iOS WKWebView',
      () => window.webkit?.messageHandlers?.imkit?.postMessage(event)
    ],
    ['Android / Flutter WebView', () => window.imkit?.postMessage?.(json)],
    ['React Native WebView', () => window.ReactNativeWebView?.postMessage(json)]
  ]
  for (const [label, send] of targets) {
    try {
      send()
    } catch (e) {
      console.warn(`[imkit] ${label} bridge post failed`, e)
    }
  }
}

type HostMessage = {
  type?: unknown
  eventType?: unknown
  payload?: unknown
}

const acceptedHostMessageTypes = new Set([
  'TRIBO_IMKIT',
  'FLUTTER_IMKIT',
  'IOS_IMKIT'
])

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null

const handleHostMessage = (event: MessageEvent<unknown>): void => {
  if (!isRecord(event.data)) return
  const message = event.data as HostMessage
  if (
    message.type !== undefined &&
    (typeof message.type !== 'string' ||
      !acceptedHostMessageTypes.has(message.type))
  ) {
    return
  }

  const payload = isRecord(message.payload) ? message.payload : {}
  if (message.eventType === 'HOST_CAPABILITIES') {
    applyHostCapabilities(payload)
  } else if (message.eventType === 'KEYBOARD_TRANSITION_END') {
    applyKeyboardTransitionEnd(payload)
  }
}

const announceSdkReady = (): void => {
  const handler = window.webkit?.messageHandlers?.IMKitBridge
  if (!handler) return

  try {
    handler.postMessage(
      JSON.stringify({
        type: 'IMKIT_IOS',
        eventType: 'SDK_READY',
        payload: {},
        timestamp: new Date().toISOString()
      })
    )
  } catch (e) {
    console.warn('[imkit] iOS keyboard bridge post failed', e)
  }
}

let stopBridge: (() => void) | null = null

export function installWebviewBridge(): () => void {
  stopBridge?.()
  const store = getImkitStore()
  const stopRoomWatch = watch(
    () => store.selectedRoomId,
    (id, prev) => {
      if (prev) dispatch({ type: 'imkit:leaveRoom', roomId: prev })
      if (id) dispatch({ type: 'imkit:enterRoom', roomId: id })
    },
    { immediate: true }
  )
  window.addEventListener('message', handleHostMessage)
  announceSdkReady()

  const cleanup = () => {
    stopRoomWatch()
    window.removeEventListener('message', handleHostMessage)
    if (stopBridge === cleanup) stopBridge = null
  }
  stopBridge = cleanup
  return cleanup
}
