import bellUrl from '../assets/bell.mp3?inline'
import type Message from '../classes/message'
import { MessageType } from '../classes/message'
import { getUid } from './uid'

// Shared by Vue and custom-element consumers; one player per SDK runtime.
let player: HTMLAudioElement | undefined
let disposePlayer: (() => void) | undefined
let unlocked = false
const seen = new Set<string>()
const roomViews = new Set<() => string | undefined>()

export const registerNotificationRoomView = (
  currentVisibleRoom: () => string | undefined
): (() => void) => {
  roomViews.add(currentVisibleRoom)
  return () => roomViews.delete(currentVisibleRoom)
}

export const stopNotificationSound = (): void => {
  disposePlayer?.()
  disposePlayer = undefined
  player = undefined
  unlocked = false
  seen.clear()
}

export const initNotificationSound = (): void => {
  stopNotificationSound()
  if (typeof window === 'undefined' || typeof Audio === 'undefined') return

  let audio: HTMLAudioElement
  try {
    audio = new Audio(bellUrl)
  } catch {
    return
  }
  player = audio
  let disposed = false
  let priming = false
  const removeListeners = () => {
    window.removeEventListener('pointerdown', prime)
    window.removeEventListener('keydown', prime)
  }
  const prime = async () => {
    if (disposed || priming || unlocked) return
    priming = true
    audio.muted = true
    try {
      // Keep play inside the user gesture, then rewind without making a sound.
      await audio.play()
      if (disposed) return
      audio.pause()
      audio.currentTime = 0
      unlocked = true
      removeListeners()
    } catch {
      // Autoplay restrictions / unavailable audio must not break chat.
      // Leave the listeners installed so a later gesture can retry.
    } finally {
      audio.muted = false
      priming = false
    }
  }
  window.addEventListener('pointerdown', prime)
  window.addEventListener('keydown', prime)
  disposePlayer = () => {
    disposed = true
    removeListeners()
    audio.pause()
  }
}

export const notifyIncomingMessage = (
  message: Message,
  previousLastMessage?: Message | null
): void => {
  if (!player || typeof document === 'undefined' || !message.id) return
  const key = `${message.roomId}:${message.id}`
  if (seen.has(key)) return
  seen.add(key)
  // Bound memory for long-lived dashboards, including silent messages.
  if (seen.size > 1000) seen.delete(seen.values().next().value!)

  const uid = getUid()
  if (
    !uid ||
    !message.senderId ||
    message.senderId === uid ||
    message.editedAt ||
    message.type === MessageType.Recall ||
    message.type === MessageType.Typing ||
    previousLastMessage?.id === message.id ||
    (previousLastMessage && message.createdAt < previousLastMessage.createdAt)
  )
    return

  const isViewingRoom = [...roomViews].some(
    (currentVisibleRoom) => currentVisibleRoom() === message.roomId
  )
  if (!document.hidden && document.hasFocus() && isViewingRoom) return
  // Never queue old notifications for playback on the next interaction.
  if (!unlocked) return
  try {
    player.currentTime = 0
    void player.play().catch(() => {})
  } catch {
    // Some embedded browsers throw synchronously instead of rejecting play().
  }
}
