import dayjs, { Dayjs } from 'dayjs'
import timezone from 'dayjs/plugin/timezone'
import utc from 'dayjs/plugin/utc'
import { DateTime } from 'luxon'

dayjs.extend(utc)
dayjs.extend(timezone)

const toLocaleString = (
  seconds: number,
  t: (str: string) => string,
  locale: string,
  now: Dayjs = dayjs()
) => {
  // Read the instant in the same timezone basis as Message.dateId
  // (dayjs.tz, honouring dayjs.tz.setDefault) so the divider label and the
  // message grouping can never disagree across a timezone day boundary.
  const dj = dayjs.tz(seconds * 1000)
  const reference = dayjs.tz(now.valueOf())
  if (dj.isSame(reference, 'day')) {
    return t('today')
  }
  if (dj.isSame(reference.subtract(1, 'day'), 'day')) {
    return t('yesterday')
  }
  // Format from the civil (calendar) parts of the timezone-aware day so the
  // rendered date matches dateId regardless of the runner's system timezone.
  const dt = DateTime.fromObject(
    { year: dj.year(), month: dj.month() + 1, day: dj.date() },
    { zone: 'utc' }
  ).setLocale(locale)
  if (dj.isSame(reference, 'week')) {
    return dt.toLocaleString({
      month: 'numeric',
      day: 'numeric',
      weekday: 'short'
    })
  }
  if (dj.isSame(reference, 'year')) {
    return dt.toLocaleString({
      month: 'numeric',
      day: 'numeric'
    })
  }
  return dt.toLocaleString({
    month: 'numeric',
    day: 'numeric',
    year: 'numeric'
  })
}
export default toLocaleString
