import { sha1 } from 'hash-wasm'

// Lowercase-hex encode a digest. Matches hash-wasm's output exactly so a
// content-derived id is identical regardless of which backend produced it.
const toHex = (buffer: ArrayBuffer): string => {
  const bytes = new Uint8Array(buffer)
  let hex = ''
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, '0')
  }
  return hex
}

// SHA-1 the given bytes for content addressing (upload dedup).
//
// Prefer the platform's Web Crypto digest: it runs natively, off the main
// thread, so hashing a large upload (videos up to 100MB) no longer blocks the
// UI the way the synchronous hash-wasm WASM path did. Fall back to hash-wasm
// when Web Crypto can't deliver: crypto.subtle is absent in non-secure contexts
// (http embeds) and older runtimes, and a hardened/policy build can expose
// subtle yet reject the legacy SHA-1 algorithm. Both backends emit the same
// lowercase hex, so the id stays stable across either path — degrading is
// always preferable to failing the upload.
export const sha1Bytes = async (
  data: Uint8Array<ArrayBuffer>
): Promise<string> => {
  try {
    // Reading .subtle can itself throw in some sandboxed iframes/WebViews, and
    // digest('SHA-1') can reject on hardened/policy builds — keep both inside
    // the try so either degrades to hash-wasm instead of failing the upload.
    const subtle = globalThis.crypto?.subtle
    if (subtle) {
      return toHex(await subtle.digest('SHA-1', data))
    }
  } catch (error) {
    // crypto.subtle exists but is unusable here. Both backends emit identical
    // hex, so the fallback is correct; warn so the resulting main-thread perf
    // regression is diagnosable rather than a silent stall. (The expected
    // subtle-absent case skips this branch and does not warn.)
    console.warn(
      '[imkit] crypto.subtle SHA-1 unavailable; falling back to hash-wasm',
      error
    )
  }
  return sha1(data)
}
