,
<script setup lang="ts">
import dayjs from 'dayjs'
import { AlertTriangle, Loader2 } from 'lucide-vue-next'
import { computed, onUnmounted, provide, ref } from 'vue'
import Message, {
  MessageStatus,
  MessageType,
  TemplateMessage,
  TemplateMessageType,
  TextMessage
} from '../classes/message'
import { RoomType } from '../classes/room'
import Settings from '../classes/settings'
import Styles from '../classes/styles'
import User from '../classes/user'
import { hasPointerMovedSinceBaseline } from '../composables/useActionsHandoffGuard'
import { useMessageActions } from '../composables/useMessageActions'
import { useMessageLoading } from '../composables/useMessageLoading'
import {
  useLongPress,
  usePointerDetection
} from '../composables/usePointerDetection'
import { useTrackedElementRect } from '../composables/useTrackedElementRect'
import { getConfig } from '../runtime/config'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import { isAllEmoji as isAllEmojiText } from '../utils/isAllEmoji'
import AIStreamingMessageContent from './AIStreamingMessageContent.vue'
import AudioMessageContent from './AudioMessageContent.vue'
import AvatarView from './AvatarView.vue'
import FileMessageContent from './FileMessageContent.vue'
import FlexMessageContent from './FlexMessageContent.vue'
import ImageMessageContent from './ImageMessageContent.vue'
import LocationMessageContent from './LocationMessageContent.vue'
import MessageActionButtons from './MessageActionButtons.vue'
import MessageDateDivider from './MessageDateDivider.vue'
import MessageStatusDisplay from './MessageStatusDisplay.vue'
import MixedMessageContent from './MixedMessageContent.vue'
import MobileMessageOverlay from './MobileMessageOverlay.vue'
import PaymentMessageContent from './PaymentMessageContent.vue'
import ReactionList from './ReactionList.vue'
import StickerMessageContent from './StickerMessageContent.vue'
import SystemMessageContent from './SystemMessageContent.vue'
import TemplateMessageContent from './TemplateMessageContent.vue'
import TextMessageContent from './TextMessageContent.vue'
import TypingMessageContent from './TypingMessageContent.vue'
import VideoMessageContent from './VideoMessageContent.vue'

const props = defineProps<{
  source: Message
  actionClaimLocked?: boolean
  ownBubbleStyle?: Record<string, string>
}>()
const emit = defineEmits<{
  'popover:open': [id: string]
  'popover:close': [id: string]
}>()
defineOptions({
  inheritAttrs: false
})

provide('messageId', props.source.id)

const imkit = useImkitStore()
const config = getConfig()
const message = computed(() => props.source)
const settings = computed((): Settings => config.settings)
const styles = computed((): Styles => config.styles)
const sender = computed((): User => imkit.users[props.source.senderId])

// Message content components mapping
const contents = {
  [MessageType.Text]: TextMessageContent,
  [MessageType.Image]: ImageMessageContent,
  [MessageType.Mixed]: MixedMessageContent,
  [MessageType.Sticker]: StickerMessageContent,
  [MessageType.Video]: VideoMessageContent,
  [MessageType.File]: FileMessageContent,
  [MessageType.Template]: TemplateMessageContent,
  [MessageType.Flex]: FlexMessageContent,
  [MessageType.Location]: LocationMessageContent,
  [MessageType.Audio]: AudioMessageContent,
  [MessageType.Recall]: TextMessageContent,
  [MessageType.JoinRoom]: TextMessageContent,
  [MessageType.LeaveRoom]: TextMessageContent,
  [MessageType.AddMember]: TextMessageContent,
  [MessageType.DeleteMember]: TextMessageContent,
  [MessageType.AddMembers]: TextMessageContent,
  [MessageType.Announcement]: TextMessageContent,
  [MessageType.Typing]: TypingMessageContent,
  [MessageType.AIStreaming]: AIStreamingMessageContent,
  [MessageType.PaymentSelect]: PaymentMessageContent,
  [MessageType.Payment]: PaymentMessageContent,
  [MessageType.Line]: TextMessageContent
}

// Composables
const {
  canCopy,
  canReply,
  canTranslate,
  canEdit,
  isEdited,
  room,
  setShowActions,
  reply,
  edit,
  copy,
  translate,
  deleteFailedMessage,
  deleteMessage,
  unsendMessage,
  retry,
  selectEmoji
} = useMessageActions(message)

const { hasFinePointer } = usePointerDetection()

const isOutgoing = computed(() => !props.source.isIncoming)
const status = computed(() => message.value.status)

const { showLoading } = useMessageLoading({
  status,
  isOutgoing
})

const isIncoming = computed(() => props.source.isIncoming)

const isGroupHead = computed(() => {
  if (message.value.type === MessageType.Typing) {
    return true
  }
  const groups =
    imkit.messageMultiLists.get(imkit.selectedRoomId)?.main?.messageGroups ??
    new Map()
  const group = groups.get(message.value.groupId)
  if (!group) {
    return false
  }
  return (
    group[0].id === message.value.id ||
    message.value.prev?.senderId !== message.value.senderId
  )
})

const isGroupTail = computed(() => {
  if (message.value.type === MessageType.Typing) {
    return true
  }
  const groups =
    imkit.messageMultiLists.get(imkit.selectedRoomId)?.main?.messageGroups ??
    new Map()
  const group = groups.get(message.value.groupId)
  if (!group) {
    return false
  }
  return (
    group[group.length - 1].id === message.value.id ||
    message.value.next?.senderId !== message.value.senderId
  )
})

const replayShortcut = computed(() => {
  return props.source.template?.quickReply?.items || []
})

// Read receipts only render on the group TAIL (the count sits inside
// v-if="isGroupTail …"). Guard the scan so a non-tail cell never walks every
// room member's lastReadMessageId — that scan is retriggered by every lastRead
// socket event, so on a long grouped run it is pure waste (M40). Declared below
// isGroupTail so the guard reads an initialised ref.
const numberOfRead = computed(() => {
  if (!isGroupTail.value) return 0
  const uid = getUid()
  if (uid !== props.source.senderId) return 0
  const { rooms, messageMultiLists, selectedRoomId } = imkit
  const currentRoom = rooms[props.source.roomId]
  if (!currentRoom) {
    return 0
  }
  const currentList = messageMultiLists.get(selectedRoomId)
  return Object.keys(currentRoom.lastReadMessageId)
    .filter((id) => id !== uid)
    .map((id) => {
      const messageId = currentRoom.lastReadMessageId[id]
      return currentList?.main?.finds(messageId)
    })
    .reduce((acc, msg) => {
      if (msg && msg.createdAt >= props.source.createdAt) {
        return acc + 1
      }
      return acc
    }, 0)
})

const isAllEmoji = computed(
  () =>
    props.source.type === MessageType.Text &&
    isAllEmojiText((props.source as TextMessage).text)
)

const templateMessage = computed(() => props.source as TemplateMessage)

const isSystemMessage = computed(() => props.source.isSystem)

const isUnreadDivider = computed(() =>
  props.source.id.startsWith('unread-divider-')
)

const isFirstMessageOfTheDate = computed(() => {
  const firstMessageOfDate =
    imkit.messageMultiLists.get(imkit.selectedRoomId)?.main
      ?.firstMessageOfDate ?? new Map()
  return firstMessageOfDate.get(props.source.dateId)?.id === props.source.id
})

const showActions = computed(
  () => imkit.activeActionMessageId === props.source.id
)

const reactions = computed(() => {
  return message.value.reactions
})

const hasReactions = computed(() => {
  return reactions.value.length > 0
})

// ReactionList owns the sheet (it is also opened by a long-press on a chip
// there), so the menu item reaches it through the exposed opener rather than
// this cell mounting a second copy. The ref is only ever non-null when
// `hasReactions` is true — which is exactly when the menu item exists — since
// the same flag gates the ReactionList `v-if` below.
const reactionListRef = ref<{ openSheet: (emoji?: string | null) => void }>()

const viewReactions = () => {
  setShowActions(false)
  reactionListRef.value?.openSheet()
}

const roundClass = computed(() => {
  // 20px everywhere, except the corners that face the rest of the group. A
  // group head keeps its top corner round and squares the bottom one on the
  // sender's side; a tail does the reverse; a middle message squares both.
  // `isGroupHead`/`isGroupTail` are both true for a standalone message, which
  // is why that case keeps all four corners at 20px.
  //
  // Every class is written out in full. Tailwind scans source text for literal
  // class names, so a constructed name like `rounded-t${side}-sm` is never
  // generated — the corner would silently stay at 20px with no error anywhere.
  const classes = ['rounded-xl']
  if (isIncoming.value) {
    if (!isGroupHead.value) classes.push('rounded-tl-sm')
    if (!isGroupTail.value) classes.push('rounded-bl-sm')
  } else {
    if (!isGroupHead.value) classes.push('rounded-tr-sm')
    if (!isGroupTail.value) classes.push('rounded-br-sm')
  }
  return classes
})

const messageBlockClass = computed(() => {
  const classes = [...roundClass.value]
  const sourceType = props.source.type
  const templateType = templateMessage.value.templateType

  if (
    new Set([
      MessageType.Sticker,
      MessageType.Image,
      MessageType.Template,
      MessageType.Flex
    ]).has(sourceType) ||
    new Set([
      TemplateMessageType.ImageCarousel,
      TemplateMessageType.Carousel
    ]).has(templateType)
  ) {
    // Neutral plate for non-text content: no colour, not direction-tinted.
    // Was `bg-white! dark:bg-zinc-800!`, a raw pair that stayed neutral while
    // the surrounding palette moved to blue-tinted dark surfaces, so
    // #27272a read as a near-black island. No semantic surface token clears
    // >=3:1 against --color-canvas in every supported colour mode here (the whole
    // bubble system is tonal, not high-contrast: even the tinted
    // message-own bubble only reaches ~1.3-1.6:1 against canvas), so a
    // "readable plate" isn't something this token system provides anywhere
    // — inventing one only for this case would be inconsistent, not a fix.
    // A sticker conventionally renders with no backing at all. An emoji-only
    // message is NOT in this set: it is a text message rendered at a larger
    // glyph size, so it keeps the ordinary bubble fill and padding like any
    // other text. Sending one with no bubble was reported as a bug. Image's
    // own artwork defines its edge. Template/Flex/carousel content already
    // supplies its own bg-surface-muted card fill one layer in
    // (TemplateMessageCarouselContent.vue, FlexMessageBubbleComponent.vue),
    // so this outer wrapper plate was redundant. Transparent removes the
    // clash without losing any real edge definition.
    classes.push('bg-transparent!')

    // Transparency alone does not make a sticker frameless. The incoming
    // branch of the template (see the `isIncoming` ternary on the bubble
    // wrapper) also carries `border border-message-border`, and nothing
    // above cancels it — so a RECEIVED sticker kept a 1px #e4ecf4 rounded
    // frame around empty space while an outgoing one, whose branch is a
    // fill with no border, came out clean. Light mode only:
    // `--color-message-border` is transparent in dark, which is why this
    // read as "stickers are fine" to anyone checking the dark theme.
    //
    // Scoped to Sticker rather than pushed for the whole frameless set
    // above: Image/Template/Flex keep the border because their own content
    // paints over it (artwork to the edge, or an inner bg-surface-muted
    // card), so removing it there would be an unrequested visual change to
    // surfaces the baseline suite photographs.
    if (sourceType === MessageType.Sticker) {
      classes.push('border-0!')
    }
  }

  if (isAllEmoji.value) {
    // KNOWN DEAD: this class does not reach the glyph, and changing its
    // value changes nothing on screen. It sets `font-size` on this wrapper,
    // but the emoji renders inside `TextMessageContent.vue`'s `prose` div,
    // and `prose` declares its own `font-size` on that child element. A
    // child's own declaration always beats a value inherited from its
    // parent — specificity does not cross an element boundary, and
    // `!important` on the parent does not change that. Measured live in the
    // running app: wrapper 30px, inner `<p>` 15px, rendered glyph 15px,
    // bubble 42px. So the "enlarged styling" this branch is named for has
    // never actually applied; an emoji-only message renders at body-text
    // size like any other text message.
    //
    // Left in place rather than deleted, deliberately: it is the only
    // observable `isAllEmoji` produces, so removing it would also strand
    // the surrogate-pair detection guard in MessageCell.test.ts ('👍' is
    // one code point but two code units, and a per-code-unit scan used to
    // split it). The fix is to make the size real — a `prose-p:` variant
    // here, or a rule in `TextMessageContent.vue` — and that needs a
    // decision on what the size should be, which is open.
    classes.push('text-3xl!')
  }
  if ([MessageType.PaymentSelect].includes(props.source.type)) {
    classes.push('flex-[0_0_268px] px-0')
  }
  if (
    !new Set([
      MessageType.Template,
      MessageType.Flex,
      MessageType.Image,
      MessageType.Sticker
    ]).has(sourceType) &&
    !new Set([
      TemplateMessageType.ImageCarousel,
      TemplateMessageType.Carousel
    ]).has(templateType)
  ) {
    // `py-2.5` (10px), not `py-2` (8px): the message floor is 40px and a
    // single-line bubble is a 22px line box, so 8px gave a 38px continuation
    // row. 10px gives 42px — the nearest value on Tailwind's numeric scale
    // that clears the floor. (9px would land exactly on 40 but only as an
    // arbitrary `py-[9px]`, which the spacing section of CLAUDE.md says to
    // avoid; the 2px overshoot is the price of staying on the scale.)
    //
    // This is VERTICAL PADDING, so it applies to every bubble reaching this
    // branch, not only the short ones — a wrapping text bubble grows by the
    // same 4px. That is accepted: 4px on a 78px bubble is not a perceptible
    // change, whereas on the 38px case it is the entire point. Media
    // (Image/Template/Flex/carousel/Sticker/emoji-only) is excluded by the
    // condition above, so the floor does NOT stack padding on top of
    // intrinsically-sized content — pinned by the image bubble staying at
    // 200.00px in tests/e2e/messenger-redesign.spec.ts. Sticker and
    // emoji-only messages share the same transparent, artwork-defined plate
    // (see above) so they get the same treatment: their own content defines
    // the edge, and unlike Image they are small enough that the 40px floor
    // may not hold on content size alone — check actual measured heights
    // before relying on this.
    classes.push('px-4', 'py-2.5')
  }
  if (sourceType === MessageType.Audio) {
    classes.push('w-full', 'max-w-[250px]!')
  }
  if (sourceType === MessageType.File) {
    classes.push('w-full', 'min-w-[250px]!')
  }
  if (sourceType === MessageType.Typing) {
    // The typing indicator holds three fixed-size dots. As a grid item it
    // stretches by default, filling the content column that a long sender
    // nickname (row 1, spanning cols 2-3) widens — leaving blank space beside
    // the dots. Hug the content so the bubble width never tracks the name.
    classes.push('justify-self-start')
  }

  return classes
})

// Event handlers
const messageCellRef = ref<HTMLElement | null>(null)
const handleContextMenu = (event: Event) => {
  if (!hasFinePointer.value) {
    event.preventDefault()
    return
  }
  if (message.value.status !== MessageStatus.Failed) {
    setShowActions(true)
  }
  event.preventDefault()
}

const dismissSoftwareKeyboard = () => {
  const active = document.activeElement
  if (active instanceof HTMLElement) {
    active.blur()
  }
}

// Mobile highlight state
const mobileHighlight = ref(false)
// The overlay paints a fixed-position clone of this cell, so the rect has to
// keep tracking the cell: collapsing the software keyboard reflows the chat a
// few frames after the menu opens (issue #18).
const { rect: highlightRect } = useTrackedElementRect(
  messageCellRef,
  mobileHighlight
)

const onLongPressCallback = () => {
  if (message.value.status !== MessageStatus.Failed) {
    if (!hasFinePointer.value) {
      // Pin the row and snapshot the pre-collapse rect, then blur. WKWebView
      // keeps the software keyboard up unless the composer is explicitly
      // blurred; the collapse resizes the list within a frame or two, and
      // without the pin the re-render can recycle this cell out from under
      // its overlay (issue #18).
      emit('popover:open', props.source.id)
      mobileHighlight.value = true
      dismissSoftwareKeyboard()
    } else {
      setShowActions(true)
    }
  }
}

const dismissMobileHighlight = () => {
  if (!mobileHighlight.value) return
  mobileHighlight.value = false
  emit('popover:close', props.source.id)
}

// Long press setup
useLongPress(messageCellRef, onLongPressCallback, hasFinePointer)

// Dropdown state
const isDropdownOpen = ref(false)

// ChatRoom.vue's openPopoverIds only shrinks on popover:close; a stranded
// id keeps actionClaimLocked true for every row until remount.
// Desktop dropdown: backstop — the child usually already emitted close.
// Mobile overlay: live path — the overlay does not emit dismiss on unmount,
// so recall / remote delete would leak the pin.
onUnmounted(() => {
  if (isDropdownOpen.value || mobileHighlight.value) {
    emit('popover:close', props.source.id)
  }
})

// `actionClaimLocked` (set by ChatRoom.vue while any popover is open) exists
// to stop a bubble that slid under a STATIONARY cursor from stealing the
// action slot from the message whose menu is actually open. Applied to every
// mouseenter, though, it also blocks the deliberate case — hover another
// message and click its own trigger to switch menus in one click — because
// hover is what mounts that second toolbar in the first place. The second
// toolbar never appears, so there is nothing left to click. Two changes that
// each verified fine on their own; the e2e switching spec is what caught the
// collision.
//
// The discriminator is whether the pointer has moved since the popover
// opened — see hasPointerMovedSinceBaseline() in useActionsHandoffGuard.ts,
// which records the two signals that were tried and measured before it.
//
// Deliberately checked ONLY when locked. With no popover open the old
// behaviour is untouched, so an enter with no preceding pointer movement can
// still claim an empty slot exactly as before.
const onBubbleMouseEnter = () => {
  if (!hasFinePointer.value) return
  if (message.value.status === MessageStatus.Failed) return
  if (props.actionClaimLocked && !hasPointerMovedSinceBaseline()) return
  setShowActions(true)
}
</script>

<template>
  <MessageDateDivider v-if="isFirstMessageOfTheDate" :date-id="source.dateId" />

  <SystemMessageContent
    v-if="isSystemMessage"
    :message="source"
    :data-message-id="source.id"
    v-bind="isUnreadDivider ? { 'data-testid': 'unread-divider' } : {}"
  />

  <div
    v-else
    data-testid="message-bubble"
    :data-message-id="source.id"
    class="flex w-full flex-col"
    :class="[
      isGroupHead ? 'mt-2' : 'mt-1',
      // pinchat-only: the reply-shortcut row is absolutely positioned under the
      // bubble, so the row has to reserve its height or the next message sits
      // on top of it.
      replayShortcut.length > 0 ? 'mb-[40px]' : ''
    ]"
    @mouseenter="onBubbleMouseEnter"
    @mouseleave="hasFinePointer && !isDropdownOpen && setShowActions(false)"
  >
    <!--
      gap-x-2 gap-y-0.5, not a single gap-2: this grid holds the sender's
      nickname on row 1 and the bubble on row 2, so one `gap` value was
      spending the same 8px on the horizontal avatar-to-bubble gutter and on
      the vertical name-to-bubble gap. The reference puts the name 2px above
      its bubble (`.bub .who { margin: 0 0 2px 6px }`), and 8px read as the
      name floating loose from the message it labels. The horizontal gutter is
      unchanged.
    -->
    <div
      class="grid w-full gap-x-2 gap-y-0.5"
      :class="
        isIncoming
          ? isGroupHead
            ? 'grid-cols-[30px_fit-content(85%)_minmax(88px,auto)] grid-rows-[auto_1fr] sm:grid-cols-[30px_fit-content(75%)_minmax(88px,auto)]'
            : 'grid-cols-[fit-content(85%)_minmax(88px,auto)] pl-[38px] sm:grid-cols-[fit-content(75%)_minmax(88px,auto)]'
          : 'grid-cols-[minmax(88px,auto)_fit-content(85%)] sm:grid-cols-[minmax(88px,auto)_fit-content(75%)]'
      "
    >
      <!-- Avatar (incoming, group head) -->
      <AvatarView
        v-if="isIncoming && isGroupHead"
        :url="sender?.avatarUrl ?? ''"
        :name="sender?.nickname ?? ''"
        class="row-span-2 h-[30px] w-[30px] rounded-full text-xs"
      />

      <!-- Nickname (incoming, group head) -->
      <div
        v-if="isIncoming && isGroupHead"
        class="col-span-2 line-clamp-2 text-xs font-medium text-content-subtle"
      >
        {{ sender?.nickname ?? '' }}
      </div>

      <!-- Outgoing: Actions or Status -->
      <template v-if="isOutgoing">
        <MessageActionButtons
          v-if="showActions"
          v-model:dropdown-open="isDropdownOpen"
          :message-id="message.id"
          direction="outgoing"
          :can-copy="canCopy"
          :can-reply="canReply"
          :can-translate="canTranslate"
          :can-edit="canEdit"
          :is-superuser="room?.isSuperuser ?? false"
          :is-group-room="room?.isGroup ?? false"
          :status="message.status"
          :has-reactions="hasReactions"
          @reply="reply"
          @edit="edit"
          @copy="copy"
          @translate="translate"
          @delete="deleteMessage"
          @unsend="unsendMessage"
          @retry="retry"
          @delete-failed-message="deleteFailedMessage"
          @select-emoji="selectEmoji"
          @view-reactions="viewReactions"
          @open="emit('popover:open', source.id)"
          @close="emit('popover:close', source.id)"
        />

        <!-- Non-tail status indicator -->
        <div
          v-else-if="!isGroupTail"
          class="flex items-end justify-end gap-1 self-end-safe text-xs text-content-subtle"
        >
          <span v-if="isEdited">{{ $t('edited') }}</span>
          <Loader2 v-if="showLoading" class="h-3 w-3 animate-spin" />
          <button
            v-else-if="message.status === MessageStatus.Failed"
            type="button"
            :aria-label="$t('retry')"
            aria-haspopup="true"
            class="inline-flex cursor-pointer p-0 text-danger-vivid"
            @click="setShowActions(true)"
          >
            <AlertTriangle class="h-4 w-4" />
          </button>
        </div>

        <!-- Tail status display -->
        <div
          v-if="isGroupTail && !showActions"
          class="flex flex-col items-end self-end-safe text-xs text-content-subtle"
        >
          <div
            v-if="settings.enableReadReceipt && numberOfRead > 0"
            data-testid="read-receipt"
          >
            {{ $t('read') }}
            <template v-if="room?.isGroup">
              {{ numberOfRead }}
            </template>
          </div>
          <div>
            <Loader2
              v-if="showLoading"
              class="mr-1 mb-0.5 inline h-3 w-3 animate-spin"
            />
            <button
              v-else-if="message.status === MessageStatus.Failed"
              type="button"
              :aria-label="$t('retry')"
              aria-haspopup="true"
              class="mr-1 mb-0.5 inline-flex cursor-pointer p-0 align-middle text-danger-vivid"
              @click="setShowActions(true)"
            >
              <AlertTriangle class="h-4 w-4" />
            </button>
            {{ isEdited ? $t('edited') + ' ' : ''
            }}{{ dayjs(source.createdAt).format('H:mm') }}
          </div>
        </div>
      </template>

      <!-- Message Content -->
      <div
        ref="messageCellRef"
        data-testid="message-content"
        :data-message-id="message.id"
        class="relative overflow-hidden select-none"
        :class="[
          messageBlockClass,
          isIncoming
            ? 'border border-message-border bg-message text-content'
            : 'bg-message-own text-message-own-content'
        ]"
        :style="[
          isIncoming ? styles.incomingMessageCell : styles.outgoingMessageCell
        ]"
        @contextmenu="handleContextMenu"
      >
        <component :is="contents[source.type]" :message="message" />
      </div>

      <!-- Mobile Highlight Overlay -->
      <MobileMessageOverlay
        :visible="mobileHighlight"
        :highlight-rect="highlightRect"
        :message="message"
        :message-content="contents[source.type]"
        :message-block-class="messageBlockClass"
        :message-style="
          isIncoming ? styles.incomingMessageCell : styles.outgoingMessageCell
        "
        :own-bubble-style="ownBubbleStyle"
        :is-outgoing="isOutgoing"
        :can-copy="canCopy"
        :can-reply="canReply"
        :can-translate="canTranslate"
        :can-edit="canEdit"
        :is-superuser="room?.isSuperuser ?? false"
        :room-type="room?.type ?? RoomType.Direct"
        @dismiss="dismissMobileHighlight"
        @select-emoji="selectEmoji"
        @reply="reply"
        @copy="copy"
        @translate="translate"
        @edit="edit"
        @unsend="unsendMessage"
        @delete="deleteMessage"
      />

      <!-- Incoming: Actions or Time -->
      <MessageActionButtons
        v-if="isIncoming && showActions"
        v-model:dropdown-open="isDropdownOpen"
        :message-id="message.id"
        direction="incoming"
        :can-copy="canCopy"
        :can-reply="canReply"
        :can-translate="canTranslate"
        :can-edit="canEdit"
        :is-superuser="room?.isSuperuser ?? false"
        :is-group-room="room?.isGroup ?? false"
        :status="message.status"
        :has-reactions="hasReactions"
        :class="isGroupHead ? 'ml-1' : 'ml-2'"
        @reply="reply"
        @edit="edit"
        @copy="copy"
        @translate="translate"
        @delete="deleteMessage"
        @unsend="unsendMessage"
        @retry="retry"
        @delete-failed-message="deleteFailedMessage"
        @select-emoji="selectEmoji"
        @view-reactions="viewReactions"
        @open="emit('popover:open', source.id)"
        @close="emit('popover:close', source.id)"
      />

      <MessageStatusDisplay
        v-if="
          isIncoming &&
          !showActions &&
          isGroupTail &&
          message.type !== MessageType.Typing
        "
        direction="incoming"
        :show-loading="showLoading"
        :status="message.status"
        :is-edited="isEdited"
        :created-at="source.createdAt"
        :number-of-read="numberOfRead"
        :enable-read-receipt="settings.enableReadReceipt"
        :room-type="room?.type ?? RoomType.Direct"
      />
    </div>

    <!-- Reactions: outside the grid so chip wrapping does not move actions -->
    <ReactionList
      v-if="hasReactions"
      ref="reactionListRef"
      :reactions="reactions"
      :align="isIncoming ? 'left' : 'right'"
      class="mt-1"
      :class="isIncoming ? 'pl-[38px]' : 'pr-0'"
      @select-emoji="selectEmoji"
    />
  </div>
</template>

