<script setup lang="ts">
/**
 * Round 12: rebuilt from a stack of two full-width destructive buttons (no
 * longer matching the reference design) into a confirm/cancel dialog — a
 * radio group of the two delete choices, `取消` / `刪除` bottom-right. That
 * shape now fits `ConfirmDialogShell` (see the shell's own doc comment for
 * why it was previously excluded), so this uses it instead of inventing a
 * third dialog shape.
 *
 * This component is only ever opened for the two-choice case (group
 * superuser, useMessageActions.ts's `deleteMessage`) — the single-choice
 * ("delete for me" only) case opens `DeleteMessageConfirmModal` directly and
 * never routes through here. Round 12 also DROPS the second confirmation
 * step this dialog used to open (`DeleteMessageConfirmModal`) for its own
 * two-choice path: the choice was previously implicit (two buttons with no
 * shared framing), so a second dialog spelling out the consequence earned
 * its place. Now the choice is explicit and described in this dialog's own
 * body copy before the user ever taps 刪除, so stacking a second
 * confirm/cancel pair behind it would just be confirming the same decision
 * twice. `DeleteMessageConfirmModal.vue` stays for the single-choice path,
 * which still only asks once.
 */
import { computed, ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import Message from '../classes/message'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

type DeleteType = 'everyone' | 'me'

const vfm = useVfm()
const imkit = useImkitStore()
const props = defineProps<{ messageId: string; roomId: string }>()

const message = computed((): Message | undefined =>
  imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.messageId)
)

// `為我刪除` (delete for me) is the safer default: it is the reversible-in-
// effect, lower-blast-radius option (it only affects the current user's own
// view), so it is what a mistaken tap on 刪除 does rather than the
// leaves-a-trace, affects-everyone option.
const deleteType = ref<DeleteType>('me')
const isLoading = ref(false)
const errorMessage = ref('')

const room = computed(() => imkit.rooms[props.roomId])
// `為所有人刪除` was gated on `room?.isSuperuser && room.isGroup` before the
// redesign flattened both choices into this array. `useMessageActions.ts` gates
// OPENING this dialog on the same predicate, so this is defence in depth — but
// the second layer is worth keeping: `isSuperuser` can be absent from a refetch
// (actions.ts preserves it explicitly for that reason), and any future call site
// would otherwise offer a hard delete to a non-superuser.
const canDeleteForEveryone = computed(
  () => !!room.value?.isSuperuser && !!room.value?.isGroup
)

const options = computed<
  Array<{ value: DeleteType; labelKey: string; descriptionKey: string }>
>(() => [
  {
    value: 'me',
    labelKey: 'deleteForMe',
    descriptionKey: 'deleteForMeDescription'
  },
  ...(canDeleteForEveryone.value
    ? [
        {
          value: 'everyone' as const,
          labelKey: 'deleteForEveryone',
          descriptionKey: 'deleteForEveryoneDescription'
        }
      ]
    : [])
])

const confirm = async () => {
  isLoading.value = true
  errorMessage.value = ''
  try {
    if (!message.value) return
    if (deleteType.value === 'everyone' && canDeleteForEveryone.value) {
      await imkit.deleteMessage({
        roomId: message.value.roomId,
        messageId: props.messageId
      })
    } else {
      await imkit.hideMessage({
        roomId: message.value.roomId,
        messageIds: [props.messageId]
      })
    }
    vfm.closeAll()
  } catch (error) {
    console.error('Error deleting message:', error)
    errorMessage.value = 'deleteMessageFailed'
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('deleteMessageTitle')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('delete')"
    confirm-test-id="delete-confirm-ok"
    :loading="isLoading"
    @cancel="vfm.closeAll()"
    @confirm="confirm()"
  >
    {{ $t('deleteMessageDescription') }}

    <template #extra>
      <div
        role="radiogroup"
        :aria-label="$t('deleteMessageTitle')"
        class="flex flex-col gap-2"
      >
        <button
          v-for="option in options"
          :key="option.value"
          type="button"
          role="radio"
          :aria-checked="deleteType === option.value"
          :data-testid="`delete-message-option-${option.value}`"
          class="flex cursor-pointer items-start gap-3 rounded-md border p-3 text-left transition-colors"
          :class="
            deleteType === option.value ? 'border-accent' : 'border-border'
          "
          @click="deleteType = option.value"
        >
          <span
            class="mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2"
            :class="
              deleteType === option.value ? 'border-accent' : 'border-border'
            "
          >
            <span
              v-if="deleteType === option.value"
              class="h-2.5 w-2.5 rounded-full bg-accent"
            />
          </span>
          <span class="flex min-w-0 flex-col gap-0.5">
            <span class="text-base text-content">{{
              $t(option.labelKey)
            }}</span>
            <span class="text-xs text-content-muted">{{
              $t(option.descriptionKey)
            }}</span>
          </span>
        </button>
      </div>
      <div v-if="errorMessage" role="alert" class="text-base text-danger-vivid">
        {{ $t(errorMessage) }}
      </div>
    </template>
  </ConfirmDialogShell>
</template>
