<script setup lang="ts">
/**
 * Moved onto ConfirmDialogShell for the same reasons as PaymentErrorModal,
 * which see.
 *
 * The action was an `<a href>` rather than a button. It becomes a confirm
 * handler that navigates, which costs middle-click and open-in-new-tab on this
 * one control — a real if small loss, taken because a dialog whose primary
 * action is styled and placed unlike every other dialog's is the more visible
 * problem. If the anchor semantics matter more than the alignment, the shell's
 * `extra` slot is where a link would go instead.
 */
import { useVfm } from 'vue-final-modal'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const SETTINGS_PATH = '/dashboard/settings_payment_flow'

const vfm = useVfm()

const goToSettings = () => {
  window.location.href = SETTINGS_PATH
}
</script>

<template>
  <confirm-dialog-shell
    :title="$t('paymentCollectionNotSet')"
    :confirm-label="$t('paymentGoToSetting')"
    :cancel-label="$t('cancel')"
    confirm-variant="primary"
    confirm-test-id="payment-collection-not-set-confirm"
    @confirm="goToSettings"
    @cancel="vfm.closeAll()"
  >
    {{ $t('paymentCollectionNotSetDescription') }}
  </confirm-dialog-shell>
</template>
