<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

/**
 * Block confirmation, on LeaveGroupConfirmModal.vue's shell — deliberately
 * NOT a third dialog shape.
 *
 * Only BLOCKING is confirmed. Unblocking is the correction path for a
 * mistaken block, so putting a dialog in front of it would make the mistake
 * harder to undo than to make; it executes on one click from
 * ChatRoomInfo.vue. This mirrors the same asymmetry RoomCell.vue's
 * hide/unhide pair already documents.
 *
 * `mode: 'error'` opens straight into the error branch. That is how a failed
 * UNBLOCK surfaces: it has no confirm step to fall back into, but it still
 * needs to tell the user the request failed rather than silently reverting.
 * The error copy is therefore written about the block STATUS ("couldn't
 * update"), not about the block direction, so one string set covers both.
 */
const props = withDefaults(
  defineProps<{
    roomId: string
    uid: string
    mode?: 'confirm' | 'error'
  }>(),
  { mode: 'confirm' }
)

const vfm = useVfm()
const imkit = useImkitStore()

const showError = ref(props.mode === 'error')
const isLoading = ref(false)
const nickname = computed(() => imkit.users[props.uid]?.nickname ?? '')

const cancelBlock = () => {
  vfm.closeAll()
}

const executeBlock = async () => {
  isLoading.value = true
  // Optimistic: flip the control before the request resolves, so the panel
  // reflects the user's intent immediately. That visible flip IS the success
  // feedback — this codebase has no toast/snackbar surface — which is also
  // why unblock needs no dialog at all. On failure we put the flag back
  // exactly as it was and show the error branch, so the user never ends up
  // believing they blocked someone when the POST rejected.
  const wasBlocked = imkit.blockedUsers[props.uid]
  imkit.blockedUsers[props.uid] = true
  try {
    await imkit.blockUser({ roomId: props.roomId, uid: props.uid })
    vfm.closeAll()
  } catch (error) {
    console.error('Failed to block user:', error)
    if (wasBlocked) {
      imkit.blockedUsers[props.uid] = wasBlocked
    } else {
      delete imkit.blockedUsers[props.uid]
    }
    showError.value = true
  } finally {
    isLoading.value = false
  }
}

const closeError = () => {
  showError.value = false
  vfm.closeAll()
}

// A single ConfirmDialogShell root (rather than two, toggled by v-if/v-else)
// so this component keeps exactly one root element — vue-final-modal's
// dynamic-modal system forwards modelValue/teleportTo onto that root via
// Vue's attrs fallthrough (see useImkitModal.ts), which only applies when
// there is a single root element.
const onConfirm = () => (showError.value ? closeError() : executeBlock())
</script>

<template>
  <ConfirmDialogShell
    :title="
      showError ? $t('blockErrorTitle') : $t('blockConfirmTitle', [nickname])
    "
    :cancel-label="showError ? undefined : $t('cancel')"
    :confirm-label="showError ? $t('confirm') : $t('block')"
    :confirm-test-id="showError ? undefined : 'block-confirm-action'"
    :loading="!showError && isLoading"
    @cancel="cancelBlock"
    @confirm="onConfirm"
  >
    {{ showError ? $t('blockErrorDesc') : $t('blockConfirmTip') }}
  </ConfirmDialogShell>
</template>
