<script setup lang="ts">
import {
  computed,
  nextTick,
  onBeforeUnmount,
  ref,
  watch,
  type Component,
  type StyleValue
} from 'vue'
import type Message from '../classes/message'
import { RoomType } from '../classes/room'
import {
  flattenMenuGroups,
  useMessageActionItems,
  type ActionType
} from '../composables/useMessageActionItems'
import { REACTION_EMOJIS } from '../constants'
import {
  addKeyboardTransitionEndListener,
  hostKeyboardTransition
} from '../runtime/hostKeyboardTransition'
import { PORTAL_HOST_SELECTOR } from '../runtime/portalHost'
import MenuItemContent from './MenuItemContent.vue'

const props = defineProps<{
  visible: boolean
  highlightRect: DOMRect | null
  message: Message
  messageContent: Component
  messageBlockClass: string[]
  messageStyle: StyleValue
  ownBubbleStyle?: Record<string, string>
  isOutgoing: boolean
  canCopy: boolean
  canReply: boolean
  canTranslate: boolean
  canEdit: boolean
  isSuperuser: boolean
  roomType: RoomType
}>()

const isAnimated = ref(false)
const showMenus = ref(false)
const showOverlayContent = ref(false)
const verticalOffset = ref(0)
const actionMenuRef = ref<HTMLElement | null>(null)
const overlayRef = ref<HTMLElement | null>(null)
let menuTimer: ReturnType<typeof setTimeout> | null = null
let animationFrameId: number | null = null
let nativeLayoutFrameId: number | null = null
let waitingForNativeTransition = false
let removeKeyboardTransitionEndListener: (() => void) | null = null

const BOTTOM_PADDING = 16 // Minimum space from bottom of screen
const MENU_REVEAL_DELAY = 200
const NATIVE_TRANSITION_TIMEOUT = 1000

// Computed transform values to avoid repetition
const translateX = computed(() => 0)

// Keyboard handler for Escape key
const handleKeydown = (event: KeyboardEvent) => {
  if (event.key === 'Escape') {
    event.preventDefault()
    emit('dismiss')
  }
}

// Focus trap handler
const handleFocusTrap = (event: FocusEvent) => {
  if (
    overlayRef.value &&
    event.target instanceof Node &&
    !overlayRef.value.contains(event.target)
  ) {
    overlayRef.value.focus()
  }
}

const clearTimers = () => {
  if (menuTimer) {
    clearTimeout(menuTimer)
    menuTimer = null
  }
  if (animationFrameId !== null) {
    cancelAnimationFrame(animationFrameId)
    animationFrameId = null
  }
  if (nativeLayoutFrameId !== null) {
    cancelAnimationFrame(nativeLayoutFrameId)
    nativeLayoutFrameId = null
  }
  waitingForNativeTransition = false
}

const scheduleMenuReveal = () => {
  waitingForNativeTransition = false
  showOverlayContent.value = true
  showMenus.value = false
  if (menuTimer) clearTimeout(menuTimer)
  menuTimer = setTimeout(() => {
    menuTimer = null
    showMenus.value = true
  }, MENU_REVEAL_DELAY)
}

const waitForNativeTransition = () => {
  waitingForNativeTransition = true
  showOverlayContent.value = false
  showMenus.value = false
  if (menuTimer) clearTimeout(menuTimer)
  // A host that advertises the capability must not be able to strand the
  // menu forever if its native observer is removed or the message is lost.
  menuTimer = setTimeout(() => {
    menuTimer = null
    waitingForNativeTransition = false
    showOverlayContent.value = true
    overlayRef.value?.focus()
    showMenus.value = true
  }, NATIVE_TRANSITION_TIMEOUT)
}

// Calculate whether the action menu would overflow the bottom of the viewport,
// and by how much. Both the rect and the viewport height move while the
// software keyboard collapses, so this has to be re-run on every change rather
// than measured once when the overlay opens (issue #18).
const updateVerticalOffset = () => {
  if (!actionMenuRef.value || !props.highlightRect) {
    verticalOffset.value = 0
    return
  }
  const menuHeight = actionMenuRef.value.offsetHeight
  const menuTop = props.highlightRect.top + props.highlightRect.height + 8
  const menuBottom = menuTop + menuHeight + BOTTOM_PADDING
  // The overlay is `fixed inset-0`, so it is laid out against the layout
  // viewport — measure the overflow in that same coordinate space.
  const overflow = menuBottom - window.innerHeight

  verticalOffset.value = overflow > 0 ? overflow : 0
}

const handleViewportChange = () => {
  if (!props.visible) return
  updateVerticalOffset()
  if (waitingForNativeTransition) return
  scheduleMenuReveal()
}

const revealAfterNativeTransition = () => {
  if (menuTimer) {
    clearTimeout(menuTimer)
    menuTimer = null
  }
  showMenus.value = false

  let framesLeft = 2
  const waitForLayout = () => {
    nativeLayoutFrameId = null
    if (!props.visible || !waitingForNativeTransition) return
    if (framesLeft > 1) {
      framesLeft -= 1
      nativeLayoutFrameId = requestAnimationFrame(waitForLayout)
      return
    }

    updateVerticalOffset()
    waitingForNativeTransition = false
    showOverlayContent.value = true
    overlayRef.value?.focus()
    showMenus.value = true
  }
  nativeLayoutFrameId = requestAnimationFrame(waitForLayout)
}

const handleKeyboardTransitionEnd = () => {
  if (
    !props.visible ||
    !waitingForNativeTransition ||
    hostKeyboardTransition.visible.value
  ) {
    return
  }
  revealAfterNativeTransition()
}

watch(
  () => props.visible,
  async (visible) => {
    clearTimers()

    if (visible) {
      // Add keyboard and focus trap listeners
      document.addEventListener('keydown', handleKeydown)
      document.addEventListener('focusin', handleFocusTrap)
      window.addEventListener('resize', handleViewportChange)
      removeKeyboardTransitionEndListener = addKeyboardTransitionEndListener(
        handleKeyboardTransitionEnd
      )

      // Wait for DOM to render so we can measure the action menu
      await nextTick()

      updateVerticalOffset()

      animationFrameId = requestAnimationFrame(() => {
        animationFrameId = null
        isAnimated.value = true
      })
      // WKWebView can keep moving the anchor while the keyboard collapses.
      // Prefer the host's post-animation signal. Standalone browsers and hosts
      // without that capability retain the geometry-stability fallback.
      if (
        hostKeyboardTransition.supported.value &&
        hostKeyboardTransition.visible.value
      ) {
        waitForNativeTransition()
      } else {
        overlayRef.value?.focus()
        scheduleMenuReveal()
      }
    } else {
      // Remove keyboard and focus trap listeners
      document.removeEventListener('keydown', handleKeydown)
      document.removeEventListener('focusin', handleFocusTrap)
      window.removeEventListener('resize', handleViewportChange)
      removeKeyboardTransitionEndListener?.()
      removeKeyboardTransitionEndListener = null

      isAnimated.value = false
      showOverlayContent.value = false
      showMenus.value = false
      verticalOffset.value = 0
    }
  }
)

watch(
  () => props.highlightRect,
  () => {
    handleViewportChange()
  },
  // Post-flush so the menu has been re-rendered at the new anchor before it is
  // measured.
  { flush: 'post' }
)

onBeforeUnmount(() => {
  clearTimers()
  document.removeEventListener('keydown', handleKeydown)
  document.removeEventListener('focusin', handleFocusTrap)
  window.removeEventListener('resize', handleViewportChange)
  removeKeyboardTransitionEndListener?.()
})

const emit = defineEmits<{
  dismiss: []
  selectEmoji: [emoji: string]
  reply: []
  copy: []
  translate: []
  edit: []
  unsend: []
  delete: []
}>()

const handleDismiss = () => {
  emit('dismiss')
}

const handleEmojiSelect = (emoji: string) => {
  emit('selectEmoji', emoji)
  handleDismiss()
}

const handleAction = (action: ActionType) => {
  // Remove focus trap before emitting so input.focus() can bring up mobile keyboard
  document.removeEventListener('focusin', handleFocusTrap)
  ;(emit as (event: ActionType) => void)(action)
  handleDismiss()
}

const actionGroups = useMessageActionItems({
  canReply: () => props.canReply,
  canCopy: () => props.canCopy,
  canEdit: () => props.canEdit,
  isOutgoing: () => props.isOutgoing,
  isSuperuser: () => props.isSuperuser,
  isGroupRoom: () => props.roomType === RoomType.Group
})

const menuEntries = computed(() => flattenMenuGroups(actionGroups.value))
</script>

<template>
  <Teleport :to="PORTAL_HOST_SELECTOR">
    <div
      v-if="visible && highlightRect"
      ref="overlayRef"
      class="fixed inset-0 z-50 bg-black/50"
      :aria-hidden="!showOverlayContent"
      :style="[
        {
          opacity: showOverlayContent ? 1 : 0,
          pointerEvents: showOverlayContent ? 'auto' : 'none'
        },
        ownBubbleStyle
      ]"
      tabindex="-1"
      @click.self="handleDismiss"
    >
      <!-- Emoji bar above the message -->
      <div
        class="absolute flex min-w-0 items-center gap-2 rounded-full border-0 bg-surface px-4 py-2 text-2xl shadow-raised transition-opacity duration-200"
        :style="{
          bottom: `calc(100% - ${highlightRect.top}px + 8px)`,
          ...(isOutgoing
            ? { right: `calc(100% - ${highlightRect.right}px)` }
            : { left: `${highlightRect.left}px` }),
          opacity: showMenus ? 1 : 0,
          transform: `translate3d(${translateX}px, ${showMenus ? -verticalOffset : 8 - verticalOffset}px, 0)`
        }"
      >
        <button
          v-for="emoji in REACTION_EMOJIS"
          :key="emoji"
          type="button"
          class="cursor-pointer transition-all hover:translate-y-[-2px]"
          @click="handleEmojiSelect(emoji)"
        >
          {{ emoji }}
        </button>
      </div>

      <!-- Cloned Message at original position -->
      <div
        class="absolute overflow-hidden rounded-md"
        :class="[
          messageBlockClass,
          isOutgoing
            ? 'bg-message-own text-message-own-content'
            : 'border border-message-border bg-message text-content'
        ]"
        :style="[
          {
            top: `${highlightRect.top}px`,
            left: `${highlightRect.left}px`,
            width: `${highlightRect.width}px`,
            height: `${highlightRect.height}px`,
            transform: isAnimated
              ? `translate3d(${translateX}px, ${-verticalOffset}px, 0)`
              : 'none'
          },
          messageStyle
        ]"
      >
        <component :is="messageContent" :message="message" />
      </div>

      <!-- Action menu below the message -->
      <div
        ref="actionMenuRef"
        class="absolute min-w-[8rem] rounded-md border border-border bg-surface p-1.5 shadow-raised transition-opacity duration-200"
        :style="{
          top: `${highlightRect.top + highlightRect.height + 8}px`,
          ...(isOutgoing
            ? { right: `calc(100% - ${highlightRect.right}px)` }
            : { left: `${highlightRect.left}px` }),
          opacity: showMenus ? 1 : 0,
          transform: `translate3d(${translateX}px, ${showMenus ? -verticalOffset : -8 - verticalOffset}px, 0)`
        }"
      >
        <template v-for="(entry, index) in menuEntries" :key="index">
          <div
            v-if="entry.kind === 'separator'"
            class="-mx-1 my-1 h-px bg-border"
          />
          <button
            v-else
            type="button"
            class="flex min-h-12 w-full cursor-default items-center rounded-sm px-3 text-base transition-colors select-none hover:bg-accent-subtle"
            :class="{ 'text-danger-vivid': entry.item.danger }"
            @click="handleAction(entry.item.type)"
          >
            <MenuItemContent
              :icon="entry.item.icon"
              :label="$t(entry.item.labelKey)"
              :danger="entry.item.danger"
              size="touch"
            />
          </button>
        </template>
      </div>
    </div>
  </Teleport>
</template>
