<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
</script>

<template>
  <!--
    Direction tinting removed, following the two siblings which dropped theirs
    first. The outgoing branch was `bg-accent text-white` with `text-gray-100`
    and `text-slate-100` foregrounds — raw near-whites painted on a TOKEN
    plate, which is the half-migrated shape CLAUDE.md records as having shipped
    two dark-mode regressions. They survive on today's green only by luck: a
    customer with a pale `brand` seed lightens `accent` and they disappear.

    The `dark:` halves of the incoming pairs are dropped rather than rewritten,
    which the rule allows because the token they belong to (`content-subtle`,
    `content-muted`) is already emitted in the same class string and is itself
    theme-aware.
  -->
  <div class="flex cursor-pointer gap-2 overflow-auto text-base">
    <div
      v-for="(column, index) in message.template.columns"
      :key="index"
      class="w-[250px] cursor-pointer overflow-hidden rounded-lg text-base"
      :class="
        isIncoming
          ? 'bg-message text-content'
          : 'bg-message-own text-message-own-content'
      "
    >
      <img
        v-if="column.thumbnailImageUrl"
        class="object-cover"
        :class="{
          'object-contain': message.template.imageSize === 'contain'
        }"
        :style="{
          // The template's own colour when it sets one, otherwise the plate
          // it sits on rather than a fixed white — this is letterboxing behind
          // a `contain` image, so it should read as part of the card.
          'background-color':
            column.imageBackgroundColor ?? 'var(--color-surface-muted)',
          height: `${
            message.template.imageAspectRatio === 'square' ? 250 : 250 / 1.51
          }px`
        }"
        :src="column.thumbnailImageUrl"
        @click="actionHandler(message.roomId, column.defaultAction)"
      />
      <div
        data-testid="template-message-body"
        class="flex flex-col gap-1 px-4 py-2.5 text-base"
        @click="actionHandler(message.roomId, column.defaultAction)"
      >
        <div>{{ column.title?.substring(0, 100) }}</div>
        <div
          v-if="column.text"
          class="text-base"
          :class="
            isIncoming ? 'text-content-subtle' : 'text-message-own-content'
          "
        >
          {{
            !column.thumbnailImageUrl && !column.title
              ? column.text.substring(0, 160)
              : column.text.substring(0, 300)
          }}
        </div>
      </div>
      <!-- Same alpha-of-the-plate rule as the Buttons sibling, which see. -->
      <div
        v-if="
          (column.actions?.length ?? 0) > 0 &&
          (column.openQuickReply || message.template.category === 'survey')
        "
        class="flex flex-col gap-2 border-t py-3"
        :class="
          isIncoming ? 'border-content/8' : 'border-message-own-content/14'
        "
      >
        <div
          v-for="action in column.actions ?? []"
          :key="action.label"
          class="flex items-center justify-center p-0.5 text-base"
          :class="
            isIncoming ? 'text-content-muted' : 'text-message-own-content'
          "
          @click="actionHandler(message.roomId, action)"
        >
          {{ action.label }}
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped></style>
