<script setup lang="ts">
import { Reply } from 'lucide-vue-next'

defineProps<{
  available: boolean
  replySenderName?: string
  description: string
  isIncoming: boolean
  unavailable: boolean
}>()

const emit = defineEmits<{ navigate: [] }>()
</script>

<template>
  <!--
    The preview is transparent so it keeps the surrounding message-bubble
    fill. The bottom rule uses each bubble side's own foreground tint. Sent
    bubbles also use message-own-content for both lines because accent-vivid
    does not reach 4.5:1 against the blue-light message-own token.
  -->
  <div
    v-if="available"
    data-testid="message-quoted"
    class="-mx-4 cursor-pointer border-b px-4 pb-1.5"
    :class="isIncoming ? 'border-content/8' : 'border-message-own-content/14'"
    @click="emit('navigate')"
  >
    <div
      class="flex items-center gap-1 text-xs font-semibold"
      :class="isIncoming ? 'text-accent-vivid' : 'text-message-own-content'"
    >
      <Reply :size="12" class="h-3 w-3 shrink-0" />
      <span data-testid="message-quoted-sender" class="truncate">
        {{ $t('reply') }} {{ replySenderName }}
      </span>
    </div>
    <div
      data-testid="message-quoted-text"
      class="truncate text-xs"
      :class="isIncoming ? 'text-content-subtle' : 'text-message-own-content'"
    >
      {{ description }}
    </div>
  </div>
  <div
    v-else-if="unavailable"
    data-testid="message-quoted-unavailable"
    class="-mx-4 truncate border-b px-4 pb-1.5 text-xs italic"
    :class="
      isIncoming
        ? 'border-content/8 text-content-subtle'
        : 'border-message-own-content/14 text-message-own-content'
    "
  >
    {{ $t('originalMessageUnavailable') }}
  </div>
</template>
