const ENTRY_SCROLL_DURATION_MS = 180

/** Follow a changing tail without restarting the entry's animation clock. */
export const createMessageEntryScroll = ({
  getOffset,
  getTarget,
  getViewportSize,
  setOffset,
  onFinish,
  onCancel
}: {
  getOffset: () => number
  getTarget: () => number
  getViewportSize: () => number
  setOffset: (offset: number) => void
  onFinish: () => void
  onCancel: () => void
}) => {
  let frame: number | undefined
  let generation = 0

  const cancel = () => {
    generation++
    if (frame !== undefined) cancelAnimationFrame(frame)
    frame = undefined
  }

  const start = (restart = false) => {
    if (frame !== undefined) {
      if (!restart) return
      cancel()
    }
    const currentGeneration = ++generation
    const from = getOffset()
    let previousOffset = from
    let previousViewportSize = getViewportSize()
    const startedAt = performance.now()
    const step = (timestamp: number) => {
      if (generation !== currentGeneration) return
      const target = getTarget()
      const viewportSize = getViewportSize()
      // Scroll events can be coalesced. Detect a reader's reverse movement
      // before writing, while allowing layout to clamp a shrinking scroll range.
      if (
        viewportSize === previousViewportSize &&
        target >= previousOffset - 1 &&
        getOffset() < previousOffset - 1
      ) {
        cancel()
        onCancel()
        return
      }
      const progress = Math.max(
        0,
        Math.min(1, (timestamp - startedAt) / ENTRY_SCROLL_DURATION_MS)
      )
      const eased = 1 - (1 - progress) ** 3
      // A growing viewport can clamp the DOM straight to a smaller tail.
      // Never interpolate backward from that clamp and mistake it for a gesture.
      setOffset(
        Math.min(target, Math.max(getOffset(), from + (target - from) * eased))
      )
      previousOffset = getOffset()
      previousViewportSize = viewportSize
      // A scroll listener can cancel synchronously during setOffset.
      if (generation !== currentGeneration) return
      if (progress < 1) {
        frame = requestAnimationFrame(step)
      } else {
        frame = undefined
        onFinish()
      }
    }
    frame = requestAnimationFrame(step)
  }

  return { start, cancel, isRunning: () => frame !== undefined }
}
