<script setup lang="ts">
import { Smile } from 'lucide-vue-next'
import { REACTION_EMOJIS } from '../constants'
import { PORTAL_HOST_SELECTOR } from '../runtime/portalHost'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuPortal,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

const emit = defineEmits<{
  (e: 'select', emoji: string): void
}>()

const isOpen = defineModel<boolean>('open', { default: false })

const selectEmoji = (emoji: string) => {
  emit('select', emoji)
}
</script>

<template>
  <DropdownMenu v-model:open="isOpen" :modal="false">
    <DropdownMenuTrigger as-child>
      <button
        type="button"
        data-testid="message-emoji-trigger"
        class="tooltip-trigger flex h-7.5 w-7.5 items-center justify-center rounded-full border border-border bg-surface shadow-chip hover:bg-surface-hover"
      >
        <Smile class="h-5 w-5 cursor-pointer text-content-subtle" />
        <span v-if="!isOpen" class="tooltip">{{ $t('emoji') }}</span>
      </button>
    </DropdownMenuTrigger>
    <DropdownMenuPortal :to="PORTAL_HOST_SELECTOR">
      <DropdownMenuContent
        :side-offset="8"
        side="top"
        class="flex w-auto min-w-0 items-center gap-2 rounded-full border-0 bg-surface px-4 py-2 text-2xl shadow-raised"
        @focus-outside.prevent
      >
        <button
          v-for="emoji in REACTION_EMOJIS"
          :key="emoji"
          type="button"
          :data-testid="`emoji-picker-${emoji}`"
          class="cursor-pointer transition-all hover:translate-y-[-2px]"
          @click="selectEmoji(emoji)"
        >
          {{ emoji }}
        </button>
      </DropdownMenuContent>
    </DropdownMenuPortal>
  </DropdownMenu>
</template>
