<script setup lang="ts">
defineOptions({ inheritAttrs: false })
import { Virtualizer } from 'virtua/vue'
import {
  computed,
  defineComponent,
  h,
  nextTick,
  onMounted,
  onUnmounted,
  reactive,
  ref,
  watch,
  type Component,
  type PropType
} from 'vue'
import { useImkitStore } from '../stores/imkit'
import AvatarView from './AvatarView.vue'
import MessageCell from './MessageCell.vue'
import StickerPanel from './StickerPanel.vue'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { vOnClickOutside } from '@vueuse/components'
import dayjs, { Dayjs } from 'dayjs'
import {
  ArrowDownToLine,
  ChevronLeft,
  Loader2,
  LogOut,
  MapPin,
  Mic,
  PanelRight,
  Paperclip,
  Play,
  Plus,
  Search,
  Smile,
  X
} from 'lucide-vue-next'
import { isDark } from 'vue-dark-switch'
import EmojiPicker from 'vue3-emoji-picker'
import 'vue3-emoji-picker/css'
import Message, {
  MessageType,
  MixedMessage,
  TextMessage
} from '../classes/message'
import { RoomType } from '../classes/room'
import Settings from '../classes/settings'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import Styles from '../classes/styles'
import { markPointerBaseline } from '../composables/useActionsHandoffGuard'
import { useAttachmentUpload } from '../composables/useAttachmentUpload'
import { useComposer } from '../composables/useComposer'
import { useMessageListState } from '../composables/useMessageListState'
import { useViewportHeight } from '../composables/useViewportHeight'
import { getConfig } from '../runtime/config'
import { getSocket } from '../runtime/socket'
import { registerNotificationRoomView } from '../runtime/notificationSound'
import { getUid } from '../runtime/uid'
import lineActionHandler from '../utils/line-action-handler'
import { renderMentionsToHtml } from '../utils/renderMentionsToHtml'
import { roomCountSuffix } from '../utils/roomTitle'
import fetchParams from '../utils/url'
import At from './at/At.vue'
import AudioInput from './AudioInput.vue'
import EditMessagePreview from './EditMessagePreview.vue'
import EndChatModal from './EndChatModal.vue'
import FileSizeLimitModal from './FileSizeLimitModal.vue'
import HeaderDivider from './HeaderDivider.vue'
import LocationModal from './LocationModal.vue'
import MessageSendButton from './MessageSendButton.vue'
import PaymentCollectionNotSetModal from './PaymentCollectionNotSetModal.vue'
import PaymentCollectionRequestModal from './PaymentCollectionRequestModal.vue'
import ReplyMessagePreview from './ReplyMessagePreview.vue'
import SearchPanel from './SearchPanel.vue'
import PaymentCollectionSvg from './svgs/PaymentCollection.vue'
import StickerSvg from './svgs/StickerSvg.vue'
import TextFormatMenu from './TextFormatMenu.vue'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
import VersionModal from './VersionModal.vue'
import { agentPresence } from '../utils/agentPresence'
import { chatHeaderStyle } from '../utils/chatHeaderStyle'
import { chatOwnBubbleStyle } from '../utils/chatOwnBubbleStyle'

const MessageListCell = defineComponent({
  name: 'MessageListCell',
  props: {
    source: {
      type: Object as PropType<Message>,
      required: true
    },
    actionClaimLocked: Boolean,
    ownBubbleStyle: {
      type: Object as PropType<Record<string, string> | undefined>,
      default: undefined
    }
  },
  emits: ['popover:open', 'popover:close'],
  setup(props, { emit }) {
    const onPopoverOpen = (id: string) => emit('popover:open', id)
    const onPopoverClose = (id: string) => emit('popover:close', id)
    return () => {
      const cellProps = {
        source: props.source,
        actionClaimLocked: props.actionClaimLocked,
        ownBubbleStyle: props.ownBubbleStyle,
        'onPopover:open': onPopoverOpen,
        'onPopover:close': onPopoverClose
      }
      return props.source.type === MessageType.Typing
        ? h('div', { 'data-testid': 'typing-indicator' }, [
            h(MessageCell, cellProps)
          ])
        : h(MessageCell, cellProps)
    }
  }
})

const imkit = useImkitStore()
const config = getConfig()
const emit = defineEmits<{
  send: []
  goBack: []
}>()
const props = defineProps<{
  isTestPreview?: boolean
  pinchatLink?: string
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  chatStyle?: any
  // Set by the custom-element wrapper, which is the only place that holds both
  // the resolved colour mode and the per-link chatStyle. Vue-plugin consumers
  // that mount ChatRoom directly and pass a chatStyle should pass this too.
  colorMode?: 'light' | 'dark'
}>()

const settings = computed((): Settings => config.settings)

// The composer is the one surface a software keyboard is guaranteed to cover,
// so this root has to follow the keyboard even when a consumer mounts
// ChatRoom on its own rather than through MainView. Refcounted, so mounting
// both costs one set of listeners (issue #20).
//
// Following the keyboard is necessary but not sufficient when the host shell
// owns the whole viewport: the document keeps a scrollable range of the
// keyboard's height regardless, and the browser scrolls the composer into view
// with it. `fullPageEnabled` is the host saying it built that shell, so the
// page may be pinned.
//
// Passed as a GETTER because the answer is not known at mount, NOT because of
// declaration order: a host that renders the custom element and calls
// setConfig in the same commit — the pinchat guest page — delivers its
// settings after this component has mounted, so a value read once would stay
// false for the life of the element and the keyboard gap would come back. Do
// not "simplify" this to `settings.value.fullPageEnabled`.
// See settings.ts and startViewportScrollLock.
useViewportHeight({ lockScroll: () => settings.value.fullPageEnabled === true })

const { open } = useModal({
  component: LocationModal
})
const openFileSizeLimitModal = () => {
  const { open } = useModal({
    component: FileSizeLimitModal,
    attrs: {
      fileSizeLimit: fileSizeLimit.value
    }
  })
  open()
}
const openEndChatModal = () => {
  const { open } = useModal({
    component: EndChatModal
  })
  open()
}
const room = computed(() => imkit.rooms[imkit.selectedRoomId])
// Group rooms only — `Team-14 (3)`, direct rooms show nothing. Shared with
// RoomCell.vue's room-list row via roomTitle.ts so the two can't drift. The
// `(n)` count is rendered as a separate, never-truncating element — see the
// `chatHeaderTitleParts` template usage below and roomTitle.ts.
//
// The name is NOT middle-truncated here, unlike the room-list row: the
// header is as wide as the chat column (the whole viewport on a guest page),
// so the row's fixed character budget cut names that had plenty of room —
// see roomCountSuffix() in roomTitle.ts. CSS clips the name instead.
const chatHeaderTitleParts = computed(() =>
  room.value
    ? {
        name: room.value.displayName ?? '',
        countSuffix: roomCountSuffix(room.value)
      }
    : { name: '', countSuffix: '' }
)
const selectedRoomId = computed(() => imkit.selectedRoomId)
const chatRoot = ref<HTMLElement>()
let unregisterNotificationRoomView: (() => void) | undefined
onMounted(() => {
  unregisterNotificationRoomView = registerNotificationRoomView(() => {
    const el = chatRoot.value
    // A selected room may remain in the store after the host hides its widget.
    if (!el?.isConnected || !el.getClientRects().length) return undefined
    return room.value?.id
  })
})
onUnmounted(() => unregisterNotificationRoomView?.())
const displayName = computed(() => {
  if (props.isTestPreview) {
    return `Test Bot ${(props.pinchatLink ?? '').split('_')[0]}`
  }
  return room.value.displayName
})
const hasFixedRoomId = computed(() => {
  return settings.value.fixedRoomEnabled || fetchParams().has('roomId')
})

const emojiTheme = computed(() => {
  return isDark.value ? 'dark' : 'light'
})

const isRoomInfoVisible = computed(() => imkit.isRoomInfoVisible)

const fileInput = ref<HTMLInputElement>()
const input = ref<HTMLDivElement>()
const lastTypingDate = ref<Dayjs>(dayjs().subtract(5, 'second'))
const showActions = ref(false)
const plusButtonEl = ref<HTMLElement | null>(null)
const formatMenu = ref<InstanceType<typeof TextFormatMenu>>()
const replyId = computed((): string => imkit.replyId)
const editingMessageId = computed((): string => imkit.editingMessageId)
type InputAction = {
  key: string
  icon: Component
  iconClass: string
  label: string
  onClick: () => void
}
const fileSizeLimit = computed(
  () => settings.value.fileUploadSizeLimit ?? 100000000
)
const {
  images,
  imageFiles,
  videos,
  videoFiles,
  isLoadingFiles,
  isLoadingVideo,
  showImageLightbox,
  selectedImageIndex,
  showVideoLightbox,
  selectedVideoUrl,
  onFileChange,
  onDrop,
  onPaste,
  removeImageAtIndex,
  removeVideoAtIndex,
  openImageLightbox,
  openVideoLightbox,
  handleVideoLightboxOpenChange,
  previousImage,
  nextImage
} = useAttachmentUpload({
  roomId: computed(() => room.value?.id ?? ''),
  users: computed(() => imkit.users),
  fileSizeLimit,
  fileInput,
  onOversize: openFileSizeLimitModal,
  sendFile: (payload) => imkit.sendMessage(payload),
  fetchPresignedUrlByPath: (path) => imkit.fetchPresignedUrlByPath(path)
})
// Prepared media is not in images/videos yet; sending now would drop the
// attachment.
const attachmentsPending = computed(
  () => isLoadingFiles.value || isLoadingVideo.value
)
const isSearchInRoomMode = computed(() => imkit.isSearchInRoomMode)
const styles = computed((): Styles => config.styles)
const chatStyle = computed(() => props.chatStyle)
// Per-link header colours, resolved into an inline style that also re-points
// the content tokens for the header's subtree — see chatHeaderStyle.ts for why
// this is one override rather than a binding per control.
const headerStyle = computed(() => chatHeaderStyle(chatStyle.value?.header))
// The agent's online/offline line in the header. `room.extra` is untrusted
// JSON off `extParams`, so the flags are normalised in one place.
const presence = computed(() => agentPresence(room.value?.extra))
// Host switch for the line above. The room flag says whether the LINK wants a
// presence line at all; this says whether THIS mount is one that should show
// it. The admin chat turns it off — see agentPresenceEnabled in settings.ts.
const agentPresenceEnabled = computed(
  () => settings.value.agentPresenceEnabled !== false
)
// Per-link colours for the visitor's own bubble, bound as `:style` on the
// template root. It goes on the root rather than on MessageCell because the
// same tokens paint the quoted preview and the mobile action overlay, which a
// prop on one component would miss. See chatOwnBubbleStyle.ts.
//
// Keep the explanation here, NOT as a comment above the root element: a
// template comment outside the root makes the component multi-root, so
// `wrapper.element` stops being the div and the root-level assertions in
// tests/components/ChatRoom.integration.test.ts fail.
const ownBubbleStyle = computed(() =>
  chatOwnBubbleStyle(chatStyle.value?.self, props.colorMode === 'dark')
)
const isPaymentAvailable = computed(() => {
  return (
    settings.value.linePayEnabled ||
    settings.value.stripeEnabled ||
    settings.value.paypalEnabled
  )
})
const isMobile = computed(() => {
  if (typeof window === 'undefined') return false
  return !window.matchMedia('(hover: hover) and (pointer: fine)').matches
})
const {
  message,
  showStickerPanel,
  showEmojiPicker,
  stickerButtonEl,
  emojiButtonEl,
  showAudioInput,
  send,
  onSelectEmoji,
  onClickOutsideSticker,
  onClickOutsideEmoji,
  toggleStickerPanel,
  toggleEmojiPicker,
  handleImageButtonTapped,
  onCompositionstart,
  onCompositionend,
  onKeydownEnter,
  onBeforeInput,
  onInput,
  onFormatApplied,
  ensureCaretAnchor
} = useComposer({
  room,
  users: computed(() => imkit.users),
  settings,
  isMobile,
  input,
  fileInput,
  images,
  imageFiles,
  videos,
  videoFiles,
  replyId,
  editingMessageId,
  sendMessage: (payload) => imkit.sendMessage(payload),
  editMessage: (payload) => imkit.editMessage(payload),
  clearReply: () => imkit.$patch({ replyId: '' }),
  clearEditing: () => imkit.$patch({ editingMessageId: '' }),
  attachmentsPending,
  onMessageChanged: (roomId, text) => {
    if (!imkit.editingMessageId) {
      imkit.setMessageDraft({ roomId, text })
    }
  },
  onUserInput: () => {
    if (lastTypingDate.value.add(5, 'second') > dayjs()) return
    lastTypingDate.value = dayjs()
    getSocket().emit('typing', selectedRoomId.value)
  }
})
const restoreDraft = async () => {
  const roomId = selectedRoomId.value
  if (
    !roomId ||
    !imkit.messageDraftsLoaded ||
    !room.value ||
    imkit.editingMessageId
  )
    return
  await nextTick()
  if (selectedRoomId.value !== roomId || !input.value || message.value) return
  const draft = imkit.messageDrafts[roomId]
  if (!draft) return
  input.value.innerHTML = renderMentionsToHtml(draft, imkit.users)
  message.value = draft
  const range = document.createRange()
  range.selectNodeContents(input.value)
  range.collapse(false)
  const selection = window.getSelection()
  selection?.removeAllRanges()
  selection?.addRange(range)
  ensureCaretAnchor()
}
watch(
  [selectedRoomId, () => imkit.messageDraftsLoaded, room],
  () => {
    void restoreDraft()
  },
  { immediate: true }
)
const flushDraftOnHide = () => {
  if (document.visibilityState === 'hidden') {
    void imkit.flushMessageDrafts().catch(() => {})
  }
}
const flushDraftOnPageHide = () => {
  void imkit.flushMessageDrafts().catch(() => {})
}
const scrollEl = ref<HTMLElement | null>(null)
const headerEl = ref<HTMLElement | null>(null)
const headerH = ref(0)

watch(
  () => headerEl.value?.offsetHeight ?? 0,
  (h) => {
    headerH.value = h
  },
  { flush: 'post' }
)

// Popover pinning — lifted state so virtua's :keep-mounted can survive
// MessageCell recycles. MessageCell emits popover:open/close(id).
const openPopoverIds = reactive(new Set<string>())
// Opening a popover turns on `actionClaimLocked` for every row. While it is
// on, a hover may only claim the action slot if the pointer has actually
// moved since this moment — that is what separates a deliberate "hover the
// next message and click its trigger" switch from a bubble sliding under a
// stationary cursor as the list scrolls. Marking the baseline here rather
// than measuring elapsed time is the point: opening the menu involves moving
// the mouse, so any time-window approach counts that movement and lets the
// scroll case straight through. See useActionsHandoffGuard.ts.
const onPopoverOpened = (id: string) => {
  markPointerBaseline()
  openPopoverIds.add(id)
}
// Same set, read as a plain "is a message menu on screen" flag: the message
// list must not re-anchor itself underneath an open menu (issue #18).
const isMessageMenuOpen = computed(() => openPopoverIds.size > 0)
const {
  jumpToLatest,
  isInitialLoaded,
  isLatestMessageVisible,
  isNearBottom,
  isPrepending,
  isRequesting,
  isScrollToBottomVisible,
  messageListKey,
  onVlResize,
  onVlScroll,
  onVlScrollEnd,
  reloadData,
  scrollToBottom,
  setVl,
  sortedMessages
} = useMessageListState({ room, scrollEl, isMessageMenuOpen })
const keepMountedIndices = computed(() =>
  sortedMessages.value
    .map((msg, index) => (openPopoverIds.has(msg.id) ? index : -1))
    .filter((i) => i >= 0)
)
// Single release point for both halves of the popover/action-slot ownership
// state - openPopoverIds (this component's own bookkeeping for virtua's
// keep-mounted) and imkit.activeActionMessageId (the global single-owner
// slot, also released per-cell in useMessageActions.ts's onUnmounted for the
// case where only that one cell goes away). Called from every path that can
// orphan ownership at the ChatRoom level: switching rooms (the old room's
// ids are meaningless once its messages are gone) and this component
// tearing down entirely. Keeping both resets in one function means a third
// orphaning path only ever needs one new call site, not a repeated pair of
// resets to keep in sync.
const resetActionOwnership = () => {
  openPopoverIds.clear()
  if (imkit.activeActionMessageId !== '') {
    imkit.$patch({ activeActionMessageId: '' })
  }
}
const inputActions = computed((): InputAction[] => {
  const actions: InputAction[] = []
  if (settings.value.fileInputEnabled) {
    actions.push({
      key: 'file',
      icon: Paperclip,
      iconClass: 'h-6 w-6 text-content-muted',
      label: 'file',
      onClick: () => {
        showActions.value = false
        handleImageButtonTapped()
      }
    })
  }
  if (settings.value.locationInputEnabled) {
    actions.push({
      key: 'location',
      icon: MapPin,
      iconClass: 'h-6 w-6 text-content-muted',
      label: 'location',
      onClick: () => {
        showActions.value = false
        open()
      }
    })
  }
  if (settings.value.audioInputEnabled) {
    actions.push({
      key: 'audio',
      icon: Mic,
      iconClass: 'h-6 w-6 text-content-muted',
      label: 'audio',
      onClick: () => {
        showActions.value = false
        showAudioInput.value = true
      }
    })
  }
  if (settings.value.paymentEnabled) {
    actions.push({
      key: 'payment',
      icon: PaymentCollectionSvg,
      iconClass: 'fill-content-subtle',
      label: 'paymentCollectionTitle',
      onClick: () => {
        showActions.value = false
        onClickPaymentCollection()
      }
    })
  }
  return actions
})
const checkIfDroppable = (event: Event) => {
  event.preventDefault()
}
const back = () => {
  emit('goBack')
  imkit.$patch({ selectedRoomId: '' })
}
const search = () => {
  imkit.$patch({
    isSearchInRoomMode: true
  })
}
onMounted(() => {
  document.addEventListener('visibilitychange', flushDraftOnHide)
  window.addEventListener('pagehide', flushDraftOnPageHide)
  watch(
    selectedRoomId,
    async (newSelectedRoomId, oldSelectedRoomId) => {
      if (newSelectedRoomId === oldSelectedRoomId) return
      resetActionOwnership()
      if (newSelectedRoomId) {
        if (input.value) {
          input.value.textContent = ''
        }
        message.value = ''
        images.value = []
        imageFiles.value = []
        videos.value = []
        videoFiles.value = []
        await reloadData(newSelectedRoomId)
        if (!isMobile.value) input.value?.focus()
      }
    },
    { immediate: true }
  )
  watch(
    replyId,
    () => {
      if (replyId.value) {
        showAudioInput.value = false
        const wasAtBottom = isNearBottom()
        // Focus synchronously to keep mobile keyboard activation within the user gesture call stack
        if (input.value) {
          input.value.focus()
        } else {
          nextTick(() => input.value?.focus())
        }
        if (wasAtBottom) {
          nextTick(() => scrollToBottom())
        }
      }
    },
    { flush: 'sync' }
  )
  watch(editingMessageId, (newId) => {
    if (newId) {
      imkit.$patch({ replyId: '' })
      showAudioInput.value = false
      showStickerPanel.value = false
      showActions.value = false
      // Focus synchronously so iOS opens the keyboard within the user gesture.
      input.value?.focus()
      const editingMessage = imkit.messageMultiLists
        .get(imkit.selectedRoomId)
        ?.main?.map.get(newId)
      if (
        editingMessage &&
        (editingMessage instanceof TextMessage ||
          editingMessage instanceof MixedMessage)
      ) {
        setTimeout(() => {
          if (input.value) {
            const html = renderMentionsToHtml(editingMessage.text, imkit.users)
            input.value.innerHTML = html
            message.value = editingMessage.text
            input.value.focus()
            const range = document.createRange()
            const sel = window.getSelection()
            range.selectNodeContents(input.value)
            range.collapse(false)
            sel?.removeAllRanges()
            sel?.addRange(range)
            // WebKit needs an editable text node when the input only has
            // contenteditable="false" children, otherwise the caret jumps to
            // the far right on click.
            ensureCaretAnchor()
          }
        }, 0)
      }
    } else {
      if (input.value) {
        input.value.textContent = ''
        message.value = ''
      }
      void restoreDraft()
    }
  })
})

// The whole list tearing down (e.g. the host unmounts ChatRoom outright) is
// itself an orphaning path distinct from a room switch - there is no "new
// room" watch trigger to piggyback on, so it needs its own call to the same
// reset.
onUnmounted(() => {
  document.removeEventListener('visibilitychange', flushDraftOnHide)
  window.removeEventListener('pagehide', flushDraftOnPageHide)
  void imkit.flushMessageDrafts().catch(() => {})
  resetActionOwnership()
})

const longtapHandler = () => {
  const { open } = useModal({
    component: VersionModal
  })
  open()
}
const members = computed(() => {
  return room.value.memberIds.map(
    (member: string) => imkit.users[member]?.nickname
  )
})
const textareaDisabled = computed(() => {
  const currRoom = room.value
  if (!currRoom) return false
  if (!currRoom.isSuperuser) return false

  const eligible = currRoom.memberIds.filter(
    (uid: string) => uid !== getUid() && !uid.endsWith('_sub')
  )

  if (eligible.length === 0) return false
  return eligible.every((uid: string) => !!imkit.blockedUsers?.[uid])
})
// Single source for the composer's placeholder/accessible-name key so the visible
// placeholder and the aria-label cannot drift apart (H36 invariant).
const composerPlaceholderKey = computed(() =>
  textareaDisabled.value ? 'textareaBlockedHint' : 'TypeMessage'
)
const canSendComposerMessage = computed(
  () =>
    !attachmentsPending.value &&
    (message.value.length > 0 ||
      images.value.length > 0 ||
      videos.value.length > 0)
)

const lastRealMessage = computed(() =>
  sortedMessages.value
    .filter((message) => message.type !== MessageType.Typing)
    .at(-1)
)
const replayShortcut = computed(() => {
  return lastRealMessage.value?.template?.quickReply?.items ?? []
})
const showReplyShortcut = computed(() => replayShortcut.value.length > 0)

const { open: openPaymentCollectionRequestModal } = useModal({
  component: PaymentCollectionRequestModal,
  attrs: {
    isLinePayEnabled: settings.value.linePayEnabled,
    isStripeEnabled: settings.value.stripeEnabled,
    isPaypalEnabled: settings.value.paypalEnabled
  }
})

const { open: openPaymentCollectionNotSetModal } = useModal({
  component: PaymentCollectionNotSetModal
})

const onClickPaymentCollection = () => {
  if (isPaymentAvailable.value) {
    openPaymentCollectionRequestModal()
  } else {
    openPaymentCollectionNotSetModal()
  }
}
</script>

<template>
  <div
    ref="chatRoot"
    v-bind="$attrs"
    class="flex h-(--imkit-viewport-height) flex-col bg-surface select-none"
    :style="ownBubbleStyle"
    @drop.prevent="onDrop"
    @dragenter="checkIfDroppable"
    @dragover="checkIfDroppable"
  >
    <template v-if="room">
      <!--
        The search header REPLACES the chat header in the same slot rather
        than overlaying it, and both are a fixed `--imkit-header-height`. The
        wrapper below holds that height open so `mode="out-in"` — which leaves
        the slot empty between the two — cannot collapse the row and jolt the
        message list. Height is animated by nothing here on purpose: e2e pins
        both headers at exactly 72px, so the motion is opacity and a few px of
        translate only.
      -->
      <div class="relative h-(--imkit-header-height) shrink-0">
        <transition name="header-swap" mode="out-in">
          <search-panel v-if="isSearchInRoomMode" />
          <!--
            `:style` is `headerStyle ?? styles.chatRoomHeader` (pinchat-only):
            a guest link can carry its own header colours, and they must win
            over the global `styles.chatRoomHeader`. Dropping that binding
            silently reverts every link to the default chrome.

            `headerStyle` carries the FOREGROUND too, as token overrides scoped
            to this subtree. This note used to say the same thing about the
            background alone, while the redesign had already dropped every
            foreground binding it was warning about — the header ended up
            painting `text-content` over a link's brand colour. Do not narrow
            this back to a background-only binding.
          -->
          <div
            v-else
            v-touch:longtap="longtapHandler"
            data-testid="chat-header"
            class="@container relative flex h-(--imkit-header-height) shrink-0 items-center gap-3 px-4 select-none"
            :style="headerStyle ?? styles.chatRoomHeader"
          >
            <!-- Overlaid border, not a real `border-b` — see HeaderDivider.vue. -->
            <HeaderDivider />
            <ChevronLeft
              v-if="!hasFixedRoomId"
              :size="24"
              class="flex shrink-0 cursor-pointer text-content-muted sm:hidden!"
              @click="back"
            />
            <!--
            Group rooms show ONE message-glyph avatar here too, so a group
            looks identical in the header and in the room list. The stacked
            member pair and its `border-2 border-surface` separator ring are
            deleted — avatars carry no border or ring.
          -->
            <!-- Cover when set, group glyph as the fallback — see the note
                 on the same expression in RoomCell.vue for why a group uses
                 `coverUrl` rather than `avatars[0]`. -->
            <span
              data-testid="chat-header-avatar"
