            </div>
            <div class="grow" />
            <div class="flex shrink-0 items-center gap-2">
              <button
                v-if="
                  settings.searchInRoomEnabled &&
                  !props.isTestPreview &&
                  !hasFixedRoomId
                "
                type="button"
                :aria-label="$t('search')"
                class="tooltip-trigger flex h-9 w-9 cursor-pointer appearance-none items-center justify-center rounded-full border-0 bg-transparent p-0 text-content-muted transition-colors hover:bg-surface-hover hover:text-content focus-visible:ring-1 focus-visible:ring-accent-vivid focus-visible:outline-none"
                @click="search"
              >
                <Search :size="20" aria-hidden="true" class="h-5 w-5" />
                <span class="tooltip tooltip-below">{{ $t('search') }}</span>
              </button>
              <button
                v-if="settings.showEndChatButton && !props.isTestPreview"
                type="button"
                :aria-label="$t('endChat')"
                class="tooltip-trigger flex h-9 w-9 cursor-pointer appearance-none items-center justify-center rounded-full border-0 bg-transparent p-0 text-content-muted transition-colors hover:bg-surface-hover hover:text-content focus-visible:ring-1 focus-visible:ring-accent-vivid focus-visible:outline-none"
                @click="openEndChatModal"
              >
                <LogOut aria-hidden="true" class="h-5 w-5" />
                <span class="tooltip tooltip-below">{{ $t('endChat') }}</span>
              </button>
              <button
                v-if="
                  ((room.isGroup && settings.showGroupChatRoomInfoButton) ||
                    (room.type === RoomType.Direct &&
                      settings.showDirectChatRoomInfoButton)) &&
                  !props.isTestPreview
                "
                data-testid="chat-info-button"
                type="button"
                :aria-label="$t('roomInfo')"
                class="tooltip-trigger flex h-9 w-9 cursor-pointer appearance-none items-center justify-center rounded-full border-0 p-0 transition-colors focus-visible:ring-1 focus-visible:ring-accent-vivid focus-visible:outline-none"
                :class="
                  isRoomInfoVisible
                    ? 'bg-accent-subtle text-accent hover:bg-accent-subtle hover:text-accent'
                    : 'bg-transparent text-content-muted hover:bg-surface-hover hover:text-content'
                "
                @click="
                  imkit.$patch({
                    isRoomInfoVisible: !isRoomInfoVisible
                  })
                "
              >
                <PanelRight :size="20" aria-hidden="true" class="h-5 w-5" />
                <span class="tooltip tooltip-below">{{ $t('roomInfo') }}</span>
                <slot name="setting" />
              </button>
            </div>
          </div>
        </transition>
      </div>

      <div
        ref="scrollEl"
        data-testid="chat-scroll-container"
        class="@container grow overflow-auto overscroll-y-none bg-canvas p-2"
        style="overflow-anchor: none"
      >
        <div
          class="pointer-events-none sticky top-0 z-10"
          style="height: 0; overflow: visible"
        >
          <div
            v-if="isRequesting"
            data-testid="chat-prepend-spinner"
            class="flex h-12 w-full items-center justify-center"
          >
            <svg
              class="h-6 w-6 animate-spin fill-accent-vivid text-surface-muted"
              viewBox="0 0 100 101"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z"
                fill="currentColor"
              />
              <path
                d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z"
                fill="currentFill"
              />
            </svg>
          </div>
        </div>
        <div ref="headerEl" />
        <!--
          `item-size` is virtua's estimate for rows it has not measured yet.
          It was re-derived by MEASUREMENT, not arithmetic, when the 40px
          message floor landed: an identical text-dominant fixture (16 text
          rows plus one image, one file, one location and one audio) was
          measured before and after the `py-2.5` change, and the mean
          rendered row pitch moved 74.04px -> 78.04px, the median 52 -> 56 —
          a uniform +4.00px, because the floor adds 4px to every text row and
          none to intrinsically-sized media. The estimate therefore moves by
          that measured delta: 66 -> 70. (The fixture's absolute mean runs
          above the estimate because it contains a ~257px map bubble, which
          is not typical; what is being tracked here is the shift.)

          The approved group-spacing restoration was measured with the same
          three-row runtime fixture before and after its 8px/4px margins:
          mean pitch moved 76.796875px -> 75.796875px. Its rounded -1px
          delta applies to the existing estimate: 70 -> 69.
        -->
        <!--
          The reveal gate is on the list, NOT on the scroll container above
          it: the loading spinner is a sticky child of that container, so
          hiding the container hid the only loading affordance too. That is
          why the gate used to read `!isInitialLoaded && !isRequesting` — the
          `!isRequesting` half existed to bring the spinner back, and as a
          side effect it also revealed an unpositioned list for the whole of
          any in-flight request, which is the cached-path jump this fixes.
          Split apart, each half says one thing: the spinner follows the
          request, the list stays hidden until it has been scrolled to its
          anchor.
        -->
        <Virtualizer
          :key="messageListKey"
          :ref="setVl"
          data-testid="chat-message-list"
          :class="{ 'opacity-0': !isInitialLoaded }"
          :data="sortedMessages"
          :scroll-ref="scrollEl || undefined"
          :start-margin="headerH"
          :shift="isPrepending"
          :item-size="69"
          :keep-mounted="keepMountedIndices"
          @resize="onVlResize"
          @scroll="onVlScroll"
          @scroll-end="onVlScrollEnd"
        >
          <template #default="{ item }">
            <MessageListCell
              :key="item.id"
              :source="item"
              :action-claim-locked="openPopoverIds.size > 0"
              :own-bubble-style="ownBubbleStyle"
              @popover:open="onPopoverOpened(item.id)"
              @popover:close="openPopoverIds.delete(item.id)"
            />
          </template>
        </Virtualizer>
      </div>

      <!--
        The reply/edit strip sits ABOVE the composer row, not inside the input
        field. Inside the field it had to cancel and restore the field's own
        padding on three sides to reach its edges, and it still left the
        sticker/emoji buttons and the + button to be aligned against a box
        whose height it changed. Out here it is a plain full-width band with
        its own padding — nothing to cancel, nothing to keep in sync.
      -->
      <!--
        The scroll-to-bottom button anchors to THIS wrapper, which spans the
        strip and the composer row together, rather than to the row alone. Its
        `-top-12` measures from its offset parent's top edge; anchored to the
        row, that landed on top of the reply/edit strip as soon as one was
        showing, because the strip is now a sibling above the row rather than
        a block inside the field.

        Its fill is `bg-panel`; the raw light/dark pair it replaced could not
        follow the derived palette. A token already changes with colour mode,
        so an additional `dark:` utility would fight it.
      -->
      <!--
        `border-t` on THIS wrapper, not on the composer row below it. The row
        is `py-3.5` so that 14 + 44 + 14 makes it exactly 72 — the header
        height — and a border inside that box would make it 73 and shift the
        field down a pixel under `items-end`. Out here there is no fixed
        height to disturb, and the rule also sits above the reply/edit strip
        rather than between it and the input.

        Removed on this branch while `canvas` was aliased to white, where it
        separated two identical planes and read as a stray line. `canvas` is
        `#fafafa` again, so the seam between the message area and the composer
        is real and needs drawing — `main` never dropped this.
      -->
      <div class="relative border-t border-border">
        <button
          v-if="isScrollToBottomVisible"
          data-testid="scroll-to-bottom-button"
          type="button"
          :aria-label="$t('scrollToBottom')"
          class="absolute -top-12 right-3 z-10 flex h-9 w-9 cursor-pointer items-center justify-center rounded-full bg-panel text-content-muted shadow-raised transition hover:scale-110"
          @click="jumpToLatest()"
        >
          <ArrowDownToLine class="h-5 w-5" />
        </button>
        <edit-message-preview />
        <reply-message-preview />
        <!--
          Anchored to the same outer wrapper as the scroll-to-bottom button
          above, for the same reason: `-top-10` measures from the offset
          parent, so while it lived inside the composer row it was drawn over
          the reply/edit strip whenever one was showing. That was fixed for
          the button and missed for this sibling — both are absolutely
          positioned children of the row, and only one was moved.

          `bg-panel` for the same reason too: the raw light/dark pair it
          replaced could not follow the derived palette.
        -->
        <!--
          `surface-muted` with a hairline on BOTH edges, not a bare `bg-panel`
          slab. The banner is absolutely positioned across the seam: its top
          edge overlays the message canvas, its bottom edge butts against the
          composer, which paints `surface` from the ChatRoom root. In light
          mode `panel` and `surface` derive to the same #ffffff, so the bottom
          edge had literally nothing to mark it and the banner and composer
          read as one white block.

          A fill alone will not fix it — every neutral plane is within a
          couple of dE of `surface` in light. The borders are what carry the
          separation; the fill just keeps it from looking like part of the
          canvas above.

          `border-t` only, not `border-y`. This banner sits at `-top-10`
          against a wrapper that carries its own `border-t`, so its bottom
          edge lands on exactly that seam — `border-y` stacks two hairlines
          into 2px there whenever the banner is visible. It was widened to
          `border-y` on this branch only because the wrapper's border had been
          removed; both move together.
        -->
        <div
          v-if="isLatestMessageVisible"
          data-testid="latest-message-banner"
          class="absolute -top-10 right-0 left-0 z-10 flex h-10 cursor-pointer items-center border-t border-border bg-surface-muted px-3"
          @click="jumpToLatest()"
        >
          <span
            class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-content"
          >
            {{ room.lastMessage?.bannerLabel(room.isGroup) }}
          </span>
        </div>
        <!--
          py-3.5 (14px), not py-3: with the field at 44px this makes the row
          exactly 14 + 44 + 14 = 72, the same height as the three headers, and
          the field's own box drives it rather than a neighbour. The + button
          drops 48px -> 44px for the same reason — at 48 it over-defined the
          row's content box and left 4px of dead space above the field under
          items-end, which read as the field not being centred.
        -->
        <div class="relative flex items-end justify-center gap-3 px-4 py-3.5">
          <button
            v-if="
              !editingMessageId &&
              (settings.locationInputEnabled ||
                settings.audioInputEnabled ||
                settings.fileInputEnabled ||
                settings.paymentEnabled)
            "
            ref="plusButtonEl"
            type="button"
            data-testid="composer-plus-button"
            class="inline-flex h-11 w-5 shrink-0 cursor-pointer appearance-none items-center justify-center border-0 bg-transparent p-0 text-content-muted transition"
            @click="
              () => {
                if (showAudioInput) {
                  showAudioInput = false
                } else {
                  showActions = !showActions
                }
              }
            "
          >
            <Plus
              class="h-11 w-5 transform object-contain"
              :class="{ 'rotate-45': showAudioInput }"
            />
          </button>
          <!--
            Two halves of one fix; either alone leaves the menu unclosable
            from the button. The handler above toggles rather than assigning
            `true` — it used to only ever open. And the button is in this
            directive's `ignore` list, because otherwise clicking it while
            the menu is open fires click-outside FIRST (closing it) and then
            the button's own handler (reopening it), so the menu never
            appears to respond. The `+` looked dead while every other menu
            behaved, because the rest use radix's dropdown primitive, which
            owns both sides of the toggle itself.

            Ignore is the element ref, not a CSS selector — same as the
            sticker and emoji panels next to this. The trigger is a
            `<button>` wrapping the lucide SVG so a click on the glyph
            still has that node on `composedPath`.
          -->
          <div
            v-if="showActions"
            v-on-click-outside="[
              () => {
                showActions = false
              },
              { ignore: [plusButtonEl] }
            ]"
            data-id="actions"
            class="absolute bottom-16 left-2 z-10 grid max-w-[240px] rounded-lg border border-border bg-surface p-1.5 text-content shadow-raised"
            :class="
              inputActions.length === 1
                ? 'grid-cols-1'
                : inputActions.length === 2
                  ? 'grid-cols-2'
                  : 'grid-cols-3'
            "
          >
            <!--
            Concentric-radius rule: inner = outer − padding. The container
            is `rounded-lg` (16px) with `p-1.5` (6px), so the item's hover
            fill wants 16 − 6 = 10px, which is `rounded-md` — not the
            `rounded-sm` (6px) it had, which fought the container's own
            curve at the shared corner instead of following it.
          -->
            <div
              v-for="action in inputActions"
              :key="action.key"
              class="flex min-w-16 cursor-pointer flex-col items-center gap-1 rounded-md p-2 hover:bg-surface-hover"
              @click="action.onClick"
            >
              <component :is="action.icon" :class="action.iconClass" />
              <div class="mt-1 flex flex-1 items-center">
                <span class="text-center text-xs leading-none">
                  {{ $t(action.label) }}
                </span>
              </div>
            </div>
          </div>
          <audio-input v-if="settings.audioInputEnabled && showAudioInput" />
          <div
            v-else
            data-testid="composer-field"
            class="relative flex min-w-0 grow flex-col items-stretch rounded-xl bg-field px-4 py-2.5 focus-within:ring-1 focus-within:ring-border-strong"
          >
            <!--
              pinchat-only: LINE quick-reply shortcuts from the last template
              message, floated above the composer. `bg-surface` + `shadow-raised`
              rather than the composer's own fill so the chips read as sitting
              over the canvas, not as part of the field. MessageCell reserves the
              40px this occupies — see the `replayShortcut` clause on its row.
            -->
            <div
              v-if="showReplyShortcut"
              class="absolute top-[-40px] left-1/2 flex -translate-x-1/2 gap-5"
            >
              <button
                v-for="(shortcut, index) in replayShortcut"
                :key="index"
                type="button"
                class="cursor-pointer rounded-full bg-surface px-2 py-1 text-center text-xs text-content shadow-raised"
                @click="lineActionHandler(selectedRoomId, shortcut.action)"
              >
                {{ shortcut.action.label }}
              </button>
            </div>
            <!--
            The two buttons carry `h-6` to match the input's own 24px line
            box. They are 20-22px glyphs, so bottom-aligning them alone left
            their centres 2px below the input's — visible at one line, and
            caught by messenger-redesign.spec.ts's centreDelta <= 1. Equal
            heights make "aligned to the bottom" and "centred on the line" the
            same position.

            items-end, not items-center: the sticker/emoji buttons sit in a row
            beside the input COLUMN, and that column grows as the message wraps
            (up to 5 lines on mobile, 10 on desktop). Centring pinned them to
            the middle of that growing box, so they drifted upward away from
            the `+` outside the field on the left, which is bottom-aligned.
            Anchoring to the bottom keeps all three controls on one line at any
            height. At one line the two are indistinguishable, which is why
            this went unnoticed.
          -->
            <div class="flex items-end gap-3">
              <div
                class="flex w-0 min-w-0 grow flex-col items-stretch justify-center gap-3"
              >
                <At class="relative flex" :members="members">
                  <!-- @vue-ignore At.vue is plain JS, slot types not inferred -->
                  <template #embeddedItem="{ current }">
                    <span>@{{ current }}</span>
                  </template>
                  <div
                    ref="input"
                    data-testid="chat-input"
                    role="textbox"
                    aria-multiline="true"
                    dir="auto"
                    :contenteditable="!textareaDisabled"
                    :aria-disabled="textareaDisabled"
                    class="chat-composer-input max-h-[calc(1.375rem_*_5)] min-h-[24px] w-full overflow-y-auto break-words whitespace-pre-wrap text-content outline-none empty:before:pointer-events-none empty:before:text-content-subtle empty:before:content-[attr(data-placeholder)] md:max-h-[min(calc(1.375rem_*_10),40vh)]"
                    :class="{
                      'cursor-not-allowed opacity-50': textareaDisabled
                    }"
                    :data-placeholder="$t(composerPlaceholderKey)"
                    :aria-label="$t(composerPlaceholderKey)"
                    @keydown.enter="onKeydownEnter"
                    @beforeinput="onBeforeInput"
                    @input="onInput"
                    @paste="onPaste"
                    @compositionstart="onCompositionstart"
                    @compositionend="onCompositionend"
                    @mouseup="formatMenu?.checkSelection()"
                    @keyup="formatMenu?.checkSelection()"
                    @blur="formatMenu?.hideMenu()"
                  />
                  <!-- Text Format Menu -->
                  <TextFormatMenu
                    ref="formatMenu"
                    :input-element="input"
                    @format-applied="onFormatApplied"
                  />
                </At>

                <!--
                    Thumbnails are outlined with a `border`, not a `ring`.
                    Both were tried and both failed, in opposite directions.
                    A plain ring paints OUTSIDE the box, and these fill their
                    parent exactly, so the extra pixel fell outside this
                    strip — which is a scroll container, so it was clipped and
                    the outline looked cut off. `ring-inset` then vanished
                    entirely: an inset box-shadow is painted above the
                    background but BELOW content, and on a replaced element
                    like `<img>` the `object-cover` bitmap covers it. A border
                    sits on the border box itself, and with border-box sizing
                    the image content insets to make room, so it can neither
                    overflow nor be painted over.
                  -->
                <div
                  v-if="
                    isLoadingFiles ||
                    images.length > 0 ||
                    isLoadingVideo ||
                    videos.length > 0
                  "
                  class="flex gap-3 overflow-x-auto pt-2 pr-2"
                >
                  <!-- Loading indicator for file processing -->
                  <div
                    v-if="isLoadingFiles"
                    class="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-lg border border-border bg-surface-muted"
                  >
                    <Loader2 class="h-5 w-5 animate-spin text-content-subtle" />
                  </div>

                  <TransitionGroup
                    v-if="images.length > 0"
                    tag="div"
                    class="relative flex gap-3"
                    enter-from-class="opacity-0 scale-90"
                    enter-active-class="transition-[opacity,transform] duration-150 ease-out"
                    leave-active-class="transition-opacity duration-150 ease-out absolute"
                    leave-to-class="opacity-0"
                    move-class="transition-transform duration-200 ease-out"
                  >
                    <div
                      v-for="(image, index) in images"
                      :key="image.id"
                      class="group relative h-12 w-12 shrink-0"
                    >
                      <img
                        :src="image.thumbnailUrl"
                        class="absolute bottom-0 left-0 h-full w-full cursor-pointer rounded-lg border border-border bg-surface-muted object-cover"
                        @click="openImageLightbox(index)"
                      />
                      <button
                        class="absolute -top-1.5 -right-1.5 flex h-5 w-5 cursor-pointer items-center justify-center rounded-full bg-black/70 text-white shadow-raised transition-[opacity,transform,background-color] duration-200 ease-out hover:scale-110 hover:bg-black/90"
                        :class="
                          isMobile
                            ? 'opacity-100'
                            : 'pointer-events-none opacity-0 group-hover:pointer-events-auto group-hover:opacity-100'
                        "
                        @click="removeImageAtIndex(index)"
                      >
                        <X :size="12" :stroke-width="2.5" />
                      </button>
                    </div>
                  </TransitionGroup>

                  <!-- Loading indicator for video processing -->
                  <div
                    v-if="isLoadingVideo"
                    class="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-lg border border-border bg-surface-muted"
                  >
                    <Loader2 class="h-5 w-5 animate-spin text-content-subtle" />
                  </div>

                  <TransitionGroup
                    v-if="videos.length > 0"
                    tag="div"
                    class="relative flex gap-3"
                    enter-from-class="opacity-0 scale-90"
                    enter-active-class="transition-[opacity,transform] duration-150 ease-out"
                    leave-active-class="transition-opacity duration-150 ease-out absolute"
                    leave-to-class="opacity-0"
                    move-class="transition-transform duration-200 ease-out"
                  >
                    <div
                      v-for="(video, index) in videos"
                      :key="video.id"
                      class="group relative h-12 w-12 shrink-0"
                    >
                      <img
                        :src="video.thumbnailUrl"
                        class="absolute bottom-0 left-0 h-full w-full cursor-pointer rounded-lg border border-border bg-surface-muted object-cover"
                        @click="openVideoLightbox(index)"
                      />
                      <div
                        class="pointer-events-none absolute inset-0 flex items-center justify-center"
                      >
                        <div
                          class="flex h-5 w-5 items-center justify-center rounded-full bg-black/60"
                        >
                          <Play class="h-3 w-3 fill-white text-white" />
                        </div>
