<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { RoomType } from '../classes/room'
import { getConfig } from '../runtime/config'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import formatCurrency, { Currency } from '../utils/formatCurrency'

const props = defineProps<{
  isLinePayEnabled: boolean
  isStripeEnabled: boolean
  isPaypalEnabled: boolean
}>()

const CURRENCIES = ['TWD', 'USD']

const config = getConfig()
const imkit = useImkitStore()
const vfm = useVfm()

const roomToken = ref('')
const amount = ref(0)
const displayAmount = ref('')
const currentCurrency = ref(CURRENCIES[0])
const remark = ref('')

const uid = computed(() => getUid())
const chatRoomId = computed(() => imkit.selectedRoomId)
const room = computed(() => imkit.rooms[chatRoomId.value])
const isLinePayVisible = computed(
  () => currentCurrency.value === CURRENCIES[0] && props.isLinePayEnabled
)
const isStripeVisible = computed(() => props.isStripeEnabled)
const isPaypalVisible = computed(() => props.isPaypalEnabled)
const isValid = computed(() => {
  const isPaymentEnabled =
    props.isLinePayEnabled || props.isStripeEnabled || props.isPaypalEnabled
  const isCurrencyValid =
    {
      [CURRENCIES[0]]:
        props.isLinePayEnabled ||
        props.isStripeEnabled ||
        props.isPaypalEnabled,
      [CURRENCIES[1]]: props.isStripeEnabled || props.isPaypalEnabled
    }[currentCurrency.value] || false
  return isPaymentEnabled && isCurrencyValid && amount.value > 0
})

const onClickSubmit = async () => {
  if (room.value.type === RoomType.Direct) {
    const payerId = room.value.memberIds.find(
      (member: string) => member !== uid.value
    )
    if (!payerId) return
    const payer = imkit.users[payerId]
    if (!payer) return

    await config.callbacks.onPaymentRequestCreated(
      roomToken.value,
      chatRoomId.value,
      payer.nickname,
      payer.id,
      String(amount.value),
      currentCurrency.value,
      remark.value
    )
  }

  vfm.closeAll()
}

const onAmountInput = (e: Event) => {
  const target = e.target as HTMLInputElement | null
  const value = target?.value ?? ''
  const numeric = value.replace(/[^\d.]/g, '')
  amount.value = parseFloat(numeric || '0')
  displayAmount.value = formatCurrency(
    amount.value,
    currentCurrency.value as Currency
  )
}

const onAmountBlur = () => {
  displayAmount.value = formatCurrency(
    amount.value,
    currentCurrency.value as Currency
  )
}

onMounted(() => {
  const roomTags = room.value.roomTags ?? []
  if (roomTags.length > 0) {
    roomToken.value = roomTags[0]
  }
})
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg border border-border shadow-raised min-w-[400px] max-w-full p-5 flex flex-col gap-4 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <!--
      Left-aligned title, no close ✕ — the shape ConfirmDialogShell sets for
      every other dialog in the app. Escape and overlay-click still dismiss
      (vue-final-modal defaults both to true and nothing here overrides them),
      which is what the ✕ was providing.
    -->
    <div class="flex flex-col">
      <h1 class="text-xl font-semibold text-content">
        {{ $t('paymentSendRequestMessage') }}
      </h1>
      <div class="mt-5 flex w-full items-end">
        <p class="mr-2 text-xl font-medium text-content">
          {{ currentCurrency }}
        </p>
        <input
          type="text"
          :value="displayAmount"
          placeholder="0"
          class="hide-spin mb-[-8px] block h-full w-full px-[12px] py-0 !text-[40px] font-medium outline-none"
          @blur="onAmountBlur"
          @input="onAmountInput"
        />
      </div>
      <div class="mt-5 flex w-full flex-col">
        <p class="mr-2 text-xs font-normal text-content-muted">
          {{ $t('currency') }}
        </p>
        <select
          v-model="currentCurrency"
          class="mt-1 mb-4 h-[34px] w-full appearance-none rounded-md border-none bg-surface-muted px-[10px] text-content outline-none"
        >
          <option
            v-for="currency in CURRENCIES"
            :key="currency"
            :value="currency"
          >
            {{ currency }}
          </option>
        </select>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="mr-2 text-xs font-normal text-content-muted">
          {{ $t('paymentSupportedMethods') }}
        </p>
        <div class="mt-1 flex">
          <img
            v-if="isLinePayVisible"
            class="mr-4"
            src="../assets/linepay_logo.png"
            alt="LINE Pay Logo"
          />
          <img
            v-if="isStripeVisible"
            class="mr-4"
            src="../assets/stripe_logo.png"
            alt="Stripe Logo"
          />
          <img
            v-if="isPaypalVisible"
            class="mr-4"
            src="../assets/paypal_logo.png"
            alt="Paypal Logo"
          />
        </div>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="mr-2 text-xs font-normal text-content-muted">
          {{ $t('paymentRequestMessage') }}
        </p>
        <input
          v-model="remark"
          class="mt-1 h-[40px] gap-[10px] rounded-md bg-surface-muted px-[12px] py-[10px] outline-none"
          type="text"
          :placeholder="$t('paymentInputMessageOptional')"
          maxlength="100"
        />
      </div>
    </div>
    <div class="flex items-center justify-end gap-2">
      <button
        class="inline-flex h-10 w-auto cursor-pointer items-center justify-center rounded-md bg-surface-muted px-4 text-base font-medium text-content transition-colors hover:bg-border"
        @click="vfm.closeAll()"
      >
        {{ $t('cancel') }}
      </button>
      <button
        :disabled="!isValid"
        class="inline-flex h-10 w-auto cursor-pointer items-center justify-center rounded-md bg-accent px-4 text-base font-medium text-white transition-colors disabled:cursor-not-allowed disabled:opacity-50"
        @click="onClickSubmit"
      >
        {{ $t('submit') }}
      </button>
    </div>
  </vue-final-modal>
</template>

<style scoped>
.hide-spin::-webkit-inner-spin-button,
.hide-spin::-webkit-outer-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.hide-spin {
  -moz-appearance: textfield;
  appearance: textfield;
}
</style>
