import type Room from '../../classes/room'
import type { ImkitState } from './state'

export const roomsInSelectedFolder = (state: ImkitState): Room[] => {
  const { selectedFolderId } = state
  const selectedFolder = state.folders[selectedFolderId]
  if (!selectedFolder) return []
  return selectedFolder.roomIds
    .map((id: string) => state.rooms[id])
    .filter((room): room is Room => {
      if (!room || room.isPinchatAi) return false
      if (state.roomTag) {
        return room.roomTags.includes(state.roomTag)
      }
      return true
    })
    .sort((a, b) =>
      !!a.pref?.sticky === !!b.pref?.sticky
        ? b.updatedAt - a.updatedAt
        : a.pref?.sticky
          ? -1
          : 1
    )
}
