import 'vue-final-modal/style.css'
import './style.css'

import * as jose from 'jose'
import { createPinia, type Pinia } from 'pinia'
import { App } from 'vue'
import { ModalsContainer } from 'vue-final-modal'
import Vue3TouchEvents, { type Vue3TouchEventsOptions } from 'vue3-touch-events'
import Config from './classes/config'
import Message from './classes/message'
import User from './classes/user'
import ChatRoom from './components/ChatRoom.vue'
import ChatRoomInfo from './components/ChatRoomInfo.vue'
import RoomList from './components/RoomList.vue'
import i18n from './i18n'
import { initRuntime } from './runtime'
import { getSharedVfm } from './runtime/vfm'
import { initImkitStore } from './stores/imkit'
import { version } from './version'
import { installWebviewBridge } from './webviewBridge'

type Options = { config: Config }
export { palette } from './classes/styles'
export type { DesignPalette, PaletteSeeds } from './classes/styles'
export { useDesignPalette } from './composables/useDesignPalette'
export { getLocale, setLocale } from './i18n'
export { clearSignedUrlCache } from './runtime/signedUrlStore'
export { useImkitStore, type ImkitStore } from './stores/imkit'
export { ChatRoom, ChatRoomInfo, Message, ModalsContainer, RoomList, User }

export const installAppLevel = (app: App) => {
  // Shared across every app this SDK installs into — see runtime/vfm.ts for
  // why a per-app vfm loses modals in the multi-app web-component build.
  app.use(getSharedVfm())
  app.use(i18n)
  app.use<Vue3TouchEventsOptions>(Vue3TouchEvents, { disableClick: false })
}

export default {
  install: async (app: App, options: Options & { store?: unknown }) => {
    console.log('IMKIT version:', version)
    if ('store' in options) {
      console.warn(
        '[imkit] options.store is no longer accepted; SDK owns its Pinia store internally.'
      )
    }
    const { config } = options
    const existingPinia = app.config.globalProperties.$pinia as
      Pinia | undefined
    const pinia = existingPinia ?? createPinia()
    if (!existingPinia) {
      app.use(pinia)
    }
    let uid = ''
    try {
      const { id, _id } = jose.decodeJwt(config.token)
      const rawUid = id ?? _id
      if (typeof rawUid === 'string') {
        uid = rawUid
      }
    } catch (e) {
      console.log(e)
    }
    initRuntime(config, uid)
    initImkitStore(pinia)
    installWebviewBridge()
    installAppLevel(app)
  }
}
