import { shallowReactive } from 'vue'
import type Config from '../classes/config'

let _config: Config | null = null

export const setConfig = (c: Config): void => {
  // shallowReactive so components reading getConfig().settings / .styles through
  // computed() react to post-mount setConfig() updates — parity with the old
  // Vuex bundle, where config lived in reactive store state. Shallow on purpose:
  // only the top-level keys are tracked, so nested objects (firebaseConfig,
  // callbacks) are handed to firebase / host code raw, not as proxies.
  // applyRuntimeConfigPatch therefore reassigns whole top-level objects
  // (settings/styles/callbacks) rather than mutating them in place.
  _config = shallowReactive(c)
}

export const getConfig = (): Config => {
  if (!_config) throw new Error('imkit runtime not initialized (config)')
  return _config
}

export const _resetConfigForTests = (): void => {
  _config = null
}
