<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import { joinFileName } from '../utils/fileName'
import { highlightHtmlText } from '../utils/highlightHtmlText'
import Message, {
  FileMessage,
  MessageType,
  MixedMessage,
  TextMessage
} from './../classes/message'
import AvatarModal from './AvatarModal.vue'
import MessageQuotedPreview from './MessageQuotedPreview.vue'
const props = defineProps<{ message: TextMessage }>()
const imkit = useImkitStore()
const config = getConfig()
const replyMessage = computed((): Message | undefined => {
  if (!props.message.replyId) return undefined
  return imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.message.replyId)
})
const replyMessageSender = computed(() => {
  const reply = replyMessage.value
  if (!reply) return null
  return imkit.users[reply.senderId]
})
const isIncoming = computed(() => props.message.isIncoming)
const linkPreviews = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  return urls.map((url) => imkit.linkPreviews[url]).filter((l) => l)
})
const loadingLinkPreviewUrls = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  const loadingSet = imkit.loadingLinkPreviews as Set<string>
  return urls.filter((url) => loadingSet.has(url) && !imkit.linkPreviews[url])
})
const description = computed((): string => {
  if (!replyMessage.value) return ''
  if (replyMessage.value.type === MessageType.Text) {
    return (replyMessage.value as TextMessage).string
  } else if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).string
  } else if (replyMessage.value.type === MessageType.File) {
    const file = replyMessage.value as FileMessage
    return joinFileName(file.fileName, file.fileExtension)
  } else if (
    replyMessage.value.type === MessageType.Image ||
    replyMessage.value.type === MessageType.Video ||
    replyMessage.value.type === MessageType.Sticker
  ) {
    const { t } = useI18n()
    const messageTypeName = {
      [MessageType.Image]: t('image'),
      [MessageType.Video]: t('video'),
      [MessageType.Sticker]: t('sticker')
    }
    return messageTypeName[replyMessage.value.type]
  }
  return ''
})
// True when this message points at a replyId but the target isn't in the
// loaded message map — either it was deleted, or it hasn't been fetched.
// Rendered as a greyed, non-clickable line rather than silently omitted.
const replyUnavailable = computed(
  () => !!props.message.replyId && !replyMessage.value
)
const failedLinkPreviewImages = ref(new Set<string>())
const handleLinkPreviewImageError = (url: string) => {
  failedLinkPreviewImages.value = new Set([
    ...failedLinkPreviewImages.value,
    url
  ])
}
const handleMentionClick = (event: MouseEvent) => {
  const target = event.target as HTMLElement
  if (target.tagName === 'SPAN' && target.dataset.uid) {
    const user = imkit.users[target.dataset.uid]
    if (!user) return
    const { open } = useModal({
      component: AvatarModal,
      attrs: {
        url: user.avatarUrl ?? '',
        name: user.nickname ?? ''
      }
    })
    open()
  }
}

const html = computed((): string => {
  const keyword = imkit.messageSearchKeyword
  return highlightHtmlText(props.message.html, keyword)
})
const handleLinkPreviewClick = (url: string) => {
  // url is autolinked from peer-supplied message text. 'noopener,noreferrer'
  // severs window.opener (reverse tabnabbing) and the referrer.
  window.open(url, '_blank', 'noopener,noreferrer')
}
const handleCopy = (event: ClipboardEvent) => {
  const selection = window.getSelection()
  const selectedText = selection?.toString()
  if (selectedText) {
    // User selected specific text, let the browser handle the copy natively
    return
  }
  // No selection, copy the entire message text
  event.preventDefault()
  event.clipboardData?.setData('text/plain', props.message.text)
}
const navigate = () => {
  if (!props.message.replyId) return
  imkit.navigateToMessage(props.message.replyId)
}
</script>

<template>
  <div v-if="message.replyId" class="mb-1.5">
    <MessageQuotedPreview
      :available="!!replyMessage"
      :reply-sender-name="replyMessageSender?.nickname"
      :description="description"
      :is-incoming="isIncoming"
      :unavailable="replyUnavailable"
      @navigate="navigate"
    />
  </div>
  <div
    class="prose max-w-none wrap-break-word text-inherit select-none dark:prose-invert pointer-fine:select-text prose-p:leading-5.5 prose-ol:my-0"
    :class="{ 'prose-own': !isIncoming }"
    @click="handleMentionClick"
    @copy="handleCopy"
    v-html="html"
  />
  <div
    v-if="isIncoming && message.translatedText"
    dir="auto"
    class="mt-1 break-words text-content-subtle"
  >
    {{ $t('translation') }}: {{ message.translatedText }}
  </div>
  <div
    v-if="linkPreviews.length > 0 || loadingLinkPreviewUrls.length > 0"
    class="my-1 flex flex-col gap-3"
  >
    <!-- Skeleton loaders for loading link previews. Keep in sync with the
      identical block in MixedMessageContent.vue.

      Filled with `border`, the hairline token. These blocks sit INSIDE a
      message bubble (`--color-message`, a translucent white wash over the
      canvas, or `--color-message-own`), so that is what they are measured
      against.

      Judge this by perceptual distance, NOT contrast ratio. Contrast ratio
      measures luminance for text legibility; these are flat filled bars, and
      going by it is how this setting went wrong twice. CIELAB dE against the
      bubble:

                        light/recv  light/own  dark/recv  dark/own
        border-strong      45.4        33.8       47.7       47.2
        content-faint      34.4        21.8       32.3       32.2
        border             13.6         5.3        9.6        9.3
        surface-muted       3.6        14.8        2.2        9.3

      The original `surface-muted` was called invisible at "1.03-1.34:1". By
      dE it is only genuinely too faint in ONE cell — a dark received bubble,
      2.2 — but that reading sent the next revision to `content-subtle`, a
      TEXT token, and then to `border-strong`. Both were reported as too dark,
      correctly: at dE 33-48 they are solid bars, not a placeholder.

      `border` clears 5.3 everywhere — comfortably perceptible — while being
      3-9x quieter. It does not meet a 3:1 contrast floor and is not meant to:
      a skeleton is transient scaffolding, not content or a control, it
      pulses, and the thing it stands in for arrives within a second.

      Keep in sync with the identical block in MixedMessageContent.vue. -->
    <div
      v-for="url in loadingLinkPreviewUrls"
      :key="url"
      class="flex animate-pulse items-stretch justify-center gap-2"
    >
      <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-border" />
      <div
        class="align-center flex grow flex-col justify-center gap-1.5 overflow-hidden"
      >
        <div class="h-4 w-3/4 rounded-md bg-border" />
        <div class="h-3 w-1/2 rounded-md bg-border" />
      </div>
      <div class="my-auto h-12 w-12 shrink-0 rounded-sm bg-border" />
    </div>
    <!-- Loaded link previews -->
    <div
      v-for="linkPreview in linkPreviews"
      :key="linkPreview.url"
      data-testid="link-preview-card"
      class="flex cursor-pointer items-stretch justify-center gap-2"
      @click="handleLinkPreviewClick(linkPreview.url)"
    >
      <!-- Loaded-state accent bar. Was a raw `bg-blue-300`, which could not
        track a customer palette or colour mode. `accent-vivid` is the
        right half of the accent split for this: it is the foreground/fill
        role (links, spinners, rings), whereas `accent` is the
        background-under-white-text role — and `accent` also fails here
        anyway, at 2.26:1 worst. This element is a childless 2px stripe with
        no foreground of its own, and carries no `dark:` partner, so the only
        pair to keep whole is stripe-vs-bubble: `accent-vivid` measures
        the 3:1 non-text floor against both bubble roles. -->
      <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-accent-vivid" />
      <div
        class="align-center flex grow flex-col justify-center gap-0.5 overflow-hidden"
      >
        <div class="ellipsis text-base font-bold">
          {{ linkPreview.title }}
        </div>
        <div class="multiline-ellipsis text-xs">
          {{ linkPreview.description || $t('tapOpen') }}
        </div>
      </div>
      <img
        v-if="
          linkPreview.images.length > 0 &&
          !failedLinkPreviewImages.has(linkPreview.url)
        "
        :src="linkPreview.images[0]"
        alt=""
        class="my-auto h-12 w-12 shrink-0 rounded-sm object-cover"
        @error="handleLinkPreviewImageError(linkPreview.url)"
      />
      <div
        v-else-if="failedLinkPreviewImages.has(linkPreview.url)"
        data-testid="link-preview-image-placeholder"
        aria-hidden="true"
        class="my-auto h-12 w-12 shrink-0 rounded-sm bg-content-subtle"
      />
    </div>
  </div>
</template>
<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

/* `--color-accent-vivid` is blue-500 in light and blue-400 in dark — the exact
   pair this rule used to hand-write. The token flips itself, so no dark-mode
   rule is needed. Never reintroduce one as `:global(.dark) :deep(...)`: that
   form compiles to a bare `.dark { ... }` selector (see ReactionList.vue). */
:deep(a) {
  color: var(--color-accent-vivid);
  text-decoration: underline;
  word-break: break-all;
}
:deep(code:not(pre code) a) {
  color: inherit;
  text-decoration: none;
}

/* Own-message bubbles pair `bg-message-own` with `text-message-own-content`
 * (MessageCell.vue), a pair verified for contrast against each other — but
 * `--color-accent-vivid` above was never verified against `message-own` and
 * can fall under the 4.5:1 AA floor on a light sent bubble. Rather than
 * add a new token, links inside an own bubble join the same verified pair by
 * inheriting the bubble's own text colour; the underline still marks them as
 * links. `.prose-own` is set by TextMessageContent.vue's `isIncoming` check. */
.prose-own :deep(a) {
  color: inherit;
}

/* Same reasoning for @-mention spans (emitted by the autolinker in
 * classes/message.ts carrying `text-accent-vivid font-semibold`).
 * accent-vivid clears AA against every incoming bubble but measures 3.85:1
 * against some customer-derived `bg-message-own` values, so inside an own bubble
 * the mention joins the verified `text-message-own-content` pair instead.
 * Colour can no longer distinguish it there — the span's `font-semibold`
 * does. */
.prose-own :deep(span[data-uid]) {
  color: inherit;
}

:deep(p:first-child:last-child) {
  margin-bottom: 0;
}

:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* Remove backticks added by Tailwind Typography prose */
:deep(code)::before,
:deep(code)::after {
  content: none;
}

/* GitHub-style inline code (exclude code blocks inside <pre>) */
:deep(code:not(pre code)) {
  display: inline;
  padding: 0.15em 0.3em;
  border-radius: 6px;
  background-color: rgba(175, 184, 193, 0.2);
  font-size: 85%;
  line-height: inherit;
  white-space: break-spaces;
  word-wrap: break-word;
  vertical-align: bottom;
}
/* No token covers this pair, so both halves stay raw — that is the sanctioned
   alternative to half-migrating. Anchored on `.prose` (this component's own
   element) rather than written as `:global(.dark) :deep(...)`, so Vue keeps the
   scope attribute on a real element instead of emitting a bare `.dark` rule. */
.dark .prose :deep(code:not(pre code)) {
  background-color: rgba(110, 118, 129, 0.4);
}
</style>
