// Join a parsed file name with its optional extension for display/download.
// parseFileName returns fileExtension: undefined for extensionless files (L06),
// so interpolating `${name}.${ext}` directly renders the literal "undefined"
// (or a trailing dot once escaped). Coalesce here so callers stay simple.
export const joinFileName = (
  fileName: string,
  fileExtension: string | undefined
): string => (fileExtension ? `${fileName}.${fileExtension}` : fileName)
