<script setup lang="ts">
import { computed, inject, ref, watch } from 'vue'
import Callbacks from '../../../classes/callbacks'
import Message from '../../../classes/message'
import { getConfig } from '../../../runtime/config'
import { useImkitStore } from '../../../stores/imkit'
import SubmitSvg from '../../svgs/SubmitSvg.vue'

defineOptions({
  inheritAttrs: false
})

const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const inputValue = ref('')
const emailFormatError = ref(false)
// A completed request keeps showing the submitted value — the backend's
// completing edit writes it back into content.text — and only drops the
// caret by disabling the input (issue #87). The edit arrives via socket
// after the host's POST succeeds, so watch the flip to sync the value in
// case this instance survives the content swap.
inputValue.value = props.content.text
watch(
  () => props.content.completed,
  (completed) => {
    if (completed) {
      emailFormatError.value = false
      if (props.content.text) {
        inputValue.value = props.content.text
      }
    }
  }
)
const imkit = useImkitStore()
const callbacks = computed((): Callbacks => getConfig().callbacks)
const messageId = inject('messageId') as string
const message = computed((): Message | undefined =>
  imkit.messageMultiLists.get(imkit.selectedRoomId)?.main?.map.get(messageId)
)
const handle = () => {
  if (!message.value) return
  if (props.content.completed) {
    return
  }
  if (props.content.subtype === 'email') {
    const regex = /^\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$/
    if (!regex.test(inputValue.value)) {
      emailFormatError.value = true
      return
    }
    emailFormatError.value = false
  }
  callbacks.value.flexMessageInputSubmitted(message.value, inputValue.value)
}
</script>

<template>
  <!--
    `bg-surface`, not the `bg-white` this shipped with: white is white in both
    modes, so a fixed white plate sat on the dark canvas in dark mode with
    `content` (near-white) text inside it.

    `rounded-md`, the declared level for inputs. A pill was tried, on the
    argument that it matches the two search fields — the app's other
    single-line inputs — and reverted: those sit in chrome, this one sits
    INSIDE a message card, where a fully round field reads as a foreign control
    dropped into the conversation rather than part of the card. Bare `rounded`,
    which this shipped with, resolves to Tailwind's stock 4px and is not one of
    the four declared levels at all.

    The border is not decoration. This field sits inside a flex card that
    follows the bubble direction, so on a RECEIVED message its plate is
    `message` — the same white as the field. Fill cannot define it there; the
    hairline can.
  -->
  <div
    class="flex items-center gap-2 rounded-md border border-border bg-surface p-2"
    v-bind="$attrs"
  >
    <input
      v-model="inputValue"
      class="w-full bg-transparent pl-2 text-base text-content placeholder-content-subtle focus:outline-none"
      :disabled="content.completed"
      :placeholder="$t(`Request.Message.${content.subtype}.placeholder`)"
      @keypress.enter="handle"
    />
    <!-- Completed: a bare checkmark — no green submit bg, and no
         disabled-gray backdrop layered under the icon (issue #87). -->
    <button
      :disabled="content.completed || !inputValue"
      class="rounded-md p-1.5"
      :class="
        content.completed
          ? ''
          : inputValue
            ? 'bg-accent'
            : 'cursor-not-allowed bg-surface-muted'
      "
      @click="handle"
    >
      <SubmitSvg v-if="!content.completed" />
      <img
        v-else
        width="20"
        height="20"
        src="../../../assets/icon_check.png"
        alt=""
      />
    </button>
  </div>
  <!--
    `danger-vivid`, the foreground role. This was a hardcoded #fe4d4f, which is
    not even the `danger` seed (#d2402c) — so this validation message was a
    different red from every other error in the product.
  -->
  <div v-if="emailFormatError" class="mt-2 text-base text-danger-vivid">
    {{ $t('emailFromatError') }}
  </div>
</template>
