<script setup lang="ts">
import { computed } from 'vue'
import { useVfm } from 'vue-final-modal'
import { formatBytes } from '../utils/formatBytes'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

// Props
const props = defineProps<{
  fileSizeLimit: number
}>()
const vfm = useVfm()
const limitText = computed(() => formatBytes(props.fileSizeLimit))
</script>

<template>
  <ConfirmDialogShell
    :title="$t('fileSizeLimitTitle', 'File too large')"
    :confirm-label="$t('confirm')"
    confirm-variant="primary"
    @confirm="vfm.closeAll()"
  >
    {{ $t('fileSizeLimitMessage', [limitText]) }}
  </ConfirmDialogShell>
</template>
