import axios, {
  AxiosHeaders,
  type AxiosInstance,
  type AxiosRequestConfig
} from 'axios'
import { useVfm } from 'vue-final-modal'
import UnauthorizedModal from '../components/UnauthorizedModal.vue'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { getImkitStore } from '../stores/imkit'
import { getConfig } from './config'
import { clearSignedUrlCache } from './signedUrlStore'
import { resolveToken } from './token'

enum RequestType {
  Start,
  End
}

let _axios: AxiosInstance | null = null

function handleRequest(type: RequestType, config: AxiosRequestConfig) {
  const { url } = config
  const path = url?.split('?')[0]
  if (!path) return
  getImkitStore().mergeInto('isRequesting', {
    [path]: type === RequestType.Start ? new Date() : null
  })
}

const refetchToken = async (): Promise<boolean> => {
  // Host-provided token provider: ask it to mint a fresh token. On success the
  // 401 request can be retried with the new credential.
  if (getConfig().getToken && (await resolveToken(true))) return true
  // No provider, or the provider could not produce a token: the session is dead.
  if (localStorage.getItem('imkit-token')) {
    localStorage.removeItem('imkit-token')
  }
  const vfm = useVfm()
  vfm.closeAll()
  const { open } = useModal({
    component: UnauthorizedModal
  })
  open()
  return false
}

// Merge IMKIT auth/locale headers onto the caller's own headers instead of
// replacing them, so caller-supplied headers (trace ids, idempotency keys, etc.)
// survive onto both the initial request and the 401 retry.
const applyAuthHeaders = (headers: unknown, token: string): AxiosHeaders => {
  const next = AxiosHeaders.from(
    headers as ConstructorParameters<typeof AxiosHeaders>[0]
  )
  next.set('IM-Authorization', token)
  next.set('IM-Client-Key', getConfig().clientKey)
  next.set('x-timezone', Intl.DateTimeFormat().resolvedOptions().timeZone)
  next.set('accept-language', navigator.language)
  return next
}

export const initAxios = (): AxiosInstance => {
  const instance = axios.create({
    baseURL: getConfig().domain,
    timeout: 10000
  })
  instance.interceptors.request.use(
    async (requestConfig) => {
      handleRequest(RequestType.Start, requestConfig)
      const token = await resolveToken()
      requestConfig.headers = applyAuthHeaders(requestConfig.headers, token)
      return requestConfig
    },
    (error) => {
      handleRequest(RequestType.End, error.config)
      return Promise.reject(error)
    }
  )
  instance.interceptors.response.use(
    (response) => {
      handleRequest(RequestType.End, response.config)
      return response
    },
    async (error) => {
      handleRequest(RequestType.End, error.config)
      if (error.response?.status === 401) {
        const tokenBefore = getConfig().token
        const refreshed = await refetchToken()
        const tokenAfter = getConfig().token
        if (tokenBefore !== tokenAfter) {
          clearSignedUrlCache()
        }
        // Only retry when a fresh token was actually minted. A dead session
        // (no provider, or provider returned nothing) shows the unauthorized
        // modal and must surface the original 401 instead of re-firing it.
        if (refreshed) {
          error.config.headers = applyAuthHeaders(
            error.config.headers,
            tokenAfter
          )
          return axios.request(error.config)
        }
      }
      return Promise.reject(error)
    }
  )
  _axios = instance
  return instance
}

export const getAxios = (): AxiosInstance => {
  if (!_axios) throw new Error('imkit runtime not initialized (axios)')
  return _axios
}

export const _resetAxiosForTests = (): void => {
  _axios = null
}
