<script setup lang="ts">
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import Message, {
  MessageType,
  SystemMessage,
  TextMessage
} from './../classes/message'
const props = defineProps<{ message: Message }>()
const users = computed(() => useImkitStore().users)
const { t } = useI18n()
const text = computed(() => {
  const senderNickname = users.value[props.message.senderId]?.nickname
  switch (props.message.type) {
    case MessageType.Recall:
      if (props.message.senderId === getUid()) {
        return t('youUnsentMessage')
      }
      return t('someoneUnsentMessage', [senderNickname])
    case MessageType.JoinRoom:
      return t('someoneJoinedTheChat', [senderNickname])
    case MessageType.LeaveRoom:
      return t('someoneLeftTheChat', [senderNickname])
    case MessageType.AddMember:
      return t('someoneInvited', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.DeleteMember:
      return t('someoneKicked', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.AddMembers:
      return t('someoneInvited', [
        senderNickname,
        (props.message as SystemMessage).members
          .map((member) => member.nickname)
          .join(', ')
      ])
    case MessageType.Announcement:
      return (props.message as TextMessage).text
    default:
      return ''
  }
})
</script>

<template>
  <!--
    A caption pill wants more horizontal than vertical padding and a radius
    that suits its height. `px-2 py-1.5` was nearly the reverse (6px
    vertical vs 8px horizontal, too close to equal for a wide caption), and
    `rounded-lg` (16px) on the resulting ~29px-tall pill was under half that
    height — close enough to a capsule to read as an almost-there rounded
    rect rather than a deliberate pill, which is what looked wrong.
    `px-3 py-1` shrinks the pill to `text-xs`'s 16.8px line-height + 8px
    vertical padding (~25px measured), and `rounded-full` — the radius scale
    already has this exact case; nothing between `lg` and `full` fits a
    height this variable — clamps to a true capsule at any height rather
    than needing to be re-tuned if the row's font metrics ever shift.
  -->
  <!--
    Top margin only, on the WRAPPER — the pill itself carries none.

    It used to be `my-1.5` on the pill, which looked symmetric and was not.
    Every other row in the message list spaces itself with a top margin and
    no bottom one (MessageCell's bubble wrapper is `mt-2` / `mt-1`), so the
    pill's own 6px bottom margin stacked with the NEXT row's top margin
    instead of overlapping it: 6px above, 6+8=14px below. That the next row
    is always a group head — and so always the larger `mt-2` — follows from
    messageLinkedList.ts skipping system messages when it builds groups,
    which leaves the following message with no group to belong to.

    `mt-2` matches a group head, so the gap above and the gap below are both
    8px and come from the same rule.
  -->
  <div class="mt-2 flex items-center justify-center">
    <div
      class="rounded-full bg-surface-sunken px-3 py-1 text-xs text-content-muted"
    >
      {{ text }}
    </div>
  </div>
</template>

<style scoped></style>
