import { createVfm } from 'vue-final-modal'

type Vfm = ReturnType<typeof createVfm>

// vue-final-modal keeps a single module-global "active vfm", (re)assigned by
// every createVfm() call, and `useModal()` resolves through that global
// whenever it runs outside a component setup context — which is every click
// handler in this SDK that opens a modal (tags, delete room, move out, ...).
//
// The web-component build mounts one Vue app per element, so giving each app
// its own vfm made modal ownership depend on mount order: selecting a room
// mounts <imkit-chat-room-info>, whose app deliberately renders no
// ModalsContainer (the page has a sibling <imkit-modals-container>), and from
// that moment every modal was queued into a vfm nothing renders. The dialog
// silently never appeared and open()'s promise never settled — no error, no
// modal (dashboard issue #122). Unmounting the info panel didn't recover:
// the global still pointed at the discarded app's vfm.
//
// One vfm shared by every app makes the queue and the container that drains it
// the same object regardless of which element mounted last.
let sharedVfm: Vfm | undefined

export const getSharedVfm = (): Vfm => {
  if (!sharedVfm) sharedVfm = createVfm()
  return sharedVfm
}

// Called when the last web-component element unmounts, alongside the shared
// Pinia/store teardown, so a later remount starts with an empty modal queue.
export const resetSharedVfm = (): void => {
  sharedVfm = undefined
}
