<script setup lang="ts">
import { computed } from 'vue'
import { escapeCssUrl } from '../../../utils/escapeCssUrl'
const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const size = computed((): string => {
  const size: string = props.content.size
  const sizes: { [size: string]: string } = {
    xxs: '12px',
    xs: '13px',
    sm: '14px',
    md: '16px',
    lg: '19px',
    xl: '22px',
    xxl: '29px',
    '3xl': '35px',
    '4xl': '48px',
    '5xl': '74px'
  }
  return sizes[size] ?? '16px'
})
// Escape backslash and double-quote so the url() value cannot break out of the
// CSS string and inject arbitrary declarations (M61).
const backgroundImageUrl = computed((): string =>
  escapeCssUrl(props.content.url ?? '')
)
</script>

<template>
  <span
    :style="{
      overflow: 'hidden',
      background: 'no-repeat center',
      backgroundSize: 'contain',
      backgroundImage: backgroundImageUrl,
      width: size,
      height: size
    }"
  />
</template>

<style scoped></style>
