export type Currency = 'USD' | 'TWD'

const formatCurrency = (value?: number, currency?: Currency) => {
  if (!value || !currency) {
    return '0'
  }
  const localeMap = {
    USD: 'en-US',
    TWD: 'zh-TW'
  }

  const locale = localeMap[currency] || 'en-US'

  return new Intl.NumberFormat(locale, {
    style: 'decimal'
  }).format(value)
}

export default formatCurrency
