import { readonly, ref } from 'vue'

const supported = ref(false)
const visible = ref(false)
const endSequence = ref(0)
const transitionEndListeners = new Set<() => void>()

export const hostKeyboardTransition = {
  supported: readonly(supported),
  visible: readonly(visible),
  endSequence: readonly(endSequence)
}

export const applyHostCapabilities = (
  payload: Record<string, unknown>
): void => {
  if (typeof payload.keyboardTransitionEnd === 'boolean') {
    supported.value = payload.keyboardTransitionEnd
  }
  if (typeof payload.keyboardVisible === 'boolean') {
    visible.value = payload.keyboardVisible
  }
}

export const applyKeyboardTransitionEnd = (
  payload: Record<string, unknown>
): void => {
  if (typeof payload.visible === 'boolean') {
    visible.value = payload.visible
  }
  endSequence.value += 1
  transitionEndListeners.forEach((listener) => listener())
}

export const addKeyboardTransitionEndListener = (
  listener: () => void
): (() => void) => {
  transitionEndListeners.add(listener)
  return () => transitionEndListeners.delete(listener)
}

export const _resetHostKeyboardTransitionForTests = (): void => {
  supported.value = false
  visible.value = false
  endSequence.value = 0
  transitionEndListeners.clear()
}
