import * as VueI18n from 'vue-i18n'

import deDE from './locales/de-DE.json'
import enUS from './locales/en-US.json'
import esES from './locales/es-ES.json'
import frFR from './locales/fr-FR.json'
import jaJP from './locales/ja-JP.json'
import koKR from './locales/ko-KR.json'
import ptPT from './locales/pt-PT.json'
import roRO from './locales/ro-RO.json'
import thTH from './locales/th-TH.json'
import viVN from './locales/vi-VN.json'
import zhCN from './locales/zh-CN.json'
import zhTW from './locales/zh-TW.json'

const messages = {
  'de-DE': deDE,
  'en-US': enUS,
  'es-ES': esES,
  'fr-FR': frFR,
  'ja-JP': jaJP,
  'ko-KR': koKR,
  'pt-PT': ptPT,
  'ro-RO': roRO,
  'th-TH': thTH,
  'vi-VN': viVN,
  'zh-CN': zhCN,
  'zh-TW': zhTW
}
const resolveLocale = (): keyof typeof messages => {
  if (typeof navigator === 'undefined' || !navigator.language) {
    return 'en-US'
  }
  const requested = navigator.language
  // Exact BCP-47 match first (e.g. ja-JP).
  if (requested in messages) {
    return requested as keyof typeof messages
  }
  // Then fall back to any locale sharing the primary subtag (e.g. fr-CA -> fr-FR)
  // so translated languages are not dropped to English over a region mismatch.
  const primarySubtag = requested.split('-')[0]
  // Chinese needs script-aware resolution: a bare primary-subtag match returns
  // whichever zh-* key is declared first (zh-CN), silently handing Traditional
  // regions (TW/HK/MO) Simplified. Resolve by script/region instead.
  if (primarySubtag === 'zh') {
    const tag = requested.toLowerCase()
    const isTraditional =
      tag.includes('hant') ||
      tag.includes('-tw') ||
      tag.includes('-hk') ||
      tag.includes('-mo')
    return isTraditional ? 'zh-TW' : 'zh-CN'
  }
  const primaryMatch = (
    Object.keys(messages) as (keyof typeof messages)[]
  ).find((available) => available.split('-')[0] === primarySubtag)
  return primaryMatch ?? 'en-US'
}

/**
 * 語言代碼映射表：將簡化的語言代碼映射到完整的語言代碼
 */
const localeMap: Record<string, string> = {
  'zh-TW': 'zh-TW',
  'zh-CN': 'zh-CN',
  en: 'en-US',
  ja: 'ja-JP',
  ko: 'ko-KR',
  fr: 'fr-FR',
  // 也支持完整格式
  'en-US': 'en-US',
  'ja-JP': 'ja-JP',
  'ko-KR': 'ko-KR',
  'fr-FR': 'fr-FR',
  'de-DE': 'de-DE',
  'es-ES': 'es-ES',
  'pt-PT': 'pt-PT',
  'ro-RO': 'ro-RO',
  'th-TH': 'th-TH',
  'vi-VN': 'vi-VN'
}

/**
 * 標準化語言代碼：將簡化的語言代碼轉換為完整的語言代碼
 * @param locale 語言代碼（可以是簡化或完整格式）
 * @returns 完整的語言代碼，如果不支持則返回原值
 */
function normalizeLocale(locale: string): string {
  // 如果已經是完整格式且在 messages 中，直接返回
  if (locale in messages) {
    return locale
  }
  // 嘗試從映射表中查找
  const normalized = localeMap[locale]
  if (normalized && normalized in messages) {
    return normalized
  }
  // 如果都不匹配，返回原值（會在使用時被驗證）
  return locale
}

/**
 * 獲取初始語言設置
 * 優先順序：URL 參數 > localStorage > 瀏覽器語言 > 預設 'en-US'
 */
function getInitialLocale(): string {
  // 1. 從 URL 參數獲取
  if (typeof window !== 'undefined') {
    const urlParams = new URLSearchParams(window.location.search)
    const urlLocale = urlParams.get('locale') || urlParams.get('lang')
    if (urlLocale) {
      const normalized = normalizeLocale(urlLocale)
      if (normalized in messages) {
        return normalized
      }
    }

    // 2. 從 localStorage 獲取
    try {
      const storedLocale = localStorage.getItem('imkit-locale')
      if (storedLocale) {
        const normalized = normalizeLocale(storedLocale)
        if (normalized in messages) {
          return normalized
        }
      }
    } catch (e) {
      console.warn('Failed to read locale from localStorage', e)
    }

    // 3. 從瀏覽器語言獲取（script-aware：涵蓋繁體中文區域 TW/HK/MO）
    return resolveLocale()
  }

  // 4. 預設值
  return 'en-US'
}

const i18n = VueI18n.createI18n({
  legacy: false,
  locale: getInitialLocale(),
  messages: messages
})

/**
 * 設置語言
 * @param locale 語言代碼，例如 'zh-TW', 'en-US', 'en', 'ja', 'ko', 'fr'
 */
export function setLocale(locale: string): void {
  const normalized = normalizeLocale(locale)
  if (normalized in messages) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    i18n.global.locale.value = normalized as any
    // 保存到 localStorage（保存標準化後的完整格式）
    try {
      localStorage.setItem('imkit-locale', normalized)
    } catch (e) {
      console.warn('Failed to save locale to localStorage', e)
    }
  } else {
    console.warn(
      `Locale "${locale}" is not supported. Available locales:`,
      Object.keys(messages)
    )
  }
}

/**
 * 獲取當前語言
 */
export function getLocale(): string {
  return i18n.global.locale.value
}

export default i18n
