<script setup lang="ts">
import Toggle from '@vueform/toggle'
import {
  Ban,
  ChevronLeft,
  Folder as FolderIcon,
  LogOut,
  MoreHorizontal,
  Pin,
  PinOff,
  Plus,
  Search,
  ShieldCheck,
  Sparkles,
  UserMinus,
  Volume2,
  VolumeX,
  X
} from 'lucide-vue-next'
import { computed, ref, watch } from 'vue'
// `useImkitModal`, not vue-final-modal's `useModal`: the SDK shares one vfm
// across element apps. Importing both names collides.
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { getConfig } from '../runtime/config'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import { deriveTagPalette } from '../utils/tagColor'
import fetchParams from '../utils/url'
import { RoomType } from './../classes/room'
import AddToFolderModal from './AddToFolderModal.vue'
import AvatarView from './AvatarView.vue'
import BlockUserConfirmModal from './BlockUserConfirmModal.vue'
import HeaderDivider from './HeaderDivider.vue'
import LeaveGroupConfirmModal from './LeaveGroupConfirmModal.vue'
import MenuItemContent from './MenuItemContent.vue'
import MoveOutConfirmModal from './MoveOutConfirmModal.vue'
import TagsModal from './TagsModal.vue'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

const imkit = useImkitStore()
const config = getConfig()
const room = computed(() => imkit.rooms[imkit.selectedRoomId])
const chatbotEnabled = ref(true)
const users = computed(() => imkit.users)
const uid = computed(() => getUid())
const settings = computed(() => config.settings)
// Agent-only room-management surfaces (quick actions + folder). Defaults to
// true when a host has not said otherwise, so existing embeds are unchanged.
const roomManagementEnabled = computed(
  () => settings.value.roomManagementEnabled !== false
)
const showCustomRoomInfoIframe = computed(() => {
  return config.settings.customRoomInfoIframeURL
})
const customRoomInfoIframeURL = computed(() => {
  const base = config.settings.customRoomInfoIframeURL
  if (!base) return ''
  const url = new URL(base, window.location.href)
  url.searchParams.set('roomId', String(imkit.selectedRoomId))
  return url.toString()
})
const blockedUsers = computed(() => imkit.blockedUsers)

const canMoveOut = computed(() => {
  return room.value.type === RoomType.Group
})

// The AI summary and the tag editor are agent-side affordances — the same
// predicate that gates the chatbot switch below. A visitor must not see the
// merchant's summary of their own conversation, nor an "add tag" control.
const isAgentView = computed(
  () => room.value.isSuperuser || uid.value.endsWith('_sub')
)
const aiSummary = computed(() => room.value.pref?.summary?.trim() ?? '')
// Tag prefs are scoped to the link / enterpoint token, which the first
// roomTag carries. Resolution order mirrors TagsModal so that removing a tag
// here writes to the same pref bucket the dialog adds it to.
const tagRoomToken = computed(
  () => fetchParams().get('roomTag') ?? room.value.roomTags?.[0] ?? ''
)

// Each removal posts the *whole* tag list, and the store only reflects the
// removal once the POST resolves. Two quick clicks read the same pre-request
// list and the second write resurrects the tag the first one removed, so the
// removals are serialized and each one re-reads the list when its turn comes.
// (pinchat-only: the mainline panel has no per-chip remove, only the dialog.)
let removeTagQueue: Promise<unknown> = Promise.resolve()
const removeTag = (tag: string) => {
  // Pin the target at click time. The body below runs only after the previous
  // POST settles, and `room` is a computed over `selectedRoomId` — by then the
  // agent may have switched rooms, or the room may be gone from the store.
  const roomId = room.value.id
  const roomTag = tagRoomToken.value
  const removal = removeTagQueue.then(() => {
    const pref = imkit.rooms[roomId]?.pref
    const current = pref?.tags ?? []
    if (!current.includes(tag)) return
    const nextTagColors = { ...(pref?.tagColors ?? {}) }
    delete nextTagColors[tag]
    return imkit.updateRoomPrefs({
      roomId,
      roomTag,
      prefs: {
        tags: current.filter((existing: string) => existing !== tag),
        tagColors: nextTagColors
      }
    })
  })
  // A failed removal must not stall the queue behind a rejected promise; the
  // rejection still propagates to this call's own returned promise.
  removeTagQueue = removal.catch(() => {})
  return removal
}

const openTagsModal = async () => {
  // TagsModal snapshots the tag list once at setup and posts that whole list
  // back on confirm, so opening it while a removal is still in flight lets it
  // write back the tag the removal just dropped — the same race the queue
  // above exists to close, reached through the other entry point.
  await removeTagQueue

  const { open } = useModal({
    component: TagsModal,
    attrs: {
      roomId: room.value.id,
      roomTag: tagRoomToken.value
    }
  })
  open()
}
const back = () => {
  imkit.$patch({ isRoomInfoVisible: false })
}
// --- Block / unblock.
//
// Both entry points — the direct-room quick action and the group member
// row's `⋯` menu — route through these two functions, so the confirmation
// rule and the failure handling cannot drift between them.
//
// These were fire-and-forget (`imkit.blockUser({...})`, no await, no catch).
// The store action awaits the POST and only THEN commits to state, so a
// rejection left the panel unchanged, showed nothing, and escaped as an
// unhandled rejection — the user believed they had blocked someone and had
// not. Now the flag is flipped optimistically so the control responds at
// once (that flip is the only success feedback this codebase can give: there
// is no toast/snackbar surface, and adding a global one would touch public
// API), and a failure puts the flag back and raises the confirm modal's own
// error branch.
const openBlockErrorDialog = (uid: string) => {
  const { open } = useModal({
    component: BlockUserConfirmModal,
    attrs: { roomId: room.value.id, uid, mode: 'error' as const }
  })
  open()
}

// Blocking is confirmed; unblocking is not. Unblocking is the correction
// path for a mistaken block, so a dialog in front of it would make the
// mistake harder to undo than to make.
const blockUser = (uid: string) => {
  const { open } = useModal({
    component: BlockUserConfirmModal,
    attrs: { roomId: room.value.id, uid }
  })
  open()
}

const unblockUser = async (uid: string) => {
  const wasBlocked = imkit.blockedUsers[uid]
  delete imkit.blockedUsers[uid]
  try {
    await imkit.unblockUser({ roomId: room.value.id, uid })
  } catch (error) {
    console.error('Failed to unblock user:', error)
    if (wasBlocked) {
      imkit.blockedUsers[uid] = wasBlocked
    }
    openBlockErrorDialog(uid)
  }
}

// The one other person in a direct room. Used by the block quick action,
// which replaces the member row that a direct room no longer renders.
const directCounterpartId = computed(() => {
  if (room.value.type !== RoomType.Direct) return ''
  return room.value.memberIds.find((id: string) => id !== uid.value) ?? ''
})
const isDirect = computed(() => room.value.type === RoomType.Direct)
// Not simply `!isDirect`: a `roomType: 'custom'` room resolves to Direct unless
// `extra.roomType` says group (see `Room.isCustomType`), and every PinChat room
// is custom, so `type` alone hid the members for the whole branch.
//
// Keyed off origin rather than `memberIds.length > 1` because member arrays
// arrive asynchronously — a length test makes the section appear a beat late,
// or not at all on a slow fetch.
const showMembers = computed(() => !isDirect.value || room.value.isCustomType)
// `!room.isSuperuser` and `!uid.endsWith('_sub')` were dropped in the redesign
// and restored: leaving is a one-way door (this SDK has no rejoin path), so a
// superuser must not be able to walk out of their own room, and agent
// sub-accounts are managed from the admin side.
const canLeaveGroup = computed(
  () =>
    room.value.isGroup &&
    !room.value.isSuperuser &&
    settings.value.showLeaveRoomButton &&
    !uid.value.endsWith('_sub')
)
const isCounterpartBlocked = computed(
  () => !!blockedUsers.value[directCounterpartId.value]
)
const toggleBlock = () => {
  const target = directCounterpartId.value
  if (!target) return
  if (isCounterpartBlocked.value) {
    unblockUser(target)
  } else {
    blockUser(target)
  }
}
const isRequesting = computed(
  () => !!imkit.isRequesting[`/blockStatus/room/${room.value.id}`]
)

const confirmMoveOut = (memberId: string) => {
  const { open } = useModal({
    component: MoveOutConfirmModal,
    attrs: {
      memberIdToMoveOut: memberId,
      roomId: room.value.id
    }
  })

  open()
}

const confirmLeaveGroup = () => {
  const { open } = useModal({
    component: LeaveGroupConfirmModal,
    attrs: { roomId: room.value.id, memberId: uid.value }
  })
  open()
}
const shouldShowBlockControl = (memberId: string) => {
  if (isRequesting.value) {
    return false
  }
  if (memberId === uid.value) {
    return false
  }
  // pinchat-only: agent sub-accounts and the bot sender are never blockable.
  if (memberId.endsWith('_sub')) {
    return false
  }
  if (memberId === 'BOT') {
    return false
  }
  // On this branch this is the ONLY branch that runs: custom rooms resolve to
  // Direct and every PinChat room is custom, so member rows take this early
  // `true` and never reach the superuser check below. If block should be
  // superuser-gated for custom rooms the way it is for real groups, change
  // THIS line — the pre-redesign behaviour was to allow it, so it is left as
  // is.
  if (room.value.type === RoomType.Direct) {
    return true
  }
  return room.value.isSuperuser
}
const onChatbotStateChange = async (enabled: boolean) => {
  chatbotEnabled.value = enabled
  const ok = await config.callbacks.onChatbotStateChange(room.value.id, enabled)
  if (!ok) {
    chatbotEnabled.value = !enabled
  }
}
watch(
  room,
  () => {
    chatbotEnabled.value = (room.value.extra.isOpenBot as boolean) ?? false
  },
  { immediate: true }
)

const displayMemberIds = computed(() => {
  const seenIds = new Set<string>()
  const result: string[] = []

  for (const memberId of room.value.memberIds) {
    const user = users.value[memberId]
    if (user?.clientType === RoomType.Group) {
      for (const subMemberId in user.memberIds) {
        if (!seenIds.has(subMemberId) && users.value[subMemberId]) {
          seenIds.add(subMemberId)
          result.push(subMemberId)
        }
      }
    } else if (!seenIds.has(memberId)) {
      seenIds.add(memberId)
      result.push(memberId)
    }
  }

  return result
})

// --- Quick actions: pin, mute, in-room search. `加成員` (add member) from
// the reference has no home here — there is no addMembers/inviteMembers
// action in the store (only `removeMembers`), so it is left out rather than
// built or stubbed. See round8-report.md.
const isSticky = computed(() => room.value.pref?.sticky ?? false)
const toggleSticky = async () => {
  await imkit.updateRoomPrefs({
    roomId: room.value.id,
    prefs: { sticky: !isSticky.value }
  })
}
const toggleMute = () => {
  imkit.toggleNotification(room.value.id)
}
const openInRoomSearch = () => {
  imkit.$patch({
    isRoomInfoVisible: false,
    isSearchInRoomMode: true
  })
}

// --- Organize: tags + folder. Both reuse the same modals RoomCell.vue's
// action menu already opens, just triggered from this panel instead.
// `openTagsModal` is NOT redefined here: the merged copy above serializes
// removals and passes the link/enterpoint `roomTag`, which this one did not.
const roomTags = computed(() => room.value.pref?.tags ?? [])
const roomTagColors = computed(() => room.value.pref?.tagColors ?? {})
const tagChipStyle = (tagHex: string) => {
  const palette = deriveTagPalette(tagHex)
  return {
    '--tag-bg': palette.lightBg,
    '--tag-fg': palette.lightFg,
    '--tag-bg-dark': palette.darkBg,
    '--tag-fg-dark': palette.darkFg
  }
}

// A room lives in at most one folder client-side, and there is no reverse
// index from roomId -> folderId (mirrors AddToFolderModal.vue's own
// currentFolderId computed).
const currentFolder = computed(() => {
  for (const id of imkit.sortedFolderIds) {
    const folder = imkit.folders[id]
    if (folder && folder.roomIds.includes(room.value.id)) {
      return folder
    }
  }
  return null
})
const openFolderModal = () => {
  const { open } = useModal({
    component: AddToFolderModal,
    attrs: { roomId: room.value.id }
  })
  open()
}
</script>

<template>
  <!-- sm:h-full: as a web component the flex stretch lands on the host
       element, not this root — without an explicit height the drawer
       collapses to content height and leaves a dead band below (issue #98).
       The custom-element mount chain (host → mountPoint → .imkit-element-ce)
       is 100%-height throughout. -->
  <div
    class="absolute inset-0 flex w-full flex-col bg-surface sm:relative sm:h-full sm:w-[350px] sm:max-w-[350px] sm:min-w-[350px]"
  >
    <div
      data-testid="room-info-header"
      class="relative flex h-(--imkit-header-height) items-center gap-3 px-4"
    >
      <!-- Overlaid border, not a real `border-b` — see HeaderDivider.vue. -->
      <HeaderDivider />
      <ChevronLeft
        :size="24"
        class="cursor-pointer text-content-muted sm:hidden"
        @click="back"
      />
      <div class="flex-1 text-base font-semibold text-content">
        {{ $t('roomInfo') }}
      </div>
      <button
        type="button"
        data-testid="room-info-close"
        class="hidden cursor-pointer items-center justify-center rounded-full p-1 text-content-muted hover:bg-surface-hover sm:flex"
        :aria-label="$t('close')"
        @click="back"
      >
        <X :size="20" />
      </button>
    </div>

    <div class="flex min-h-0 flex-1 flex-col overflow-auto pb-3">
      <!-- idblock -->
      <!--
        `pt-6`, not `pt-2`. This block sits directly under the panel header's
        overlaid rule, so 8px left the avatar almost against a hard boundary —
        an inside-a-component value where a between-groups one belongs (see
        CLAUDE.md's spacing note). 24px reads as the identity block starting,
        rather than as the header having thick bottom padding.
      -->
      <div
        class="flex flex-col items-center gap-2 px-4 pt-6 pb-3.5 text-center"
      >
        <!--
          72px maps the reference's `.idblock .avatar` (72px). The camera
          edit badge is skipped: there is no room-avatar-upload action in
          the store, and the reference's editable room name (`h4`) is also
          plain text here for the same reason — no room-rename action
          exists. See round8-report.md.
        -->
        <!-- Cover when set, group glyph as the fallback — see the note on
             the same expression in RoomCell.vue for why a group uses
             `coverUrl` rather than `avatars[0]`. -->
        <avatar-view
          :url="room.isGroup ? room.coverUrl : room.avatars[0].url"
          :name="room.isGroup ? (room.displayName ?? '') : room.avatars[0].name"
          :is-group="room.isGroup"
          class="h-18 w-18 text-xl"
        />
        <h4 class="text-xl font-bold text-content">{{ room.displayName }}</h4>
        <!--
          The panel used to show `createdAt` and `updatedAt` here. Both are
          gone by decision, and the `createdAt` / `updatedAt` locale keys are
          DELIBERATELY LEFT IN all twelve files with no reference in src/.
          Do not "tidy" them away, and do not read them as evidence of a
          dropped feature — an unused key plus a dangling `dayjs` import is
          exactly what flagged the redesign's accidental removal of this block,
          so the note exists to stop the next reader repeating that inference.
          The `dayjs` import IS gone, since it had no other caller.
        -->
      </div>

      <!--
        qa: quick actions. Agent-only — pin, mute, block and in-room search
        organise an agent's own inbox and mean nothing to a visitor with one
        conversation. See `roomManagementEnabled` in classes/settings.ts.
      -->
      <div
        v-if="roomManagementEnabled"
        class="flex justify-center gap-2.5 px-4 pb-4"
      >
        <button
          type="button"
          data-testid="room-info-pin"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleSticky"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              isSticky
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component :is="isSticky ? PinOff : Pin" :size="20" />
          </span>
          {{ isSticky ? $t('unpin') : $t('pin') }}
        </button>
        <!--
          Mute is a TOGGLE, so its pill carries the same engaged fill as pin
          above and block below (`bg-accent` + white glyph when on, the
          `surface-muted` resting pill when off). It used to be the only
          toggle in this row without one: the pill stayed byte-identical in
          both states and the entire on/off signal rested on the glyph
          swapping Volume2 <-> VolumeX and the label swapping mute <->
          unmute. Two small, easily-missed channels — sitting directly
          beside a pinned row that DOES fill — is what made this read as
          having no switch to it.

          Search, the remaining button in this row, deliberately keeps the
          unconditional resting pill: it opens in-room search rather than
          holding an on/off state, so an engaged fill would be claiming a
          state it does not have.
        -->
        <button
          type="button"
          data-testid="room-info-mute"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleMute"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              room.muted
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component :is="room.muted ? VolumeX : Volume2" :size="20" />
          </span>
          {{ room.muted ? $t('unmute') : $t('mute') }}
        </button>
        <!--
          `!showMembers`, not `isDirect`: block needs exactly one entry point.
          Rooms with a member list carry it in the row's `⋯` menu; rooms
          without one would otherwise have no route to it. Both call the same
          toggleBlock/blockUser/unblockUser pair.

          Sits between mute and search so the row reads
          置頂 / 靜音 / 封鎖 / 搜尋.

          A toggle like mute: the icon and label follow the current state.
        -->
        <!--
          Routed through `shouldShowBlockControl` rather than carrying its own
          clauses: this entrance was added with only `!isRequesting`, so it
          skipped the BOT and `_sub` cases the member-row route deliberately
          made unreachable. `directCounterpartId` is just "the other member",
          which can be either.

          The truthiness check stays — `shouldShowBlockControl('')` returns
          true in a direct room, so an empty counterpart would render a button
          that blocks nobody.
        -->
        <button
          v-if="
            !showMembers &&
            directCounterpartId &&
            shouldShowBlockControl(directCounterpartId)
          "
          type="button"
          data-testid="room-info-block"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleBlock"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              isCounterpartBlocked
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component
              :is="isCounterpartBlocked ? ShieldCheck : Ban"
              :size="20"
            />
          </span>
          {{ isCounterpartBlocked ? $t('unblock') : $t('block') }}
        </button>
        <!--
          This is a SECOND entrance to in-room search; ChatRoom's header button
          is the other, and it carries `settings.searchInRoomEnabled`. Added
          without it, so the host flag stopped being a real switch — the flag
          was still referenced elsewhere, which is why an unreferenced-flag
          scan did not catch it.
        -->
        <button
          v-if="settings.searchInRoomEnabled"
          type="button"
          data-testid="room-info-search"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="openInRoomSearch"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full bg-surface-muted text-accent hover:bg-accent-subtle"
          >
            <Search :size="20" />
          </span>
          {{ $t('search') }}
        </button>
        <!--
          Host-supplied quick actions, last in the row. PinChat puts its
          chat-history export here; it used to be a full-width primary button
          in `afterChatbotSwitch`, below the chatbot switch.

          Sizing is the HOST's job — nothing here constrains the slot — but a
          cell that does not match `w-15` will not line up with the built-ins.
          The row has space for one: four 60px cells with 10px gaps come to
          270px against 288px of usable width in a 320px panel, and the SDK's
          own build already renders four here whenever the block control is
          visible. A FIFTH does not fit (340px), so a host adding one of these
          should check whether the block control can appear in its rooms.

          Inside the `roomManagementEnabled` row on purpose: a host action left
          behind on its own after the built-ins are hidden would read as a
          stray control rather than as part of a row.
        -->
        <slot name="quickActions"></slot>
      </div>

      <!--
        sect: chatbot — pinchat-only. `room.extra.bindBot` is what says this
        room has a bot at all; without it the switch would offer to toggle
        something that does not exist.
      -->
      <div
        v-if="room.extra.bindBot && isAgentView"
        class="border-t border-border py-4"
      >
        <!--
          Two lines under the heading, from the design reference: what the
          switch is doing NOW (accent) and what flipping it would do (muted).
          The single static line this replaced could only describe one of the
          two states, so it was wrong to read whenever the bot was already off.

          The heading is `text-base`, DELIBERATELY unlike the caption-sized
          uppercase headings every other section uses. This block is the only
          control in the panel — everything else is data or a link to a dialog
          — and it is the thing an agent comes here to flip. It reads as the
          odd one out because it is one. An earlier round made it match the
          others and that was the wrong correction; the round after that tried
          `text-xl` and overshot, since the scale has no 16-17px step between.

          One caption under it, not two. A second line spelling out what
          flipping the switch would do was dropped: the toggle's own position
          already says how to change it, and the state line says where it
          stands. Merging the two into one line was rejected first — zh-TW is
          the SHORTEST locale at 26 characters and fr-FR the longest at 99, so
          a merged line fits here and wraps to three or four lines there, which
          loses exactly the state-vs-consequence split the merge was meant to
          tidy.
        -->
        <h5 class="mx-4 mb-2 flex items-center justify-between gap-2">
          <span class="text-base font-semibold text-content">
            {{ $t('chatbotSwitch') }}
          </span>
          <!--
            `Toggle` is styled through a `classes` prop, not a class attribute,
            so the design-token codemod cannot reach it — these had to be moved
            by hand. Was `bg-green-500` on / `#e5e7eb`+`#3f3f46` off, i.e. a
            fixed green that ignored the customer's brand seed and a pair of
            hardcoded greys that ignored the colour mode. `accent` follows the
            seed; `border-strong` is the same off-state fill the room-list
            toolbar's dark-mode switch uses.
          -->
          <Toggle
            :value="chatbotEnabled"
            :classes="{
              toggleOn: 'bg-accent !border-accent',
              toggleOff: 'bg-border-strong !border-border-strong'
            }"
            @change="onChatbotStateChange"
          />
        </h5>
        <p class="mx-4 text-xs text-accent-vivid">
          {{ chatbotEnabled ? $t('chatbotStateOn') : $t('chatbotStateOff') }}
        </p>
      </div>

      <!--
        The 8px band between sections is a deliberate device (CLAUDE.md /
        round8-room-settings.md) — a thick `surface-muted` divider, not a
        1px border, so the panel reads as grouped cards without any card
        element existing.
      -->
      <!--
        sect: AI summary — pinchat-only, and agent-side only: this is the
        merchant's own summary of the conversation, which the visitor must
        never see. Same `isAgentView` gate as the chatbot switch below.

        Shaped like every other section in this panel — `border-t` rule, small
        uppercase heading — rather than as a standalone card. tribo's version of
        this section makes the same point: a bare icon-and-label row was the
        only one of its kind here and read as belonging to a different screen.

        It differs from tribo's in having a body. tribo opens the summary as an
        overlay, so its section is a heading plus an `open` action and nothing
        else; pinchat has no such drawer and shows the text inline.

        The Sparkles glyph is `accent-vivid` — the foreground role — against the
        heading's `content-subtle`, so it stays legible on this plane in both
        colour modes. Same size and token as tribo's, so the feature is
        recognisably the same one across customers.
      -->
      <div
        v-if="isAgentView && aiSummary"
        data-testid="room-info-ai-summary"
        class="border-t border-border py-4"
      >
        <h5 class="mx-4 mb-2 flex items-center gap-1.5">
          <span
            class="text-xs font-bold tracking-wider text-content-subtle uppercase"
          >
            {{ $t('aiSummary') }}
          </span>
          <Sparkles :size="13" class="text-accent-vivid" aria-hidden="true" />
        </h5>
        <!--
          `content`, not `content-subtle`: the summary is what an agent opens
          this section to read, and it was the only body copy in the panel
          rendered muted.
        -->
        <p class="mx-4 text-base whitespace-pre-line text-content">
          {{ aiSummary }}
        </p>
        <!--
          Provenance: the summary is generated and should not be read as the
          merchant's own note.

          `content-subtle`, not `content-faint`. This is text, and faint
          measures 2.58:1 on the light panel — under the 4.5:1 floor. style.css
          reserves that token for non-text and decorative graphics for exactly
          this reason.
        -->
        <p class="mx-4 mt-2 text-xs text-content-subtle">
          {{ $t('aiSummaryDisclaimer') }}
        </p>
      </div>

      <!--
        Host slot, PUBLIC API — `src/custom-element.ts` projects a consumer's
        `<imkit-chat-room-info>` children here. Documented occupant: the
        dashboard's guest email-notify form. See the slot below for why losing
        one of these is silent.
      -->
      <slot></slot>

      <!--
        sect: tags — split into its own section (was one row shared with
        folder, under a single `organize` heading, itself with a "標籤"
        label — a duplicated label, since the row's own label was ALSO
        "標籤"; that locale key is now deleted from all 12 files rather
        than left as litter). The heading now carries the name and count
        (`標籤(12)`, matching the `成員(2)` convention this panel already
        uses for its members heading, rather than the reference mockup's
        `標籤 12`, so the two headings agree), a `管理標籤` action opens the
        same tags modal the old row's click did, and there is no longer an
        icon + right-aligned-value row underneath: the chips themselves ARE
        the body, wrapping onto as many lines as a room's tag count needs —
        the whole point of this split, since a room can carry well over
        five.
      -->
      <!--
        `isAgentView` (pinchat-only): tags are the merchant's own labelling of
        the conversation, so a visitor must not see them — the same gate as the
        AI summary above. The mainline panel has no such gate because mainline
        has no visitor-side view of this panel.
      -->
      <div v-if="isAgentView" class="border-t border-border py-4">
        <h5 class="mx-4 mb-2 flex items-center justify-between gap-2">
          <span
            class="text-xs font-bold tracking-wider text-content-subtle uppercase"
          >
            {{ $t('tag') }}({{ roomTags.length }})
          </span>
          <button
            type="button"
            data-testid="room-info-tags-manage"
            class="cursor-pointer text-xs font-semibold text-accent-vivid hover:underline"
            @click="openTagsModal"
          >
            {{ $t('manageTag') }}
          </button>
        </h5>
        <div class="flex flex-wrap gap-2 px-4">
          <!--
            pinchat-only: an `×` per chip. The mainline panel removes tags only
            inside TagsModal; pinchat removes them from the panel, and the
            serialized `removeTag` above exists for that entry point. The glyph
            inherits the chip's own derived foreground rather than taking a
            token of its own, so it cannot collide with a customer tag colour.
          -->
          <span
            v-for="tg in roomTags"
            :key="tg"
            data-testid="room-info-tag"
            class="tag-chip flex items-center gap-1 rounded-full py-1 pr-1.5 pl-3 text-xs font-semibold"
            :style="tagChipStyle(roomTagColors[tg])"
          >
            {{ tg }}
            <button
              type="button"
              :aria-label="$t('delete')"
              class="cursor-pointer opacity-70 hover:opacity-100"
              data-testid="room-info-tag-remove"
              @click="removeTag(tg)"
            >
              <X class="h-3 w-3" />
            </button>
          </span>
          <!--
            Dashed outline, from the design reference. This was a soft
            `surface-muted` fill, on the reasoning that a dashed
            `border-strong` outline made the add-chip the heaviest thing in a
            row of pastel fills — `border-strong` is the interactive-outline
            role, pitched at 3:1, which is deliberately harder than any chip.
            That reasoning was about WEIGHT and it still holds, so the dashes
            come back on `border` rather than `border-strong`: the hairline
            divider role, softer than every chip fill beside it.

            The label stays `content-subtle`, which clears the 4.5:1 text
            floor on `panel` across the supported palettes and both colour
            modes. `content-faint` would not — see the AI summary note above.
          -->
          <button
            type="button"
            data-testid="room-info-tags-add"
            class="flex cursor-pointer items-center gap-1 rounded-full border border-dashed border-border px-3 py-1 text-xs font-semibold text-content-subtle hover:border-border-strong hover:text-content"
            @click="openTagsModal"
          >
            <Plus :size="12" />
            {{ $t('add') }}
          </button>
        </div>
      </div>

      <!-- sect: folder — its own single-row section; it holds exactly one
           value, so it keeps the `value ›` shape rather than wrapping.
           Agent-only, same gate as the quick actions above: a visitor has no
           folders to file the conversation into. -->
      <div
        v-if="roomManagementEnabled && !room.isPinchatAi"
        class="border-t border-border py-4"
      >
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-content-subtle uppercase"
        >
          {{ $t('roomPrefFolder') }}
        </h5>
        <button
          type="button"
          data-testid="room-info-folder"
          class="flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-2.5 text-left hover:bg-surface-hover"
          @click="openFolderModal"
        >
          <span
            class="flex h-7.5 w-7.5 flex-none items-center justify-center rounded-md bg-surface-muted text-accent"
          >
            <FolderIcon :size="16" />
          </span>
          <span class="flex-1 truncate text-base text-content">{{
            currentFolder ? currentFolder.name : $t('unclassified')
          }}</span>
          <!--
            Same treatment as the tags section's 管理標籤: both open a dialog,
            so they are one class of action and were styled as two. The chevron
            goes with the grey — it reads as navigation to another screen,
            which is not what either of these does.
          -->
          <span class="text-xs font-semibold text-accent-vivid">
            {{ $t('changeFolder') }}
          </span>
        </button>
      </div>

      <!--
        Host slot, PUBLIC API. Documented occupant: the admin "export chat
        history" button.

        Losing a slot here is SILENT — `reattachSlots()` in custom-element.ts
        does `if (!marker) continue`, so with no `<slot>` Vue renders no marker
        and the consumer's elements are dropped with no error or warning.
        Nothing looks broken; the content is just gone. The redesign did
        exactly that to both slots. Don't remove either without also removing
        the machinery in custom-element.ts.

        Stays before members, which is what custom-element.ts promises
        consumers. The name is only loosely accurate now — it sat right after
        tags back when tags was the last section before members — but it is
        public API.
      -->
      <slot name="afterChatbotSwitch"></slot>

      <!--
        sect: members — multi-party rooms only. In a true direct room the list
        would restate the panel title and nothing else. Dropping it also drops
        the member row's `⋯` menu, which is why block is promoted to a quick
        action above.
      -->
      <div v-if="showMembers" class="border-t border-border py-4">
        <!--
          The reference's `管理成員` (manage members) header link opens a
          separate full members page that does not exist in this SDK, so
          the link is omitted rather than left dangling — matching the
          spec's "omit the link and say so" guidance.
        -->
        <!--
          `成員(2)`, not `2 名成員`. The prose form is already the description
          line under the room avatar; repeating it here made the same sentence
          appear twice in one panel. A section heading wants the label with its
          count, so this composes `members` + the number rather than reusing
          `memberCount`, which keeps all 12 locales working without a new key.
        -->
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-content-subtle uppercase"
        >
          {{ $t('members') }}({{ displayMemberIds.length }})
        </h5>
        <!--
          Not clickable — no click handler on the row itself, only its "..."
          button is. A hover fill here would invite a click that does
          nothing, so this loses the hover half of the cursor/hover rule
          (see HeaderDivider.vue's neighbours in this file for the other
          half: clickable rows/buttons keep `cursor-pointer` explicitly,
          since Tailwind 4 preflight doesn't give `<button>` one).
        -->
        <!--
          `displayMemberIds`, not `room.memberIds` (pinchat-only): a member of
          this room can itself be a group, and its members are the people the
          agent actually talks to. Flattening happens in the computed so the
          count above and the rows below cannot disagree.
        -->
        <div
          v-for="memberId in displayMemberIds"
          :key="memberId"
          class="flex min-h-13 items-center gap-2.5 px-4 py-2.5"
        >
          <avatar-view
            :url="users[memberId]?.avatarUrl ?? ''"
            :name="users[memberId]?.nickname"
            class="h-[38px] w-[38px] text-xs"
          />
          <div class="flex min-w-0 flex-1 flex-col overflow-hidden">
            <span class="truncate text-base font-semibold text-content">{{
              users[memberId]?.nickname
            }}</span>
            <span
              v-if="users[memberId]?.city && users[memberId]?.country"
              class="truncate text-xs text-content-subtle"
            >
              {{ users[memberId]?.city }}, {{ users[memberId]?.country }}
            </span>
          </div>
          <!--
            `!memberId.endsWith('_sub')` was dropped in the redesign. Without
            it a `_sub` row still hides block (`shouldShowBlockControl` rejects
            `_sub` itself) but offers 移出, where the whole menu used to be
            hidden. Agent sub-accounts are managed from the admin side.
          -->
          <template
            v-if="
              settings.showMemberActionMenu &&
              !memberId.endsWith('_sub') &&
              (shouldShowBlockControl(memberId) ||
                (canMoveOut && memberId !== uid))
            "
          >
            <DropdownMenu :modal="false">
              <DropdownMenuTrigger as-child>
                <button
                  type="button"
                  :data-testid="`member-actions-${memberId}`"
                  :aria-label="$t('more')"
                  class="ml-auto flex h-9 w-9 cursor-pointer items-center justify-center rounded-md text-content-muted hover:bg-surface"
                >
                  <MoreHorizontal :size="18" />
                </button>
              </DropdownMenuTrigger>
              <!--
                All three rows go through `MenuItemContent`, like every
                other action menu in the app — they were bare labels, the
                only menu in the app without glyphs. Hand-adding an icon
                here would re-introduce exactly the divergence that
                component exists to make unrepresentable: the glyph's
                colour has to track the item's danger state, and a glyph
                with its own colour class beats the row's inherited one,
                which is how a grey icon beside a red label shipped three
                times (see MenuItemContent.vue's own note).

                Icons are member-scoped, not message-scoped: `UserMinus`
                for removing a member from the group (NOT `Trash2`, which
                means destroy-the-thing and is what the room-list menu uses
                for deleting a room), and the `Ban`/`ShieldCheck` pair for
                block/unblock.
              -->
              <DropdownMenuContent align="end" side="bottom">
                <DropdownMenuItem
                  v-if="canMoveOut && memberId !== uid"
                  @select="confirmMoveOut(memberId)"
                >
                  <MenuItemContent :icon="UserMinus" :label="$t('moveOut')" />
                </DropdownMenuItem>
                <template v-if="shouldShowBlockControl(memberId)">
                  <DropdownMenuItem
                    v-if="blockedUsers[memberId]"
                    @select="unblockUser(memberId)"
                  >
                    <MenuItemContent
                      :icon="ShieldCheck"
                      :label="$t('unblock')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    v-else
                    class="text-danger-vivid focus:text-danger-vivid"
                    @select="blockUser(memberId)"
                  >
                    <MenuItemContent
                      :icon="Ban"
                      :label="$t('block')"
                      :danger="true"
                    />
                  </DropdownMenuItem>
                </template>
              </DropdownMenuContent>
            </DropdownMenu>
          </template>
        </div>
        <!--
          `＋ 新增成員` (add member) from the reference is skipped: no
          addMembers/inviteMembers action exists in the store. See
          round8-report.md.
        -->
      </div>

      <!-- sect danger -->
      <div v-if="canLeaveGroup" class="border-t border-border py-4">
        <!--
          `刪除頻道` (delete channel) from the reference is skipped this
          round: the panel previously exposed no delete/hide-room capability
          at all, so adding one now is new capability for this component,
          not a restyle — even though the store has `deleteRoom` /
          `updateRoomPrefs({ hidden: true })` wired elsewhere (RoomCell.vue's
          DeleteRoomModal.vue, which this round does not own or modify).
          See round8-report.md.
        -->
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-danger-vivid uppercase"
        >
          {{ $t('dangerZone') }}
        </h5>
        <button
          type="button"
          data-testid="leave-group-button"
          class="flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-2.5 text-left hover:bg-surface-hover"
          @click="confirmLeaveGroup"
        >
          <span
            class="flex h-7.5 w-7.5 flex-none items-center justify-center rounded-md bg-surface-muted text-danger-vivid"
          >
            <LogOut :size="16" />
          </span>
          <span class="text-base text-danger-vivid">{{
            $t('leaveGroup')
          }}</span>
        </button>
      </div>

      <iframe
        v-if="showCustomRoomInfoIframe"
        :src="customRoomInfoIframeURL"
        sandbox="allow-scripts allow-same-origin"
        frameborder="0"
      />
    </div>
  </div>
</template>

