/**
 * Web Component (custom element) wrappers around the IMKIT Vue SDK.
 *
 * Exposed elements:
 *   <imkit-chat-room>          — main message thread + input
 *   <imkit-room-list>          — left-pane room list with search/sort
 *   <imkit-chat-room-info>     — right-pane room/member info panel
 *   <imkit-modals-container>   — page-level modal mount point
 *
 * All four share a single Pinia store at the module level. Clicking a room
 * in <imkit-room-list> updates selectedRoomId; the sibling <imkit-chat-room>
 * re-renders, and <imkit-chat-room-info> auto-shows. Modal confirmations
 * (delete room, etc.) get a teleport target via <imkit-modals-container>.
 *
 * Mounted into light DOM (no shadow root) on purpose: SDK overlays teleport
 * into the shared body-level portal host, and shadow-encapsulated styles
 * cannot reach those teleported nodes. Tradeoff: page-level styles can leak
 * in.
 */
import * as jose from 'jose'
import { createPinia, type Pinia } from 'pinia'
import type { App, Component } from 'vue'
import {
  computed,
  createApp,
  defineComponent,
  h,
  markRaw,
  onMounted,
  onUpdated,
  reactive,
  ref,
  watch,
  type VNode
} from 'vue'
import { ModalsContainer } from 'vue-final-modal'
import Callbacks from './classes/callbacks'
import Config from './classes/config'
import Message from './classes/message'
import Settings from './classes/settings'
import Styles from './classes/styles'
import ChatRoom from './components/ChatRoom.vue'
import ChatRoomInfo from './components/ChatRoomInfo.vue'
import NotificationPermissionModal from './components/NotificationPermissionModal.vue'
import RoomList from './components/RoomList.vue'
import { useDesignPalette } from './composables/useDesignPalette'
import { useImkitModal as useModal } from './composables/useImkitModal'
import { setLocale } from './i18n'
import IMKitPlugin, { installAppLevel } from './lib'
import { getConfig } from './runtime/config'
import { stopNotificationSound } from './runtime/notificationSound'
import { getSocket } from './runtime/socket'
import { setStickerBaseUrl } from './runtime/stickerAsset'
import { setUid } from './runtime/uid'
import { resetSharedVfm } from './runtime/vfm'
import { useImkitStore, type ImkitStore } from './stores/imkit'

const CHAT_ROOM_ELEMENT_NAME = 'imkit-chat-room'
const ROOM_LIST_ELEMENT_NAME = 'imkit-room-list'
const CHAT_ROOM_INFO_ELEMENT_NAME = 'imkit-chat-room-info'
const MODALS_CONTAINER_ELEMENT_NAME = 'imkit-modals-container'

// Marker placeholders the wrapper renders at each of RootComp's <slot>
// positions. The mount step then physically moves the host element's
// consumer-rendered children INTO the marker matching their `slot` attribute
// (default when absent) — so e.g. ChatRoomInfo's default slot (guest
// email-notify form) and its `afterChatbotSwitch` named slot (admin export
// button) each receive the right children. Markers carry
// `data-imkit-slot="<name>"` for lookup; the class is for layout only.
const SLOT_MARKER_PREFIX = 'imkit-ce-slot-'
const DEFAULT_SLOT_NAME = 'default'
const slotMarkerClass = (name: string): string => `${SLOT_MARKER_PREFIX}${name}`

const ATTR_TOKEN = 'token'
const ATTR_API_BASE_URL = 'api-base-url'
const ATTR_CLIENT_KEY = 'client-key'
const ATTR_ROOM_ID = 'room-id'
const ATTR_ROOM_TAG = 'room-tag'
const ATTR_THEME = 'theme'
const ATTR_LANG = 'lang'

const COMMON_OBSERVED_ATTRIBUTES = [
  ATTR_TOKEN,
  ATTR_API_BASE_URL,
  ATTR_CLIENT_KEY,
  ATTR_ROOM_TAG,
  ATTR_THEME,
  ATTR_LANG
] as const

const ROOM_AWARE_OBSERVED_ATTRIBUTES = [
  ...COMMON_OBSERVED_ATTRIBUTES,
  ATTR_ROOM_ID
] as const

type AttrName = (typeof ROOM_AWARE_OBSERVED_ATTRIBUTES)[number]

const defaultSettings = (): Settings => ({
  paymentEnabled: false,
  linePayEnabled: false,
  stripeEnabled: false,
  paypalEnabled: false,
  locationInputEnabled: true,
  audioInputEnabled: true,
  fileInputEnabled: true,
  emojiInputEnabled: true,
  stickerInputEnabled: true,
  sendButtonEnabled: true,
  searchInRoomEnabled: true,
  showDirectChatRoomInfoButton: true,
  showGroupChatRoomInfoButton: true,
  autoSelectRoomWhenLoaded: false,
  // The admin chat leads with the room-info panel: clicking a room opens it
  // alongside the conversation instead of making the agent hunt for the header
  // info button (dashboard issue #122).
  autoOpenRoomInfoOnSelect: true,
  customRoomInfoIframeURL: '',
  showLeaveRoomButton: false,
  showMemberActionMenu: true,
  massTextingEnabled: false,
  showDarkModeSwitch: false,
  enableReadReceipt: true,
  linkPreviewEnabled: true,
  fullPageEnabled: false,
  fixedRoomEnabled: false,
  roomManagementEnabled: true,
  agentPresenceEnabled: true,
  pinchatAiEnabled: false
})

const defaultStyles = (): Styles => ({
  incomingMessageCell: '',
  outgoingMessageCell: '',
  roomListUnreadBadge: '',
  chatRoomHeader: '',
  sendButtonEnabled: '',
  sendButtonDisabled: ''
})

// Elements currently mounted. Config callbacks are owned by whichever element
// mounted first (it runs the full IMKitPlugin install), but consumers hold a
// ref to a specific element — usually <imkit-chat-room> — with no way to know
// which one built the config. So callback-driven events fan out to every live
// element, same net behavior as the store-driven events in bridgeStoreEvents.
const liveElements = new Set<HTMLElement>()
const dispatchToLiveElements = (eventName: string, detail: unknown): void => {
  for (const el of liveElements) {
    el.dispatchEvent(new CustomEvent(eventName, { detail }))
  }
}

const defaultCallbacks = (): Callbacks => ({
  onMessageReceived: () => {},
  onMessageSent: () => {},
  // The in-chat customer-info form (FlexMessageInputComponent) and CSAT rating
  // (FlexMessageRatingComponent) delegate submission to these callbacks — the
  // SDK never posts the value itself. The host page owns the API call, so
  // surface them as DOM events for it to handle.
  flexMessageInputSubmitted: (message: Message, value: string) => {
    dispatchToLiveElements('flex-message-input-submitted', { message, value })
  },
  flexMessageRatingSubmitted: (message: Message, rating: string) => {
    dispatchToLiveElements('flex-message-rating-submitted', { message, rating })
  },
  onChatbotStateChange: async () => true,
  onPaymentRequestCreated: async () => {},
  onPaymentDetailFetched: () =>
    Promise.reject(new Error('onPaymentDetailFetched not configured')),
  onPaymentDetailUrlGenerated: () =>
    Promise.reject(new Error('onPaymentDetailUrlGenerated not configured'))
})

const buildConfig = (
  attrs: Partial<Record<AttrName, string>>,
  overrides: Partial<Config>
): Config => ({
  domain: attrs[ATTR_API_BASE_URL] ?? '',
  clientKey: attrs[ATTR_CLIENT_KEY] ?? '',
  token: attrs[ATTR_TOKEN] ?? '',
  translationApiKey: '',
  // Baked in at build time (.env.production / .env.local). A browser key —
  // must stay referer-unrestricted (REST Geocoding rejects referer-restricted
  // keys); secure via Google Cloud API restrictions + quotas instead.
  mapApiKey: import.meta.env.VITE_MAPS_API_KEY ?? '',
  firebaseConfig: null,
  firebaseVapidKey: undefined,
  settings: defaultSettings(),
  styles: defaultStyles(),
  callbacks: defaultCallbacks(),
  ...overrides
})

// ---------------------------------------------------------------------------
// Shared store across element instances.
//
// First element to mount creates the singleton AND runs the full
// IMKitPlugin install (builds axios + socket, initializes the Pinia store,
// and registers per-app pieces on its own Vue app).
// Subsequent elements reuse the singleton store and call only
// `installAppLevel(app)` for their own Vue app, avoiding duplicate sockets.
//
// A refcount tracks live elements; when it drops to zero we tear down the
// socket and clear the singleton so a future remount starts fresh.
// ---------------------------------------------------------------------------

let sharedPinia: Pinia | undefined
let sharedStore: ImkitStore | undefined
let sharedStoreInitialized = false
let sharedRefcount = 0

const getOrCreateSharedPinia = (): Pinia => {
  if (!sharedPinia) sharedPinia = createPinia()
  return sharedPinia
}

const getOrCreateSharedStore = (pinia: Pinia): ImkitStore => {
  if (!sharedStore) sharedStore = useImkitStore(pinia)
  return sharedStore
}

const releaseSharedStore = (): void => {
  sharedRefcount = Math.max(0, sharedRefcount - 1)
  if (sharedRefcount > 0 || !sharedStore) return
  stopNotificationSound()
  try {
    getSocket().disconnect()
  } catch {
    /* ignore */
  }
  sharedPinia = undefined
  sharedStore = undefined
  sharedStoreInitialized = false
  // Drop the shared modal queue with the store; a later remount installs a
  // fresh vfm instead of inheriting modals left over from the old page.
  resetSharedVfm()
}

const decodeUid = (token: string): string => {
  try {
    const { id, _id } = jose.decodeJwt(token)
    const rawUid = id ?? _id
    return typeof rawUid === 'string' ? rawUid : ''
  } catch (e) {
    console.log(e)
    return ''
  }
}

const applyRuntimeConfigPatch = (config: Partial<Config>): void => {
  try {
    const current = getConfig()
    const patch: Partial<Config> = { ...config }
    // Deep-merge the nested config objects so a partial setConfig({ settings:
    // {...} }) preserves the other default keys instead of replacing the whole
    // object. Reassigning the top-level key (vs mutating in place) is also what
    // triggers the shallowReactive runtime config.
    if (config.settings) {
      patch.settings = { ...current.settings, ...config.settings }
    }
    if (config.styles) {
      patch.styles = { ...current.styles, ...config.styles }
    }
    if (config.callbacks) {
      patch.callbacks = { ...current.callbacks, ...config.callbacks }
    }
    Object.assign(current, patch)
  } catch {
    return
  }
  if (typeof config.token === 'string') {
    setUid(decodeUid(config.token))
  }
}

const getRuntimeToken = (): string | undefined => {
  try {
    return getConfig().token
  } catch {
    return undefined
  }
}

const reconnectSocket = (): void => {
  try {
    const socket = getSocket()
    socket.disconnect()
    socket.connect()
  } catch {
    /* runtime is not initialized yet */
  }
}

// Offline-push permission flow, ported from MainView.vue's
// ensureNotificationPermissionFlow (the standalone-app root the web-component
// build doesn't use). MUST be called from a component setup() so useModal /
// useImkitStore resolve the per-app vue-final-modal + Pinia context.
//
// Gated on firebaseConfig + firebaseVapidKey: a host that doesn't configure
// push gets no prompt. The host (e.g. the PinChat dashboard) sets these via
// setConfig AFTER mount, so we watch the shallowReactive runtime config rather
// than reading it once — top-level keys are tracked, so the watcher fires when
// the host patches them in. Runs at most once per element (the `handled` guard),
// matching v1 where the flow fired a single time on chat-list mount.
const setupNotificationPermissionFlow = (): void => {
  const imkit = useImkitStore()
  const { open: openNotificationPermissionModal } = useModal({
    component: NotificationPermissionModal
  })
  let handled = false
  const run = async (): Promise<void> => {
    if (handled) return
    if (typeof window === 'undefined' || typeof Notification === 'undefined') {
      return
    }
    const config = getConfig()
    if (!config.firebaseConfig || !config.firebaseVapidKey) return
    handled = true
    // User already dismissed the prompt this device — don't nag again.
    if (localStorage.getItem('notification-permission-skipped') === 'true') {
      return
    }
    if (Notification.permission === 'granted') {
      await imkit.subscribe()
      return
    }
    if (Notification.permission === 'denied') return
    openNotificationPermissionModal()
  }
  watch(
    () => {
      try {
        const c = getConfig()
        return !!(c.firebaseConfig && c.firebaseVapidKey)
      } catch {
        return false
      }
    },
    (ready) => {
      if (ready) void run()
    },
    { immediate: true }
  )
}

// ---------------------------------------------------------------------------
// Base element shared by all four element classes.
// ---------------------------------------------------------------------------

interface IMKitElementImperativeAPI {
  setConfig(config: Partial<Config>): void
  setRoomTag(tag: string): void
  setChatStyle(style: unknown): void
  getStore(): ImkitStore | undefined
  readonly imkitReady: boolean
}

abstract class IMKitElementBase
  extends HTMLElement
  implements IMKitElementImperativeAPI
{
  protected app?: App
  protected store?: ImkitStore
  protected mountPoint?: HTMLDivElement
  protected overrides: Partial<Config> = {}
  // The `theme` attribute now carries the colour MODE only (light/dark); the
  // palette itself comes from the design-token seeds. Named `modeState` to keep
  // that distinction, which is why this is not `themeState` any more.
  protected modeState = reactive<{ mode: string | null }>({ mode: null })
  // Per-link guest theming (header colors etc.). Reactive so setChatStyle()
  // updates flow to the mounted <ChatRoom> via its chatStyle prop. Only
  // <imkit-chat-room> consumes it; other elements ignore the prop.
  protected chatStyleState = reactive<{ chatStyle: unknown }>({
    chatStyle: null
  })
  private storeUnsubscribe?: () => void
  private actionUnsubscribe?: () => void
  private _imkitReady = false

  protected abstract getElementLabel(): string

  /** Override to swap the inner Vue component. Return null for elements that
   *  only need the modals container (e.g. <imkit-modals-container>). */
  protected getRootComponent(): Component | null {
    return null
  }

  /** Render an inline ModalsContainer next to the root component. Off for
   *  <imkit-chat-room-info> since the page already has a sibling
   *  <imkit-modals-container>. On for everyone else. */
  protected includesInlineModals(): boolean {
    return true
  }

  /** Auto-hide the root component when there's no selected room. Used by
   *  <imkit-chat-room-info> to match v1's `v-if="selectedRoomId"`. */
  protected hideRootWhenNoSelectedRoom(): boolean {
    return false
  }

  /** Drive the offline-push permission flow (modal + FCM subscribe) from this
   *  element. Only <imkit-room-list> opts in — it's the always-mounted element
   *  on the admin chat, mirroring v1's MainView.onMounted, which the
   *  web-component build (no MainView) otherwise drops. Gated at runtime on
   *  firebaseConfig + firebaseVapidKey, so it's a no-op until the host
   *  configures push. */
  protected enablesNotificationFlow(): boolean {
    return false
  }

  /** Hook fired after the inner Vue app has mounted. */
  protected onAfterMount?(store: ImkitStore): void

  /** Public: set by the base class once mount() resolves. React consumers
   *  can read this synchronously to recover from missing the imkit-ready
   *  event (event-only signaling races against React effect phases). */
  get imkitReady(): boolean {
    return this._imkitReady
  }

  connectedCallback(): void {
    if (this.app) return
    this.modeState.mode = this.getAttribute(ATTR_THEME)
    // Apply the initial language before mount so the first render already
    // uses the host-requested locale. i18n is a shared singleton, so this
    // affects every sibling element too.
    const lang = this.getAttribute(ATTR_LANG)
    if (lang) setLocale(lang)
    this.mount()
  }

  disconnectedCallback(): void {
    this.unmount()
  }

  attributeChangedCallback(
    name: string,
    oldVal: string | null,
    newVal: string | null
  ): void {
    if (oldVal === newVal) return
    const store = this.store
    switch (name) {
      case ATTR_THEME:
        this.modeState.mode = newVal
        break
      case ATTR_LANG:
        // Runtime language switch. setLocale updates the reactive i18n
        // locale on the shared singleton, so all mounted elements re-render.
        if (newVal) setLocale(newVal)
        break
      case ATTR_ROOM_ID:
        if (store) store.$patch({ selectedRoomId: newVal ?? '' })
        break
      case ATTR_ROOM_TAG:
        if (store) store.setRoomTag(newVal ?? '')
        break
      case ATTR_TOKEN:
        if (store) {
          this.applyMountedRuntimeConfigPatch({ token: newVal ?? '' })
        }
        break
      case ATTR_API_BASE_URL:
      case ATTR_CLIENT_KEY:
        // Attribute setters also run before the element is connected. Those
        // values are initial configuration and mount() reads them below; only
        // a change after mount is unsupported and should warn.
        if (!store) break
        // Changing these would require rebuilding axios/socket for the shared
        // runtime, which would also invalidate any sibling element. Out of
        // scope for runtime updates; consumers should set these once at
        // first mount.
        console.warn(
          `[${this.getElementLabel()}] ${name} changed at runtime; ignored. ` +
            `Set this attribute once before the element first connects.`
        )
        break
    }
  }

  protected currentAttrs(): Partial<Record<AttrName, string>> {
    const result: Partial<Record<AttrName, string>> = {}
    for (const name of ROOM_AWARE_OBSERVED_ATTRIBUTES) {
      const v = this.getAttribute(name)
      if (v !== null) result[name] = v
    }
    return result
  }

  private applyMountedRuntimeConfigPatch(config: Partial<Config>): void {
    const tokenChanged =
      typeof config.token === 'string' && config.token !== getRuntimeToken()

    if (tokenChanged) {
      this.store?.resetSession()
      // resetSession intentionally clears account-owned navigation. A fixed
      // room attribute is host configuration, so re-apply it just as App.vue
      // re-applies its fixed room from the route after a token switch.
      const fixedRoomId = this.getAttribute(ATTR_ROOM_ID)
      if (fixedRoomId !== null) {
        this.store?.$patch({ selectedRoomId: fixedRoomId })
      }
    }

    applyRuntimeConfigPatch(config)
    if (tokenChanged || config.clientKey || config.domain) reconnectSocket()
  }

  protected mount(): void {
    const config = buildConfig(this.currentAttrs(), this.overrides)
    const pinia = getOrCreateSharedPinia()
    const store = getOrCreateSharedStore(pinia)
    const initialRoomId = this.getAttribute(ATTR_ROOM_ID) ?? ''
    const initialRoomTag = this.getAttribute(ATTR_ROOM_TAG) ?? ''
    const modeState = this.modeState
    const chatStyleState = this.chatStyleState
    const rootComponent = this.getRootComponent()
    const includeInlineModals = this.includesInlineModals()
    const hideRootWhenNoSelectedRoom = this.hideRootWhenNoSelectedRoom()
    const enableNotificationFlow = this.enablesNotificationFlow()

    // Slot pass-through: capture this host element's existing children BEFORE
    // we append the Vue mountPoint, grouped by their `slot` attribute (default
    // when absent). These are the children the consumer placed inside
    // <imkit-chat-room-info> — e.g. the dashboard's email-notify form (default
    // slot) and the admin "export chat history" button
    // (slot="afterChatbotSwitch"). Vue's render below emits a marker div at
    // each matching <slot> position and reattachSlots() physically moves each
    // group into its marker after mount.
    //
    // Snapshot is static — fine for content the consumer mounts once and
    // mutates in place (the consumer keeps owning the subtree). If a consumer
    // conditionally remounts slot content, revisit with a MutationObserver.
    const slotGroups: Record<string, Node[]> = {}
    for (const node of Array.from(this.childNodes)) {
      const slotName =
        node.nodeType === Node.ELEMENT_NODE
          ? (node as Element).getAttribute('slot') || DEFAULT_SLOT_NAME
          : DEFAULT_SLOT_NAME
      if (!slotGroups[slotName]) slotGroups[slotName] = []
      slotGroups[slotName].push(node)
    }
    const slotNames = Object.keys(slotGroups)

    const Wrapper = defineComponent({
      name: 'IMKitElementCE',
      setup() {
        const RootComp = rootComponent ? markRaw(rootComponent) : null
        const ModalsContainerComp = markRaw(
          ModalsContainer as unknown as Component
        )
        const imkit = useImkitStore()
        // Opt-in per element (room-list only). Runs in setup so useModal /
        // useImkitStore bind to this app's vfm + store context.
        if (enableNotificationFlow) {
          setupNotificationPermissionFlow()
        }
        const showRoot = computed(() => {
          if (!RootComp) return false
          if (!hideRootWhenNoSelectedRoom) return true
          return !!imkit.selectedRoomId
        })
        const rootEl = ref<HTMLDivElement | null>(null)
        const dark = computed(() => modeState.mode === 'dark')
        useDesignPalette(rootEl, dark)
        // After Vue mounts (and after each update), move each captured slot
        // group into the marker Vue rendered for that slot name. rAF defers
        // until the DOM is committed; appendChild is a safe no-op when the node
        // is already in place. Groups whose slot has no marker (RootComp lacks
        // that <slot>) are left in place — same as native slot fallback.
        const reattachSlots = () => {
          if (slotNames.length === 0) return
          const markers: Record<string, Element> = {}
          mountPoint.querySelectorAll('[data-imkit-slot]').forEach((el) => {
            markers[el.getAttribute('data-imkit-slot') as string] = el
          })
          for (const name of slotNames) {
            const marker = markers[name]
            if (!marker) continue
            for (const node of slotGroups[name]) {
              if (node === mountPoint) continue
              if (node.parentNode !== marker) marker.appendChild(node)
            }
          }
        }
        onMounted(() => requestAnimationFrame(reattachSlots))
        onUpdated(() => requestAnimationFrame(reattachSlots))
        return () => {
          const children = []
          if (showRoot.value && RootComp) {
            // chatStyle is a <ChatRoom>-only prop; pass it reactively there and
            // nowhere else so RoomList / ChatRoomInfo don't get a stray attr.
            //
            // `colorMode` rides along because the per-link colours in chatStyle
            // are SEEDS that have to be adapted to the mode, and this is the
            // only place that holds both. ChatRoom cannot work the mode out on
            // its own: the palette follows `modeState`, while the `.dark` class
            // and vue-dark-switch are separate mechanisms that can disagree.
            const rootProps =
              rootComponent === (ChatRoom as unknown as Component)
                ? {
                    chatStyle: chatStyleState.chatStyle,
                    colorMode: dark.value ? 'dark' : 'light'
                  }
                : null
            // One marker per discovered slot name, each emitted at RootComp's
            // matching <slot> position — default `<slot>` (between header and
            // members in ChatRoomInfo) plus named slots like `afterChatbotSwitch`
            // (between the chatbot switch and members). reattachSlots() fills
            // them after mount.
            //
            // The marker is `display: contents`, so it holds a POSITION and not
            // a box: the consumer's projected children become direct children
            // of whatever the <slot> sits in, and each surface keeps its own
            // layout. It used to be `w-full min-w-0` — sized for the two
            // block-level slots that existed then (the guest email form, the
            // full-width export button) to stop the box inflating past the info
            // sidebar. That is the wrapper deciding layout on the component's
            // behalf, and it broke the first slot placed in a ROW: the marker
            // took the whole remaining width of ChatRoomInfo's quick-actions
            // row, squeezing pin / mute / search from 60px to 44px and wrapping
            // their labels. Any future inline slot would have hit the same
            // thing. A consumer that needs the old full-width box can put
            // `w-full` on its own wrapper.
            // Slot names RootComp doesn't expose are simply ignored by Vue, and
            // elements with no host children pass no slots at all.
            const slots: Record<string, () => VNode> = {}
            for (const name of slotNames) {
              slots[name] = () =>
                h('div', {
                  class: `${slotMarkerClass(name)} contents`,
                  'data-imkit-slot': name
                })
            }
            children.push(
              h(RootComp, rootProps, slotNames.length > 0 ? slots : undefined)
            )
          }
          if (includeInlineModals) children.push(h(ModalsContainerComp))
          return h(
            'div',
            {
              ref: rootEl,
              class: [
                'imkit-element-ce relative h-full w-full',
                dark.value ? 'dark' : ''
              ]
            },
            children
          )
        }
      }
    })

    const mountPoint = document.createElement('div')
    mountPoint.style.height = '100%'
    mountPoint.style.width = '100%'
    this.appendChild(mountPoint)
    this.mountPoint = mountPoint

    const app = createApp(Wrapper)
    app.use(pinia)

    // First element to mount: full install (builds axios + socket,
    // initializes store, registers per-app pieces). Subsequent
    // elements reuse the shared store and only register per-app pieces.
    // Set the flag synchronously before awaiting so concurrent mounts in
    // the same tick don't both run the heavy path.
    let installPromise: Promise<unknown>
    if (!sharedStoreInitialized) {
      sharedStoreInitialized = true
      installPromise = Promise.resolve(IMKitPlugin.install(app, { config }))
    } else {
      installAppLevel(app)
      installPromise = Promise.resolve()
    }

    installPromise
      .then(() => {
        if (initialRoomTag) {
          store.setRoomTag(initialRoomTag)
        }
        if (initialRoomId) {
          store.$patch({ selectedRoomId: initialRoomId })
        }
        this.bridgeStoreEvents(store)
        app.mount(mountPoint)
        this.onAfterMount?.(store)
        this._imkitReady = true
        this.dispatchEvent(new CustomEvent('imkit-ready'))
      })
      .catch((err) => {
        this.dispatchEvent(new CustomEvent('imkit-error', { detail: err }))
        console.error(`[${this.getElementLabel()}] failed to mount:`, err)
      })

    this.app = app
    this.store = store
    liveElements.add(this)
    sharedRefcount++
  }

  protected unmount(): void {
    this._imkitReady = false
    this.storeUnsubscribe?.()
    this.actionUnsubscribe?.()
    this.storeUnsubscribe = undefined
    this.actionUnsubscribe = undefined
    try {
      this.app?.unmount()
    } catch (err) {
      console.warn(`[${this.getElementLabel()}] unmount error:`, err)
    }
    this.mountPoint?.remove()
    this.mountPoint = undefined
    this.app = undefined
    this.store = undefined
    liveElements.delete(this)
    releaseSharedStore()
  }

  private bridgeStoreEvents(store: ImkitStore): void {
    let prevSelectedRoomId = store.selectedRoomId
    this.storeUnsubscribe = store.$subscribe((_mutation, state) => {
      const newId = state.selectedRoomId
      if (newId === prevSelectedRoomId) return
      this.dispatchEvent(
        new CustomEvent('room-selected', {
          detail: { roomId: newId }
        })
      )
      // Synthesize go-back: in v1 the back button on <ChatRoom> clears
      // selectedRoomId. This element fires `go-back` on that exact
      // transition (non-empty -> empty). The SDK component itself does
      // not emit anything, so this is the closest faithful proxy.
      if (prevSelectedRoomId && !newId) {
        this.dispatchEvent(
          new CustomEvent('go-back', {
            detail: { fromRoomId: prevSelectedRoomId }
          })
        )
      }
      prevSelectedRoomId = newId
    })
    this.actionUnsubscribe = store.$onAction(({ name, args, after }) => {
      if (name === 'pushMessage') {
        const [message] = args
        after(() => {
          if (
            message &&
            typeof message === 'object' &&
            'roomId' in message &&
            message.roomId === store.selectedRoomId
          ) {
            this.dispatchEvent(
              new CustomEvent('message-received', { detail: message })
            )
          }
        })
      } else if (name === 'sendMessage') {
        const [payload] = args
        after(() => {
          this.dispatchEvent(
            new CustomEvent('message-sent', { detail: payload })
          )
        })
      }
    })
  }

  // -------------------------------------------------------------------------
  // Imperative API
  // -------------------------------------------------------------------------

  setConfig(config: Partial<Config>): void {
    this.overrides = { ...this.overrides, ...config }
    if (!this.store) return
    this.applyMountedRuntimeConfigPatch(config)
  }

  setRoomTag(tag: string): void {
    if (!this.store) {
      // Not mounted yet — queue via attribute so it's picked up on mount.
      this.setAttribute(ATTR_ROOM_TAG, tag)
      return
    }
    this.store.setRoomTag(tag)
  }

  setChatStyle(style: unknown): void {
    // Reactive holder is read in the mount() render, so this applies whether
    // called before or after mount (no queueing needed).
    this.chatStyleState.chatStyle = style
  }

  getStore(): ImkitStore | undefined {
    return this.store
  }
}

// ---------------------------------------------------------------------------
// <imkit-chat-room>
// ---------------------------------------------------------------------------

interface IMKitChatRoomElement extends IMKitElementImperativeAPI {
  sendMessage(text: string): Promise<void>
}

class ChatRoomElement extends IMKitElementBase implements IMKitChatRoomElement {
  static get observedAttributes(): readonly string[] {
    return ROOM_AWARE_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return ChatRoom as unknown as Component
  }

  protected getElementLabel(): string {
    return CHAT_ROOM_ELEMENT_NAME
  }

  async sendMessage(text: string): Promise<void> {
    const store = this.store
    if (!store) throw new Error(`${CHAT_ROOM_ELEMENT_NAME}: not mounted`)
    const roomId = store.selectedRoomId
    if (!roomId) throw new Error(`${CHAT_ROOM_ELEMENT_NAME}: no room selected`)
    await store.sendMessage({
      roomId,
      messageType: 'text',
      message: text
    })
  }
}

// ---------------------------------------------------------------------------
// <imkit-room-list>
// ---------------------------------------------------------------------------

class RoomListElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return COMMON_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return RoomList as unknown as Component
  }

  protected getElementLabel(): string {
    return ROOM_LIST_ELEMENT_NAME
  }

  protected enablesNotificationFlow(): boolean {
    // The room list is the always-mounted element on the admin chat, so it's
    // the faithful home for v1's chat-list offline-push permission prompt.
    return true
  }

  protected onAfterMount(store: ImkitStore): void {
    // RoomList.vue dispatches fetchRooms in its own onMounted, but a
    // standalone caller may mount the room list before any chat room and
    // expect rooms to load immediately. The dispatch is idempotent (gated
    // on isRequesting[FetchRooms] in the action), so calling it here is
    // safe and matches the user-facing spec for this element.
    store.fetchRooms().catch((err) => {
      console.warn(`[${ROOM_LIST_ELEMENT_NAME}] fetchRooms error:`, err)
    })
  }
}

// ---------------------------------------------------------------------------
// <imkit-chat-room-info>
// ---------------------------------------------------------------------------

class ChatRoomInfoElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return ROOM_AWARE_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): Component {
    return ChatRoomInfo as unknown as Component
  }

  protected getElementLabel(): string {
    return CHAT_ROOM_INFO_ELEMENT_NAME
  }

  protected includesInlineModals(): boolean {
    // The page already has a sibling <imkit-modals-container>; rendering
    // another inline modals container here would create duplicate teleport
    // targets.
    return false
  }

  protected hideRootWhenNoSelectedRoom(): boolean {
    return true
  }
}

// ---------------------------------------------------------------------------
// <imkit-modals-container>
// ---------------------------------------------------------------------------

class ModalsContainerElement extends IMKitElementBase {
  static get observedAttributes(): readonly string[] {
    return COMMON_OBSERVED_ATTRIBUTES
  }

  protected getRootComponent(): null {
    return null // ModalsContainer-only; no sibling component
  }

  protected getElementLabel(): string {
    return MODALS_CONTAINER_ELEMENT_NAME
  }

  protected includesInlineModals(): boolean {
    return true
  }
}

// ---------------------------------------------------------------------------
// Element registration
// ---------------------------------------------------------------------------

if (typeof window !== 'undefined' && typeof customElements !== 'undefined') {
  // Resolve bundled sticker assets against this bundle's own location instead
  // of the host page origin. As a CDN web component the bundle and its
  // `sticker/` assets are published together, so deriving the base from the
  // module URL (ESM) or the loading <script> (UMD/classic) keeps stickers
  // loading wherever the bundle is served from.
  const bundleUrl =
    import.meta.url ||
    (document.currentScript as HTMLScriptElement | null)?.src ||
    ''
  setStickerBaseUrl(bundleUrl)

  if (!customElements.get(CHAT_ROOM_ELEMENT_NAME)) {
    customElements.define(CHAT_ROOM_ELEMENT_NAME, ChatRoomElement)
  }
  if (!customElements.get(ROOM_LIST_ELEMENT_NAME)) {
    customElements.define(ROOM_LIST_ELEMENT_NAME, RoomListElement)
  }
  if (!customElements.get(CHAT_ROOM_INFO_ELEMENT_NAME)) {
    customElements.define(CHAT_ROOM_INFO_ELEMENT_NAME, ChatRoomInfoElement)
  }
  if (!customElements.get(MODALS_CONTAINER_ELEMENT_NAME)) {
    customElements.define(MODALS_CONTAINER_ELEMENT_NAME, ModalsContainerElement)
  }
}

export {
  CHAT_ROOM_ELEMENT_NAME,
  CHAT_ROOM_INFO_ELEMENT_NAME,
  ChatRoomElement,
  ChatRoomInfoElement,
  MODALS_CONTAINER_ELEMENT_NAME,
  ModalsContainerElement,
  ROOM_LIST_ELEMENT_NAME,
  RoomListElement
}
export default ChatRoomElement
