import { nextTick, ref, type Ref } from 'vue'
import type IMImage from '../classes/image'
import type Room from '../classes/room'
import type Settings from '../classes/settings'
import type User from '../classes/user'
import type IMVideo from '../classes/video'
import { escapeRegExp } from '../utils/escapeRegExp'

type UseComposerOptions = {
  room: Ref<Room | undefined>
  users: Ref<Record<string, User>>
  settings: Ref<Settings>
  isMobile: Ref<boolean>
  input: Ref<HTMLDivElement | undefined>
  fileInput: Ref<HTMLInputElement | undefined>
  images: Ref<IMImage[]>
  imageFiles: Ref<File[]>
  videos: Ref<IMVideo[]>
  videoFiles: Ref<File[]>
  replyId: Ref<string>
  editingMessageId: Ref<string>
  sendMessage: (payload: Record<string, unknown>) => Promise<unknown>
  editMessage: (payload: {
    roomId: string
    _id: string
    message: string
    mentions?: string[]
  }) => Promise<unknown>
  clearReply: () => void
  clearEditing: () => void
  attachmentsPending: Ref<boolean>
  onMessageChanged?: (roomId: string, text: string) => void
  onUserInput?: () => void
}

const extractMessageAndMentions = (
  input: HTMLDivElement,
  room: Room,
  users: Record<string, User>,
  trim = true
) => {
  let message = ''
  const mentions: string[] = []

  const walk = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      message += node.parentElement?.closest('[data-at-caret-anchor]')
        ? node.textContent?.replace(/\u200b/g, '')
        : node.textContent
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const element = node as HTMLElement
      if (element.tagName === 'BR') {
        message += '\n'
      } else if (element.hasAttribute('data-at-embedded')) {
        const nickname =
          element.textContent?.trim().replace(/^@/, '').trim() || ''
        const user = Object.values(users).find(
          (member) => member.nickname === nickname
        )
        if (user) {
          mentions.push(user.id)
          message += ` @${user.id} `
        } else {
          message += element.textContent
        }
      } else if (element.tagName === 'DIV') {
        if (message.length > 0 && !message.endsWith('\n')) {
          message += '\n'
        }
        Array.from(node.childNodes).forEach(walk)
      } else {
        Array.from(node.childNodes).forEach(walk)
      }
    }
  }

  walk(input)
  if (trim) message = message.trim()

  // Free-text @nickname fallback (mentions typed without the picker). Match the
  // longest nicknames first so '@John' is consumed before '@Jo', require a
  // Unicode-aware word boundary after the nickname so '@Jo' does not match
  // inside '@John' and '@王' does not match inside '@王小明', and skip empty
  // nicknames (which would otherwise match every '@' in the message).
  // No '@' anywhere means no free-text mention is possible — skip the candidate
  // sort and the per-member regex entirely (this runs on every send).
  if (message.indexOf('@') === -1) {
    return { message, mentions }
  }
  const candidates = room.memberIds
    .map((uid) => users[uid])
    .filter((user): user is User => !!user && user.nickname.length > 0)
    .sort((a, b) => b.nickname.length - a.nickname.length)

  for (const user of candidates) {
    if (mentions.includes(user.id)) {
      continue
    }
    // The regex can only match if the literal '@nickname' substring is present;
    // this cheap check avoids compiling/running a regex per member in large
    // groups where most members are not mentioned.
    if (!message.includes(`@${user.nickname}`)) {
      continue
    }
    const pattern = new RegExp(
      `@${escapeRegExp(user.nickname)}(?![\\p{L}\\p{N}_-])`,
      'gu'
    )
    const replaced = message.replace(pattern, `@${user.id}`)
    if (replaced !== message) {
      mentions.push(user.id)
      message = replaced
    }
  }

  return { message, mentions }
}

export const useComposer = ({
  room,
  users,
  settings,
  isMobile,
  input,
  fileInput,
  images,
  imageFiles,
  videos,
  videoFiles,
  replyId,
  editingMessageId,
  sendMessage,
  editMessage,
  clearReply,
  clearEditing,
  attachmentsPending,
  onMessageChanged,
  onUserInput
}: UseComposerOptions) => {
  const message = ref('')
  const isComposing = ref(false)
  const showStickerPanel = ref(false)
  const showEmojiPicker = ref(false)
  const showAudioInput = ref(false)
  const stickerButtonEl = ref<HTMLElement | null>(null)
  const emojiButtonEl = ref<HTMLElement | null>(null)

  const send = async () => {
    const el = input.value
    const currentRoom = room.value
    if (!el || !currentRoom) return
    if (attachmentsPending.value) return

    const { message: extractedMessage, mentions } = extractMessageAndMentions(
      el,
      currentRoom,
      users.value
    )
    const hasText = extractedMessage.length > 0
    const hasImages = images.value.length > 0
    const hasVideos = videos.value.length > 0

    if (!hasText && !hasImages && !hasVideos) return

    const currentReplyId = replyId.value
    const currentEditingMessageId = editingMessageId.value
    const videosToSend = hasVideos ? [...videos.value] : []
    const videoFilesToSend = hasVideos ? [...videoFiles.value] : []

    // Snapshot the composer state before clearing optimistically so a failed
    // send/edit rolls back instead of silently destroying the user's typed
    // content (H20/H21). innerHTML (not textContent) preserves mention spans.
    // Reply/editing state is intentionally not snapshotted: clearReply() stays
    // optimistic (so a follow-up sent during an in-flight request is not
    // re-threaded onto the old reply target) and clearEditing() runs only on
    // success, so an edit failure correctly stays in edit mode.
    const snapshot = {
      html: el.innerHTML,
      message: message.value,
      draft: extractMessageAndMentions(el, currentRoom, users.value, false)
        .message,
      images: [...images.value],
      imageFiles: [...imageFiles.value],
      videos: [...videos.value],
      videoFiles: [...videoFiles.value]
    }

    // Keep the viewport size until the optimistic row has rendered. Otherwise
    // clearing multiline text clamps scrollTop before the new row can fill it,
    // making the list jump backward at the start of its entry scroll.
    const previousMinHeight = el.style.minHeight
    let composerHeightHeld = hasText && !currentEditingMessageId
    if (composerHeightHeld) el.style.minHeight = getComputedStyle(el).height
    const releaseComposerHeight = () => {
      if (!composerHeightHeld) return
      composerHeightHeld = false
      el.style.minHeight = previousMinHeight
    }

    el.textContent = ''
    message.value = ''
    if (!currentEditingMessageId) onMessageChanged?.(currentRoom.id, '')
    if (currentReplyId) {
      clearReply()
    }
    if (hasVideos) {
      videos.value = []
      videoFiles.value = []
    }

    await nextTick()

    try {
      const sendPromises: Promise<unknown>[] = []

      if (currentEditingMessageId && hasText) {
        await editMessage({
          roomId: currentRoom.id,
          _id: currentEditingMessageId,
          message: extractedMessage,
          mentions
        })
        clearEditing()
        if (hasImages) {
          sendPromises.push(
            sendMessage({
              roomId: currentRoom.id,
              messageType: 'image',
              images: images.value,
              files: imageFiles.value
            })
          )
          images.value = []
          imageFiles.value = []
        }
      } else if (hasText && hasImages) {
        sendPromises.push(
          sendMessage({
            roomId: currentRoom.id,
            messageType: 'mixed',
            message: extractedMessage,
            images: images.value,
            files: imageFiles.value,
            reply: currentReplyId || null,
            mentions
          })
        )
        images.value = []
        imageFiles.value = []
      } else if (hasText) {
        sendPromises.push(
          sendMessage({
            roomId: currentRoom.id,
            messageType: 'text',
            message: extractedMessage,
            reply: currentReplyId || null,
            mentions
          })
        )
      } else if (hasImages) {
        sendPromises.push(
          sendMessage({
            roomId: currentRoom.id,
            messageType: 'image',
            images: images.value,
            files: imageFiles.value
          })
        )
        images.value = []
        imageFiles.value = []
      }

      for (let index = 0; index < videosToSend.length; index++) {
        const video = videosToSend[index]
        const file = videoFilesToSend[index]
        sendPromises.push(
          sendMessage({
            roomId: currentRoom.id,
            messageType: 'video',
            video,
            file,
            width: video.width,
            height: video.height,
            duration: video.duration
          })
        )
      }

      await nextTick()
      if (composerHeightHeld) {
        // Virtua measures the optimistic row on a frame after Vue renders it.
        // Keep the viewport stable through that paint so WebKit cannot clamp
        // the old scroll offset before the new row extends the scroll range.
        await new Promise<void>((resolve) =>
          requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
        )
      }
      releaseComposerHeight()

      if (sendPromises.length > 0) {
        await Promise.all(sendPromises)
      }

      input.value?.focus()
    } catch (error) {
      // Roll back the optimistic clear so the user can retry, and swallow the
      // rejection so @click="send" / onKeydownEnter never see an unhandled
      // rejection. A multi-send batch (edit+image, text+videos) that fails after
      // a partial success may re-send the succeeded item on retry — inherent to
      // Promise.all batching and out of H20/H21's scope.
      console.error('Failed to send message', error)
      el.innerHTML = snapshot.html
      message.value = snapshot.message
      if (!currentEditingMessageId)
        onMessageChanged?.(currentRoom.id, snapshot.draft)
      // Restore only what this send cleared, so a paste/drop that landed during
      // the in-flight request is not clobbered by a stale snapshot.
      if (hasImages) {
        images.value = snapshot.images
        imageFiles.value = snapshot.imageFiles
      }
      if (hasVideos) {
        videos.value = snapshot.videos
        videoFiles.value = snapshot.videoFiles
      }
      input.value?.focus()
    } finally {
      releaseComposerHeight()
    }
  }

  const onSelectEmoji = (emoji: { i: string }) => {
    if (input.value) {
      input.value.focus()
      document.execCommand('insertText', false, emoji.i)
    }
    showEmojiPicker.value = false
  }

  const onClickOutsideSticker = () => {
    showStickerPanel.value = false
  }

  const onClickOutsideEmoji = () => {
    showEmojiPicker.value = false
  }

  const toggleStickerPanel = () => {
    showStickerPanel.value = !showStickerPanel.value
    if (showStickerPanel.value) {
      showEmojiPicker.value = false
    }
  }

  const toggleEmojiPicker = () => {
    showEmojiPicker.value = !showEmojiPicker.value
    if (showEmojiPicker.value) {
      showStickerPanel.value = false
    }
  }

  const handleImageButtonTapped = () => {
    fileInput.value?.click()
  }

  const onCompositionstart = () => {
    isComposing.value = true
  }

  const onCompositionend = () => {
    setTimeout(() => {
      isComposing.value = false
      if (input.value === document.activeElement) ensureCaretAnchor()
    }, 0)
  }

  const onKeydownEnter = (event: KeyboardEvent) => {
    if (
      !isComposing.value &&
      !event.isComposing &&
      event.key === 'Enter' &&
      !event.shiftKey &&
      !isMobile.value &&
      !settings.value.sendButtonEnabled
    ) {
      event.preventDefault()
      send()
    }
  }

  // Mention-only state: input contains only contenteditable="false" children
  // and whitespace text nodes. In this state At's atomic-delete cannot trigger
  // (caret sits inside a whitespace text node with offset > 0) and
  // ensureCaretAnchor would silently regenerate the anchor on every backspace,
  // making the mention undeletable. Intercept backspace here and remove the
  // trailing mention span instead. When other editable text is present, this
  // returns false and native deletion runs as usual.
  const isMentionOnly = (el: HTMLElement) => {
    for (const node of Array.from(el.childNodes)) {
      if (node.nodeType === Node.TEXT_NODE) {
        if (!/^[^\S\r\n]*$/.test((node as Text).data)) return false
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        if ((node as HTMLElement).contentEditable !== 'false') return false
      } else {
        return false
      }
    }
    return el.querySelector('[contenteditable="false"]') !== null
  }

  const placeCaretAtTextEnd = (node: Text) => {
    const range = document.createRange()
    range.setStart(node, node.length)
    range.collapse(true)
    const sel = window.getSelection()
    sel?.removeAllRanges()
    sel?.addRange(range)
  }

  // WebKit places the caret at the far right of a contenteditable container
  // when its only children are contenteditable="false" mention spans. Keeping
  // an editable trailing text-node anchor lets WebKit position the caret
  // correctly. trim() at send time strips it from the outgoing message.
  const ensureCaretAnchor = () => {
    const el = input.value
    // Leave the browser-owned IME range untouched until composition ends.
    if (!el || isComposing.value) return
    const last = el.lastChild
    if (
      isMentionOnly(el) &&
      last?.nodeType === Node.TEXT_NODE &&
      /^\s*$/.test((last as Text).data)
    ) {
      const anchor = last as Text
      if (!anchor.data) anchor.data = ' '
      const sel = window.getSelection()
      const range = sel?.rangeCount ? sel.getRangeAt(0) : null
      if (
        (!range && document.activeElement === el) ||
        (range?.collapsed &&
          range.startContainer === anchor &&
          range.startOffset === 0)
      ) {
        placeCaretAtTextEnd(anchor)
      }
      return
    }
    if (
      !last ||
      last.nodeType !== Node.ELEMENT_NODE ||
      (last as HTMLElement).contentEditable !== 'false'
    ) {
      return
    }
    const anchor = document.createTextNode(' ')
    el.appendChild(anchor)
    placeCaretAtTextEnd(anchor)
  }

  const onBeforeInput = (e: InputEvent) => {
    if (e.inputType !== 'deleteContentBackward') return
    const el = input.value
    if (!el || !isMentionOnly(el)) return
    e.preventDefault()
    e.stopPropagation()
    const spans = el.querySelectorAll('[contenteditable="false"]')
    const lastSpan = spans[spans.length - 1]
    if (!lastSpan) return
    let cursor: Node | null = el.lastChild
    while (cursor) {
      const prev: Node | null = cursor.previousSibling
      el.removeChild(cursor)
      if (cursor === lastSpan) break
      cursor = prev
    }
    const range = document.createRange()
    range.selectNodeContents(el)
    range.collapse(false)
    const sel = window.getSelection()
    sel?.removeAllRanges()
    sel?.addRange(range)
    el.dispatchEvent(new Event('input', { bubbles: true }))
  }

  const onInput = (event?: InputEvent) => {
    if (!input.value) return
    // Mention autocomplete already leaves an editable suffix at the intended
    // caret position. Moving to the end of that suffix would insert an extra
    // space before the user's next character.
    if (event?.inputType !== 'insertReplacementText') ensureCaretAnchor()
    onUserInput?.()
    // The invisible marker only supplies a caret stop before a mention.
    const text = (input.value.innerText || '').replace(/\u200b/g, '')
    // A contenteditable emptied by the user does not report `''` — the browser
    // leaves a trailing newline (or a stray `<br>`), so `innerText` is "\n".
    // Assigning that raw value left `message` one character long after the
    // user had deleted everything, which kept the send button enabled with an
    // empty composer, and would have sent a whitespace-only message. The DOM
    // was already being cleared on this branch; `message` has to be cleared
    // with it, or the two disagree about whether the composer is empty.
    // Only the ALL-whitespace case collapses to empty: a trailing space
    // mid-typing ("hello ") is real content and must survive.
    if (!text.trim()) {
      message.value = ''
      input.value.textContent = ''
      if (room.value) onMessageChanged?.(room.value.id, '')
      return
    }
    message.value = text
    if (room.value) {
      onMessageChanged?.(
        room.value.id,
        extractMessageAndMentions(input.value, room.value, users.value, false)
          .message
      )
    }
  }

  const onFormatApplied = () => {
    if (input.value) {
      message.value = (input.value.innerText || '').replace(/\u200b/g, '')
      if (room.value) {
        onMessageChanged?.(
          room.value.id,
          extractMessageAndMentions(input.value, room.value, users.value, false)
            .message
        )
      }
    }
  }

  return {
    message,
    isComposing,
    showStickerPanel,
    showEmojiPicker,
    stickerButtonEl,
    emojiButtonEl,
    showAudioInput,
    send,
    onSelectEmoji,
    onClickOutsideSticker,
    onClickOutsideEmoji,
    toggleStickerPanel,
    toggleEmojiPicker,
    handleImageButtonTapped,
    onCompositionstart,
    onCompositionend,
    onKeydownEnter,
    onBeforeInput,
    onInput,
    onFormatApplied,
    ensureCaretAnchor
  }
}
