/**
 * Bundled sticker assets (public/sticker/**) are referenced by the chat UI via
 * root-relative paths like `/sticker/FunFunFamily/FunFunFamily-1.png`. That
 * works when the SDK is bundled into a host that serves those files at its own
 * site root (e.g. the Nuxt guest site). But when the SDK is loaded as a CDN
 * web-component bundle (`<script src="cdn.../imkit-custom-element.js">`), a
 * root-relative `<img src>` resolves against the *host page* origin — which
 * does not serve `/sticker` — so every sticker 404s.
 *
 * The custom-element entry calls `setStickerBaseUrl(import.meta.url)` so sticker
 * URLs resolve against the bundle's own location, where the sticker assets are
 * published alongside the bundle. Consumers that bundle the SDK directly leave
 * the base unset and keep the root-relative behaviour.
 */
let stickerBaseUrl = ''

/**
 * Set the base the sticker assets are served from. Accepts the bundle's own
 * file URL (the directory is derived from it via `new URL`) or a directory URL.
 * An empty string restores root-relative resolution.
 */
export function setStickerBaseUrl(url: string): void {
  stickerBaseUrl = url ?? ''
}

/**
 * Resolve a root-relative sticker path (e.g. `/sticker/FunFunFamily/x.png`) to
 * an absolute URL against the configured base. With no base set, returns the
 * path root-relative (unchanged behaviour), so host-bundled consumers keep
 * serving stickers from their own site root.
 */
export function resolveStickerUrl(pathFromRoot: string): string {
  const rel = pathFromRoot.replace(/^\/+/, '')
  if (!stickerBaseUrl) return `/${rel}`
  try {
    return new URL(rel, stickerBaseUrl).href
  } catch {
    return `/${rel}`
  }
}
