<script setup lang="ts">
import { useMediaQuery } from '@vueuse/core'
import { Bold, Code, Italic, SquareCode, Strikethrough } from 'lucide-vue-next'
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'

const props = defineProps<{
  inputElement: HTMLDivElement | undefined
}>()

const { t } = useI18n()

const hasFinePointer = useMediaQuery('(hover: hover) and (pointer: fine)')

const emit = defineEmits<{
  (e: 'format-applied'): void
}>()

const showMenu = ref(false)
const menuPosition = ref({ top: 0, left: 0 })
const arrowOffset = ref(0) // Arrow offset from menu center (in px)
const savedSelection = ref<Range | null>(null)
let selectionCheckFrame: number | undefined

type FormatType = 'bold' | 'italic' | 'strike' | 'code' | 'block'

const cancelPendingSelectionCheck = () => {
  if (selectionCheckFrame === undefined) return

  cancelAnimationFrame(selectionCheckFrame)
  selectionCheckFrame = undefined
}

// Hide menu on scroll
const onScroll = () => {
  cancelPendingSelectionCheck()
  if (showMenu.value) {
    showMenu.value = false
  }
}

const updateMenuFromSelection = () => {
  const selection = window.getSelection()
  if (
    !hasFinePointer.value ||
    !selection ||
    selection.isCollapsed ||
    !props.inputElement ||
    selection.rangeCount === 0
  ) {
    showMenu.value = false
    savedSelection.value = null
    return
  }

  const range = selection.getRangeAt(0)
  // Check if selection is within the input element
  if (!props.inputElement.contains(range.commonAncestorContainer)) {
    showMenu.value = false
    savedSelection.value = null
    return
  }

  const selectedText = selection.toString().trim()
  if (!selectedText) {
    showMenu.value = false
    savedSelection.value = null
    return
  }

  // Save the selection for later use
  savedSelection.value = range.cloneRange()

  // Calculate position
  const rect = range.getBoundingClientRect()
  const inputRect = props.inputElement.getBoundingClientRect()

  // Menu dimensions (approximate)
  const menuWidth = 220
  const menuHeight = 32

  // Position menu above the selection, centered
  const originalLeft = rect.left - inputRect.left + rect.width / 2
  let left = originalLeft
  const top = rect.top - inputRect.top - menuHeight - 22 // 6px gap above text

  // Arrow can be offset up to 30% from center (keep 10% margin from edge)
  const maxArrowOffset = menuWidth * 0.3

  // Prevent menu from going off the left edge (allow arrow offset)
  const minLeft = menuWidth / 2 - maxArrowOffset + 8
  if (left < minLeft) {
    left = minLeft
  }

  // Prevent menu from going off the right edge (allow arrow offset)
  const maxLeft = inputRect.width - menuWidth / 2 + maxArrowOffset - 8
  if (left > maxLeft) {
    left = maxLeft
  }

  // Calculate arrow offset from menu center to point at selection center
  // Clamp arrow offset to stay within menu bounds
  const rawOffset = originalLeft - left
  arrowOffset.value = Math.max(
    -maxArrowOffset,
    Math.min(maxArrowOffset, rawOffset)
  )

  menuPosition.value = { top, left }
  showMenu.value = true
}

const checkSelection = () => {
  cancelPendingSelectionCheck()
  selectionCheckFrame = requestAnimationFrame(() => {
    selectionCheckFrame = undefined
    updateMenuFromSelection()
  })
}

// Browser selection is updated asynchronously across drag and click paths.
const onSelectionChange = () => {
  checkSelection()
}

// Watch for inputElement changes to add/remove scroll listener
watch(
  () => props.inputElement,
  (newEl, oldEl) => {
    oldEl?.removeEventListener('scroll', onScroll)
    newEl?.addEventListener('scroll', onScroll)
  },
  { immediate: true }
)

onMounted(() => {
  document.addEventListener('selectionchange', onSelectionChange)
})

onUnmounted(() => {
  cancelPendingSelectionCheck()
  props.inputElement?.removeEventListener('scroll', onScroll)
  document.removeEventListener('selectionchange', onSelectionChange)
})

const hideMenu = () => {
  cancelPendingSelectionCheck()
  showMenu.value = false
  savedSelection.value = null
}

const applyFormat = (type: FormatType) => {
  cancelPendingSelectionCheck()
  if (!savedSelection.value || !props.inputElement) return

  const selection = window.getSelection()
  if (!selection) return

  // Restore the saved selection
  selection.removeAllRanges()
  selection.addRange(savedSelection.value)

  const selectedText = selection.toString()
  if (!selectedText) return

  // Define format symbols
  const formats: Record<FormatType, { prefix: string; suffix: string }> = {
    bold: { prefix: '**', suffix: '**' },
    italic: { prefix: '_', suffix: '_' },
    strike: { prefix: '~~', suffix: '~~' },
    code: { prefix: '`', suffix: '`' },
    block: { prefix: '\n```\n', suffix: '\n```\n' }
  }

  const { prefix, suffix } = formats[type]
  const formattedText = `${prefix}${selectedText}${suffix}`

  // Insert the formatted text
  // For formats with newlines, use DOM manipulation to avoid HTML parsing issues
  if (prefix.includes('\n') || suffix.includes('\n')) {
    const range = savedSelection.value
    range.deleteContents()

    // Create fragment with text nodes and <br> elements
    const fragment = document.createDocumentFragment()
    const parts = formattedText.split('\n')

    parts.forEach((part, index) => {
      if (index > 0) {
        fragment.appendChild(document.createElement('br'))
      }
      if (part) {
        fragment.appendChild(document.createTextNode(part))
      }
    })

    range.insertNode(fragment)

    // Move cursor to end of inserted content
    range.collapse(false)
    selection.removeAllRanges()
    selection.addRange(range)
  } else {
    document.execCommand('insertText', false, formattedText)
  }

  // Hide the menu
  showMenu.value = false
  savedSelection.value = null

  // Notify parent that format was applied
  emit('format-applied')
}

defineExpose({
  checkSelection,
  hideMenu
})
</script>

<template>
  <Transition name="format-menu">
    <!--
      Same chrome as every other floating surface in the app — the
      input-actions popover in ChatRoom.vue and the dropdown-menu primitive
      both use `rounded-lg border border-border bg-surface text-content
      shadow-raised`. This one was `border-gray-200/60 bg-white/95` with dark
      variants and a `backdrop-blur-sm`: raw palette that could not follow the
      theme, and a translucent-blurred treatment nothing else in the app uses,
      which is what made it look foreign.

      The buttons inside are `rounded-md`, not `rounded-lg`. Concentric radii:
      inner = outer − padding, so 16px − 6px of `px-1.5` lands on 10px. Two
      equal radii nested inside each other is what reads as wrong at the
      corners (the rule is spelled out at ChatRoom.vue's popover).
    -->
    <div
      v-if="showMenu"
      class="format-menu absolute z-50 flex items-center gap-0.5 rounded-lg border border-border bg-surface px-1.5 py-1 text-content shadow-raised"
      :style="{
        top: `${menuPosition.top}px`,
        left: `${menuPosition.left}px`,
        transform: 'translateX(-50%)'
      }"
      @mousedown.prevent
    >
      <!-- Bold -->
      <button
        class="format-btn tooltip-trigger group relative flex h-8 w-8 items-center justify-center rounded-md text-content-muted transition-all duration-150 hover:bg-surface-hover hover:text-content active:scale-95"
        :aria-label="t('formatBold') + ' **text**'"
        @click="applyFormat('bold')"
      >
        <Bold class="h-4 w-4" />
        <span class="tooltip">{{ t('formatBold') + ' **text**' }}</span>
      </button>

      <!-- Italic -->
      <button
        class="format-btn tooltip-trigger group relative flex h-8 w-8 items-center justify-center rounded-md text-content-muted transition-all duration-150 hover:bg-surface-hover hover:text-content active:scale-95"
        :aria-label="t('formatItalic') + ' _text_'"
        @click="applyFormat('italic')"
      >
        <Italic class="h-4 w-4" />
        <span class="tooltip">{{ t('formatItalic') + ' _text_' }}</span>
      </button>

      <!-- Strikethrough -->
      <button
        class="format-btn tooltip-trigger group relative flex h-8 w-8 items-center justify-center rounded-md text-content-muted transition-all duration-150 hover:bg-surface-hover hover:text-content active:scale-95"
        :aria-label="t('formatStrike') + ' ~~text~~'"
        @click="applyFormat('strike')"
      >
        <Strikethrough class="h-4 w-4" />
        <span class="tooltip">{{ t('formatStrike') + ' ~~text~~' }}</span>
      </button>

      <!-- Divider -->
      <div class="mx-0.5 h-5 w-px bg-border" />

      <!--
        All five glyphs are lucide icons at one size and one colour. They used
        to be three different languages: `B`/`I`/`S` as text characters at
        `text-xs`, inline code as a boxed letter `T` in its own red, and the
        code block as a hand-inlined SVG at `h-4.5` — which is what read as
        inconsistent. lucide is what the rest of the app draws with.

        The boxed T also had two defects worth recording, since both are gone
        with it rather than fixed: its border was `border-1.5`, not a Tailwind
        width (the scale is `border`, `border-2`), so it compiled to nothing
        and had never rendered — verified against the built stylesheet. And
        its red was `border-red-400` / `hover:bg-red-50`, raw palette that
        could not follow the theme.

        No colour on the code icons. Real inline code renders rose in a
        message (style.css, a deliberately raw pair), but `danger-vivid` is a
        different hue, so tinting these would have implied a link to that
        convention while pointing at the wrong red. The `</>` shapes and the
        titles already say "code".
      -->
      <button
        class="format-btn tooltip-trigger group relative flex h-8 w-8 items-center justify-center rounded-md text-content-muted transition-all duration-150 hover:bg-surface-hover hover:text-content active:scale-95"
        :aria-label="t('formatInlineCode') + ' `text`'"
        @click="applyFormat('code')"
      >
        <Code class="h-4 w-4" />
        <span class="tooltip">{{ t('formatInlineCode') + ' `text`' }}</span>
      </button>

      <!-- Code Block (Paragraph Box) -->
      <button
        class="format-btn tooltip-trigger group relative flex h-8 w-8 items-center justify-center rounded-md text-content-muted transition-all duration-150 hover:bg-surface-hover hover:text-content active:scale-95"
        :aria-label="t('formatCodeBlock') + ' \`\`\`text\`\`\`'"
        @click="applyFormat('block')"
      >
        <SquareCode class="h-4 w-4" />
        <span class="tooltip">{{
          t('formatCodeBlock') + ' \`\`\`text\`\`\`'
        }}</span>
      </button>

      <!-- Arrow pointer -->
      <div
        class="absolute -bottom-1.5 h-3 w-3 -translate-x-1/2 rotate-45 border-r border-b border-border bg-surface"
        :style="{ left: `calc(50% + ${arrowOffset}px)` }"
      />
    </div>
  </Transition>
</template>

<style scoped>
/* Format Menu Transitions */
.format-menu-enter-active,
.format-menu-leave-active {
  transition: all 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}

.format-menu-enter-from,
.format-menu-leave-to {
  opacity: 0;
  transform: translateX(-50%) translateY(4px) scale(0.95);
}

.format-menu-enter-to,
.format-menu-leave-from {
  opacity: 1;
  transform: translateX(-50%) translateY(0) scale(1);
}
</style>
