import { computed, onUnmounted, type ComputedRef } from 'vue'
import Message, {
  LocationMessage,
  MessageStatus,
  MessageType,
  MixedMessage,
  TextMessage
} from '../classes/message'
import DeleteMessageConfirmModal from '../components/DeleteMessageConfirmModal.vue'
import DeleteMessageModal from '../components/DeleteMessageModal.vue'
import UnsendMessageModal from '../components/UnsendMessageModal.vue'
import { getConfig } from '../runtime/config'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import { isActionsHandoffInProgress } from './useActionsHandoffGuard'
import { useImkitModal as useModal } from './useImkitModal'

export function useMessageActions(message: ComputedRef<Message>) {
  const imkit = useImkitStore()
  const config = getConfig()

  const room = computed(() => imkit.rooms[message.value.roomId])
  const userId = computed(() => getUid())
  const reactions = computed(() => message.value.reactions)
  const translationApiKey = computed((): string => config.translationApiKey)

  // 權限判斷
  const canCopy = computed(() => {
    const nonCopyableTypes = new Set([
      MessageType.Sticker,
      MessageType.Audio,
      MessageType.File,
      MessageType.Image,
      MessageType.Video,
      MessageType.Flex,
      MessageType.Template
    ])
    return !nonCopyableTypes.has(message.value.type)
  })

  const canReply = computed(() => {
    const allowTypes = new Set([
      MessageType.Text,
      MessageType.Image,
      MessageType.Mixed,
      MessageType.Video,
      MessageType.Sticker,
      MessageType.File
    ])
    return allowTypes.has(message.value.type)
  })

  const canTranslate = computed(() => {
    return (
      (message.value.type === MessageType.Text ||
        message.value.type === MessageType.Mixed) &&
      !!translationApiKey.value
    )
  })

  const canEdit = computed(() => {
    return (
      (message.value.type === MessageType.Text ||
        message.value.type === MessageType.Mixed) &&
      message.value.isOutgoing &&
      message.value.status === MessageStatus.Delivered
    )
  })

  const isEdited = computed(() => {
    return (
      message.value.editedAt != null &&
      message.value.status === MessageStatus.Delivered
    )
  })

  // Actions
  const setShowActions = (value: boolean) => {
    if (value) {
      // While a different message's dropdown is mid-handoff (see
      // useActionsHandoffGuard.ts), don't let a hover on *this* message
      // steal the active slot - that hover is a reveal of the bubble
      // underneath a just-closed portalled menu, not a deliberate hover.
      if (
        isActionsHandoffInProgress() &&
        imkit.activeActionMessageId !== '' &&
        imkit.activeActionMessageId !== message.value.id
      ) {
        return
      }
      imkit.$patch({ activeActionMessageId: message.value.id })
      return
    }
    // Only the message that currently owns the active slot may clear it.
    // Without this check, a mouseleave firing on some *other* (never-active)
    // message - e.g. one the cursor grazed while a blocked claim attempt
    // above was rejected - would unconditionally blank
    // activeActionMessageId and unmount whichever message legitimately
    // owns it, even though that message's own hover state never changed.
    if (imkit.activeActionMessageId === message.value.id) {
      imkit.$patch({ activeActionMessageId: '' })
    }
  }

  // The cell that owns the active action slot can disappear without ever
  // firing a mouseleave/setShowActions(false) - virtua recycling it out from
  // under a stationary cursor, its room being switched away from, or the
  // whole list tearing down. None of those paths emit a DOM event, so
  // without this the store's activeActionMessageId would keep pointing at a
  // message.id that no longer has a mounted cell, and (via
  // ChatRoom.vue's actionClaimLocked wiring) could leave the list
  // permanently unhoverable. Release unconditionally on unmount, but only
  // when this cell is still the current owner - a cell that never claimed
  // the slot, or already lost it to another message, must not blank
  // someone else's legitimate ownership.
  onUnmounted(() => {
    if (imkit.activeActionMessageId === message.value.id) {
      imkit.$patch({ activeActionMessageId: '' })
    }
  })

  // Reply and edit are mutually exclusive — the composer can only be doing
  // one — but only one direction enforced it: ChatRoom's editingMessageId
  // watcher cleared replyId, while starting a reply left editingMessageId
  // set, so both preview strips rendered at once. Edit-then-reply showed two;
  // reply-then-edit did not, which is the signature of a one-sided guard.
  //
  // Cleared here, in one atomic patch, rather than by a second watcher
  // mirroring the first: two watchers that each clear the other's state fire
  // in the same flush and race, and the surviving value depends on watcher
  // order. That was tried and broke the existing edit-prefill test.
  //
  // Clearing editingMessageId also empties the composer, via the else branch
  // of that same watcher — which is correct: starting a reply abandons the
  // edit, and leaving the edited text in the box would send it as the reply.
  const reply = () => {
    setShowActions(false)
    imkit.$patch({ replyId: message.value.id, editingMessageId: '' })
  }

  const edit = () => {
    setShowActions(false)
    imkit.$patch({ editingMessageId: message.value.id })
  }

  const copy = () => {
    setShowActions(false)
    let text = ''
    switch (message.value.type) {
      case MessageType.Text:
        text = (message.value as TextMessage).text
        break
      case MessageType.Mixed:
        text = (message.value as MixedMessage).text
        break
      case MessageType.Location:
        text = (message.value as LocationMessage).address
        break
      default:
        break
    }
    navigator.clipboard.writeText(text)
  }

  const translate = () => {
    setShowActions(false)
    imkit.translateMessage(message.value)
  }

  const deleteFailedMessage = () => {
    imkit.deleteMessages([message.value.id])
  }

  const deleteMessage = () => {
    if (room.value?.isSuperuser && room.value.isGroup) {
      const { open } = useModal({
        component: DeleteMessageModal,
        attrs: {
          messageId: message.value.id,
          roomId: message.value.roomId
        }
      })
      open()
    } else {
      const { open } = useModal({
        component: DeleteMessageConfirmModal,
        attrs: {
          messageId: message.value.id,
          deleteType: 'me'
        }
      })
      open()
    }
  }

  const unsendMessage = () => {
    setShowActions(false)
    const { open } = useModal({
      component: UnsendMessageModal,
      attrs: {
        messageId: message.value.id,
        roomId: message.value.roomId
      }
    })
    open()
  }

  const retry = async () => {
    try {
      await imkit.retryMessage(message.value)
    } catch (error) {
      console.error('Failed to retry message', error)
    }
  }

  const selectEmoji = async (emoji: string) => {
    setShowActions(false)
    const isEmojiInReactions = reactions.value.some(
      (reaction) =>
        reaction.reaction === emoji && reaction.client === userId.value
    )
    try {
      if (isEmojiInReactions) {
        await imkit.deleteReaction({
          messageId: message.value.id,
          reaction: emoji
        })
      } else {
        await imkit.sendReaction({
          messageId: message.value.id,
          reaction: emoji
        })
      }
    } catch (error) {
      // A failed reaction toggle must not surface as an unhandled rejection;
      // the optimistic UI self-heals on the next sync. Surface for diagnostics.
      console.error('[selectEmoji] reaction toggle failed:', error)
    }
  }

  return {
    // 權限
    canCopy,
    canReply,
    canTranslate,
    canEdit,
    isEdited,
    // Room 相關
    room,
    // Actions
    setShowActions,
    reply,
    edit,
    copy,
    translate,
    deleteFailedMessage,
    deleteMessage,
    unsendMessage,
    retry,
    selectEmoji
  }
}
