<script setup lang="ts">
import { computed } from 'vue'
import { resolveStickerUrl } from '../runtime/stickerAsset'
import { StickerMessage } from './../classes/message'
const props = defineProps<{ message: StickerMessage }>()
const src = computed(() => {
  if (props.message.stickerUrl) {
    return props.message.stickerUrl
  }
  return resolveStickerUrl(
    `/sticker/${props.message.stickerId.split('-')[0]}/${
      props.message.stickerId
    }.png`
  )
})
</script>

<template>
  <img
    :src="src"
    :alt="$t('sticker')"
    draggable="false"
    class="h-32 w-32 border-0 object-contain [-webkit-touch-callout:none] [-webkit-user-select:none]"
  />
</template>

<style scoped></style>
