import { sha1Bytes } from './hash'
type IMImage = {
  id: string
  width: number
  height: number
  thumbnailUrl: string
  originalUrl: string
}
export const file2image = (file: File): Promise<IMImage> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      const image = new Image()
      image.src = reader.result as string
      image.onload = async () => {
        try {
          resolve({
            // Hash the data URL's UTF-8 bytes off the main thread. hash-wasm's
            // sha1(string) already UTF-8-encoded internally, so encoding here
            // yields the identical hex — the content id is unchanged.
            id: await sha1Bytes(new TextEncoder().encode(image.src)),
            width: image.width,
            height: image.height,
            thumbnailUrl: image.src,
            originalUrl: image.src
          })
        } catch (error) {
          reject(error)
        }
      }
      image.onerror = () => reject(new Error('Could not load image'))
    }
    reader.onerror = () => {
      reject(reader.error)
    }
    reader.readAsDataURL(file)
  })
}
export default IMImage
