import { useMediaQuery } from '@vueuse/core'
import dayjs from 'dayjs'
import type { VirtualizerHandle } from 'virtua/vue'
import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
  watch,
  type ComputedRef,
  type Ref
} from 'vue'
import Message, { MessageType } from '../classes/message'
import type Room from '../classes/room'
import type Settings from '../classes/settings'
import { getConfig } from '../runtime/config'
import { getMessageEntryAnimation } from '../runtime/messageEntryAnimation'
import { getSocket } from '../runtime/socket'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import { createMessageEntryScroll } from '../utils/messageEntryScroll'
import { createMessageNavigationScroll } from '../utils/messageNavigationScroll'
import { bumpActionsHandoffGuard } from './useActionsHandoffGuard'

type UseMessageListStateOptions = {
  room: Ref<Room | undefined>
  scrollEl: Ref<HTMLElement | null>
  // True while a message-anchored menu (the long-press overlay, a row popover)
  // is open. Such a menu is positioned against the message's on-screen rect, so
  // the list must hold still underneath it — see the resize observer below.
  isMessageMenuOpen?: Ref<boolean> | ComputedRef<boolean>
}

type ScrollAlign = NonNullable<
  Parameters<VirtualizerHandle['scrollToIndex']>[1]
>['align']

type VirtualizerLike = Pick<
  VirtualizerHandle,
  'scrollOffset' | 'scrollSize' | 'viewportSize' | 'scrollToIndex' | 'scrollTo'
>

type ScrollToBottomOptions = {
  animation?: 'entry' | 'native'
  restartEntry?: boolean
}

export type UseMessageListStateReturn = {
  jumpToLatest: () => Promise<void>
  isInitialLoaded: Ref<boolean>
  isLatestMessageVisible: Ref<boolean>
  isNearBottom: () => boolean
  isPrepending: Ref<boolean>
  isRequesting: ComputedRef<boolean>
  isScrollToBottomVisible: ComputedRef<boolean>
  messageListKey: Ref<number>
  onVlResize: () => Promise<void>
  onVlScroll: (offset: number) => void
  onVlScrollEnd: () => void
  reloadData: (roomId: string, resetInitialLoaded?: boolean) => Promise<void>
  scrollToBottom: (options?: ScrollToBottomOptions) => Promise<void>
  setVl: (el: unknown) => void
  sortedMessages: ComputedRef<Message[]>
  tobottom: () => Promise<void>
  totop: () => Promise<void>
  vl: Ref<VirtualizerLike | null>
}

const BOTTOM_OFFSET_THRESHOLD = 24

export const useMessageListState = ({
  room,
  scrollEl,
  isMessageMenuOpen
}: UseMessageListStateOptions): UseMessageListStateReturn => {
  const imkit = useImkitStore()
  const config = getConfig()

  const selectedRoomId = computed(() => imkit.selectedRoomId)
  const settings = computed((): Settings => config.settings)
  const isRequesting = computed(
    () => !!imkit.isRequesting[`/rooms/${imkit.selectedRoomId}/messages/v3`]
  )
  const sortedMessages = computed((): Message[] => {
    const typingMessages = Object.keys(imkit.isTyping)
      .filter((key) => !imkit.blockedUsers[key])
      .map(
        (key) =>
          new Message({
            _id: key,
            messageType: 'typing',
            sender: {
              _id: key
            }
          })
      )
    return (
      imkit.messageMultiLists
        .get(imkit.selectedRoomId)
        ?.main?.array()
        .concat(typingMessages) ?? []
    )
  })
  // Derive from sortedMessages instead of walking main.array() a second time:
  // realMessages is sortedMessages minus the typing placeholders it appends
  // (typing nodes have a uid-keyed id, not a real message id). One list walk per
  // recompute now feeds both, instead of one walk each (M42).
  const realMessages = computed(() =>
    sortedMessages.value.filter(
      (message) => message.type !== MessageType.Typing
    )
  )
  const lastRealMessage = computed(() => realMessages.value.at(-1))
  const navigationTargetId = computed(() => imkit.navigationTargetId)
  const isNavigatingToMessage = computed(() => imkit.isNavigatingToMessage)

  const vl = ref<VirtualizerLike | null>(null)
  const messageListKey = ref(0)
  const setVl = (el: unknown) => {
    if (el !== vl.value) {
      const preparing = isNativeScrollPreparing
      stopEntryScroll()
      // A segment remount replaces refs while the same latest request prepares.
      isNativeScrollPreparing = preparing
    }
    vl.value = (el as VirtualizerLike | null) ?? null
  }
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)')
  let isEntryScroll = false
  let isEntryMeasurementPending = false
  let isNativeScrollPending = false
  let isNativeScrollPreparing = false
  let isNativeScrollToTail = false
  let isNativeScrollActive = false
  let nativeScrollTargetOffset = 0
  let nativeScrollStartOffset = 0
  let nativeScrollHasAdvanced = false
  let requestNativeScroll: (() => void) | undefined
  let scrollRevision = 0
  let isUnmounted = false
  let finishedEntryOffset = 0
  let finishedEntryViewportSize = 0
  const getEntryOffset = () =>
    scrollEl.value?.scrollTop ?? vl.value?.scrollOffset ?? 0
  const getEntryViewportSize = () =>
    scrollEl.value?.clientHeight ?? vl.value?.viewportSize ?? 0
  const entryScroll = createMessageEntryScroll({
    getOffset: getEntryOffset,
    getTarget: () => {
      const scroller = scrollEl.value
      return Math.max(
        0,
        scroller && scroller.clientHeight > 0
          ? scroller.scrollHeight - scroller.clientHeight
          : (vl.value?.scrollSize ?? 0) - (vl.value?.viewportSize ?? 0)
      )
    },
    getViewportSize: getEntryViewportSize,
    setOffset: (offset) => {
      // Virtua's imperative scrollTo replays its target on later measurements.
      // Each animation frame must write once so a stale replay cannot undo user input.
      if (scrollEl.value)
        scrollEl.value.scrollTo({ top: offset, behavior: 'instant' })
      else vl.value?.scrollTo(offset)
    },
    onFinish: () => {
      isEntryScroll = false
      finishedEntryOffset = getEntryOffset()
      finishedEntryViewportSize = getEntryViewportSize()
    },
    onCancel: () => stopEntryScroll()
  })
  const navigationScroll = createMessageNavigationScroll({
    getOffset: getEntryOffset,
    getMaxOffset: () =>
      Math.max(
        0,
        (scrollEl.value?.scrollHeight ?? vl.value?.scrollSize ?? 0) -
          getEntryViewportSize()
      ),
    setOffset: (offset) => {
      const scroller = scrollEl.value
      scroller?.scrollTo({ top: offset, behavior: 'instant' })
      if (
        isNativeScrollToTail &&
        scroller &&
        scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop <= 1
      )
        isLatestMessageVisible.value = false
    },
    onCancel: () => stopEntryScroll()
  })
  const stopEntryScroll = () => {
    isEntryScroll = false
    isEntryMeasurementPending = false
    isNativeScrollPending = false
    isNativeScrollPreparing = false
    isNativeScrollToTail = false
    isNativeScrollActive = false
    nativeScrollHasAdvanced = false
    requestNativeScroll = undefined
    scrollRevision++
    entryScroll.cancel()
    navigationScroll.cancel()
  }
  const scrollToIndexWithNativeAnimation = async (
    index: number,
    align: ScrollAlign
  ) => {
    stopEntryScroll()
    if (!vl.value) return
    const targetId = sortedMessages.value[index]?.id
    isNativeScrollPending = !reducedMotion.value
    isNativeScrollActive = isNativeScrollPending
    isNativeScrollToTail = align === 'end'
    const revision = scrollRevision
    // Claim navigation before flushing queued tail follows, then let Vue update
    // the virtual list before Virtua measures the smooth-scroll range.
    if (isNativeScrollPending) await nextTick()
    if (revision !== scrollRevision || !vl.value) return
    requestNativeScroll = () => {
      // An in-flight history page can move the target while measurement waits.
      const targetIndex =
        align === 'end'
          ? sortedMessages.value.length - 1
          : sortedMessages.value.findIndex((message) => message.id === targetId)
      if (targetIndex < 0) {
        stopEntryScroll()
        return
      }
      vl.value?.scrollToIndex(targetIndex, {
        align,
        ...(isNativeScrollPending && { smooth: true })
      })
    }
    requestNativeScroll()
  }
  const onVlResize = async () => {
    if (!isNativeScrollPending) return
    const revision = scrollRevision
    // Prepend corrections can cancel Virtua's smooth request while it measures
    // the path. Resume after those corrections have flushed, only until motion starts.
    await nextTick()
    if (revision === scrollRevision && isNativeScrollPending)
      requestNativeScroll?.()
  }
  const onUserScrollIntent = () => stopEntryScroll()
  const onVlScrollEnd = () => {
    if (
      entryScroll.isRunning() ||
      navigationScroll.isRunning() ||
      isNativeScrollPreparing ||
      isEntryMeasurementPending ||
      isNativeScrollPending
    )
      return
    // Virtua debounces scroll-end by 150ms. An older scroll can finish after
    // a new entry starts but before its first animation frame.
    const scroller = scrollEl.value
    const remaining =
      scroller && scroller.clientHeight > 0
        ? scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight
        : vl.value
          ? vl.value.scrollSize - vl.value.scrollOffset - vl.value.viewportSize
          : 0
    if (
      isNativeScrollActive &&
      scroller &&
      (!isNativeScrollToTail || remaining > 1) &&
      Math.abs(scroller.scrollTop - nativeScrollTargetOffset) > 1
    ) {
      // An older end can arrive before the first native frame. Once motion has
      // started, a non-target end means the browser or host interrupted it.
      if (Math.abs(scroller.scrollTop - nativeScrollStartOffset) > 1)
        stopEntryScroll()
      return
    }
    // A debounce from the previous segment must not enable paging before
    // history navigation reaches its measured target.
    if (
      isNativeScrollActive &&
      !isNativeScrollToTail &&
      scroller &&
      Math.abs(scroller.scrollTop - nativeScrollTargetOffset) > 1
    )
      return
    isNativeScrollActive = false
    if (isNativeScrollToTail && scroller && scroller.clientHeight > 0) {
      const tail = Math.max(0, scroller.scrollHeight - scroller.clientHeight)
      stopEntryScroll()
      // The browser owns desktop motion; settle row measurements after it ends.
      if (remaining > 1) scroller.scrollTo({ top: tail, behavior: 'instant' })
      isLatestMessageVisible.value = false
      return
    }
    if (remaining <= 1) stopEntryScroll()
  }
  const isInitialLoaded = ref(false)
  const isLatestMessageVisible = ref(false)
  const isAwayFromBottom = ref(false)
  const isNavigating = ref(false)
  const isBackgroundRefreshing = ref(false)
  const isReconnectResyncing = ref(false)
  // Rooms whose reconnect recovery was deferred (reader in history, another
  // loader in flight, …). Keyed by room so a deferral recorded for one room is
  // never consumed by a spurious resync of another after a room switch.
  const pendingResyncRoomIds = ref<ReadonlySet<string>>(new Set())
  const initialUnreadCount = ref(0)
  const isPrepending = ref(false)

  const markPendingResync = (roomId: string) => {
    if (pendingResyncRoomIds.value.has(roomId)) return
    pendingResyncRoomIds.value = new Set(pendingResyncRoomIds.value).add(roomId)
  }
  const clearPendingResync = (roomId: string) => {
    if (!pendingResyncRoomIds.value.has(roomId)) return
    const next = new Set(pendingResyncRoomIds.value)
    next.delete(roomId)
    pendingResyncRoomIds.value = next
  }

  // The scroller's own height, and the offset it held, as of the last frame in
  // which the two were consistent with each other. Both are read off the DOM
  // rather than off the virtualizer: virtua caches `scrollOffset` from scroll
  // events, so the two disagree in exactly the frame that matters here.
  let prevClientHeight = 0
  let prevScrollTop = 0
  let wasAtBottom = false
  let visibilityHiddenAt = 0

  const isNearBottom = () => {
    if (!vl.value) return false
    return (
      vl.value.scrollSize - vl.value.scrollOffset - vl.value.viewportSize <
      BOTTOM_OFFSET_THRESHOLD
    )
  }

  // Corner scroll-to-bottom button (ported from imkit-ios-sdk `bottomButton`):
  // visible only when scrolled away from bottom AND the latest-message banner
  // is hidden — the two affordances are mutually exclusive, as on iOS.
  const isScrollToBottomVisible = computed(
    () => isAwayFromBottom.value && !isLatestMessageVisible.value
  )

  const scrollToBottom = async ({
    animation,
    restartEntry = false
  }: ScrollToBottomOptions = {}) => {
    if (animation !== 'entry') stopEntryScroll()
    isLatestMessageVisible.value = false
    isAwayFromBottom.value = false
    if (!vl.value) return
    const last = sortedMessages.value.length - 1
    if (last < 0) return
    if (animation === 'native' && !reducedMotion.value) {
      return scrollToIndexWithNativeAnimation(last, 'end')
    }
    if (animation === 'entry' && !reducedMotion.value) {
      navigationScroll.cancel()
      isNativeScrollActive = false
      isNativeScrollPending = false
      isNativeScrollToTail = false
      // Let Virtua measure the destination and cancel any older imperative
      // scroll. Its smooth request is handled by the container adapter below.
      isEntryMeasurementPending = true
      vl.value.scrollToIndex(last, { align: 'end', smooth: true })
      entryScroll.start(restartEntry)
      return
    }
    const list = vl.value
    const revision = scrollRevision
    const roomId = selectedRoomId.value
    list.scrollToIndex(last, { align: 'end' })
    await nextTick()
    if (
      isUnmounted ||
      revision !== scrollRevision ||
      roomId !== selectedRoomId.value ||
      list !== vl.value
    )
      return
    list.scrollToIndex(last, { align: 'end' })
  }

  const jumpToLatest = async () => {
    const roomId = selectedRoomId.value
    stopEntryScroll()
    // The visible history segment can end before the newest cached segment.
    // Explicit navigation skips that gap; ordinary edge scrolling still pages
    // forward through it in tobottom().
    isNavigating.value = false
    const cache = imkit.messageMultiLists.get(roomId)
    const replacesSegment =
      cache?.main && cache.tail && cache.main !== cache.tail
    isNativeScrollPreparing = !!replacesSegment
    imkit.navigateToLatest()
    // Virtua caches heights by index. A disjoint segment needs fresh row measurements.
    if (replacesSegment) messageListKey.value++
    const navigationRevision = imkit.navigationRevision
    await nextTick()
    const revision = scrollRevision
    const list = vl.value
    if (replacesSegment) {
      // Let replacement rows reach layout and ResizeObserver before Virtua freezes
      // the row offsets for its smooth request.
      await new Promise<void>((resolve) =>
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
      )
    }
    if (
      isUnmounted ||
      scrollRevision !== revision ||
      vl.value !== list ||
      selectedRoomId.value !== roomId ||
      imkit.navigationRevision !== navigationRevision
    )
      return
    await scrollToBottom({ animation: 'native' })
  }

  const resizeObserver = new ResizeObserver((entries) => {
    const entry = entries[0]
    if (!entry) return
    const el = entry.target as HTMLElement
    const newHeight = el.clientHeight
    // Re-anchoring the list while a message menu is open tears the menu away
    // from the message it points at, and the re-render can recycle the cell
    // that owns it. The keyboard collapse that opening the menu triggers in a
    // webview lands here within a frame or two, so this is the common case,
    // not an edge one — hold the offset and just re-baseline (issue #18).
    if (isMessageMenuOpen?.value) {
      prevClientHeight = newHeight
      prevScrollTop = el.scrollTop
      return
    }
    let heldOffset: number | null = null
    if (prevClientHeight && vl.value) {
      if (isEntryScroll) {
        // Clearing a multiline composer resizes the viewport during the entry scroll.
        // Keep following the new tail instead of restoring the previous offset.
        void scrollToBottom({ animation: 'entry' })
      } else if (wasAtBottom) {
        void scrollToBottom()
      } else {
        // Growing the viewport can clamp the old offset to the new maximum
        // before ResizeObserver runs. Only that clamp needs the saved offset;
        // otherwise the current offset may include Virtua's prepend correction.
        const wasClamped =
          newHeight > prevClientHeight &&
          prevScrollTop > el.scrollTop &&
          Math.abs(el.scrollTop - Math.max(0, el.scrollHeight - newHeight)) <= 1
        const target = Math.max(
          0,
          (wasClamped ? prevScrollTop : el.scrollTop) +
            (prevClientHeight - newHeight)
        )
        if (Math.abs(target - el.scrollTop) > 1) vl.value.scrollTo(target)
        heldOffset = target
      }
    }
    prevClientHeight = newHeight
    prevScrollTop = heldOffset ?? el.scrollTop
  })

  const TOP_THRESHOLD_FACTOR = 1.5
  const TOP_THRESHOLD_MIN = 200
  const BOTTOM_EDGE_THRESHOLD = 100
  let wasAtBottomEdge = false

  // ChatRoom.vue swaps rooms in-place (no unmount) via reloadData, so the
  // closure-level scroll flags above persist across switches; reset them when
  // the selected room changes.
  watch(selectedRoomId, () => {
    // Row indexes belong to a room; do not reuse another room's height cache.
    messageListKey.value++
    stopEntryScroll()
    wasAtBottomEdge = false
    wasAtBottom = false
    prevClientHeight = 0
    prevScrollTop = 0
    isAwayFromBottom.value = false
  })

  const getScrollSize = () => vl.value?.scrollSize ?? 0
  const getClientSize = () => vl.value?.viewportSize ?? 0
  const getTopThreshold = () =>
    Math.max(getClientSize() * TOP_THRESHOLD_FACTOR, TOP_THRESHOLD_MIN)

  const onVlScroll = (offset: number) => {
    if (!vl.value) return
    // Remember where the reader is, so the next resize can put them back.
    // Skipped in the frame a resize has already landed in layout but the
    // observer above has not run yet: the browser clamps `scrollTop` into the
    // new box during that layout and fires a scroll event for it, and taking
    // that as the reader's own position would bake the clamp in and defeat the
    // correction below.
    const scroller = scrollEl.value
    if (scroller && scroller.clientHeight === prevClientHeight) {
      // Entry and latest navigation move downward. A reverse scroll can come from the
      // scrollbar or a host without wheel/touch/key events. Yield immediately;
      // viewport and shrinking-range clamps are layout changes, not gestures.
      // A prior WebKit motion can still deliver an upward tick after takeover;
      // the new native motion must advance before its reversal can cancel it.
      if (
        (isEntryScroll ||
          isEntryMeasurementPending ||
          isNativeScrollPending ||
          (isNativeScrollActive &&
            isNativeScrollToTail &&
            nativeScrollHasAdvanced)) &&
        scroller.scrollHeight - scroller.clientHeight >= prevScrollTop - 1 &&
        scroller.scrollTop < prevScrollTop - 1
      ) {
        stopEntryScroll()
      }
      prevScrollTop = scroller.scrollTop
      if (
        isNativeScrollActive &&
        isNativeScrollToTail &&
        scroller.scrollTop > nativeScrollStartOffset + 1
      )
        nativeScrollHasAdvanced = true
    }
    // Scrolling moves every row under a cursor that hasn't moved at all,
    // which fires a real mouseenter on whatever bubble ends up underneath -
    // see useActionsHandoffGuard.ts. Only worth bumping while some
    // message's action dropdown could actually be open.
    if (imkit.activeActionMessageId !== '') {
      bumpActionsHandoffGuard()
    }
    // Measured off the DOM whenever the scroller is available. `isNearBottom`
    // reads virtua's cached `viewportSize`, which is updated by virtua's own
    // resize observer — so in the frame a resize lands it still describes the
    // box the reader had a moment ago. That is how the scroll-to-bottom button
    // could appear on a list sitting exactly at its bottom: WebKit's clamp
    // fires this scroll event with the new geometry already in the DOM but the
    // old height still cached, the button's state is derived here and nowhere
    // else, and nothing scrolls afterwards to correct it (issue #20).
    // A zero-height box is not laid out — a hidden scroller, or a test
    // environment with no layout at all — and has nothing to say, so the
    // virtualizer's own numbers stand there.
    const nearBottom =
      scroller && scroller.clientHeight > 0
        ? scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight <
          BOTTOM_OFFSET_THRESHOLD
        : isNearBottom()
    if (
      !entryScroll.isRunning() &&
      !isEntryMeasurementPending &&
      !isNativeScrollPending &&
      !isNativeScrollPreparing &&
      !isNativeScrollActive &&
      scroller &&
      scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight <= 1
    ) {
      stopEntryScroll()
    }
    if (settings.value.scrollAnchoringEnabled) {
      wasAtBottom = nearBottom
    }
    const atTop = offset < getTopThreshold()
    const atBottomEdge =
      offset + getClientSize() >= getScrollSize() - BOTTOM_EDGE_THRESHOLD
    // Native navigation can pass an edge on its way to the measured target.
    // Paging there changes the scroll range and invalidates the browser's target.
    if (!isNativeScrollActive && !isNativeScrollPreparing) {
      if (atTop) void ensureTopLoaded()
      if (atBottomEdge && !wasAtBottomEdge) void tobottom()
    }
    wasAtBottomEdge = atBottomEdge
    isAwayFromBottom.value = !nearBottom && !isEntryScroll
  }

  const shouldChainTop = () => {
    if (isNativeScrollActive || isNativeScrollPreparing) return false
    if (isPrepending.value) return false
    if (isNavigating.value || isNavigatingToMessage.value) return false
    if (isBackgroundRefreshing.value) return false
    if (!vl.value) return false
    const roomId = room.value?.id
    const total = imkit.numberOfTotalMessages.get(imkit.selectedRoomId)
    if (!roomId || total === undefined) return false
    if (sortedMessages.value.length >= total) return false
    return vl.value.scrollOffset < getTopThreshold()
  }

  const ensureTopLoaded = async () => {
    if (isPrepending.value) return
    while (true) {
      const before = sortedMessages.value.length
      await totop()
      if (sortedMessages.value.length === before) break
      if (!shouldChainTop()) break
    }
  }

  const totop = async () => {
    if (isNativeScrollActive || isNativeScrollPreparing) return
    if (isNavigating.value || isNavigatingToMessage.value) return
    if (isBackgroundRefreshing.value) return

    const roomId = room.value?.id
    const totalMessages = imkit.numberOfTotalMessages.get(imkit.selectedRoomId)
    if (!roomId || totalMessages === undefined) return
    if (sortedMessages.value.length >= totalMessages) return

    const firstRealMessage = imkit.messageMultiLists
      .get(roomId)
      ?.main?.firstRealMessage()
    isPrepending.value = true
    try {
      const messages = await imkit.loadMessages({
        roomId,
        beforeMessageId: firstRealMessage?.id
      })
      if (messages && messages.length > 0) {
        const hasLastRead = !!room.value?.lastReadMessageId[getUid()]
        if (
          initialUnreadCount.value > 0 &&
          settings.value.enableReadReceipt &&
          hasLastRead
        ) {
          await imkit.insertUnreadMessage(initialUnreadCount.value)
        }
        // virtua :shift re-anchors visible scroll on prepend; no explicit
        // scrollToIndex(messages.length) needed anymore
      }
      await waitForPaint()
    } finally {
      isPrepending.value = false
    }
  }

  // Resolves once no load for `path` is in flight; used to retry a forward
  // page that collided with a concurrent load (e.g. a reconnect resync).
  const waitForRequestIdle = (path: string) =>
    new Promise<void>((resolve) => {
      if (!imkit.isRequesting[path]) {
        resolve()
        return
      }
      const stop = watch(
        () => imkit.isRequesting[path],
        (pending) => {
          if (pending) return
          stop()
          resolve()
        }
      )
    })

  const tobottom = async () => {
    if (isNativeScrollActive || isNativeScrollPreparing) return
    if (isNavigating.value || isNavigatingToMessage.value) return

    const roomId = room.value?.id
    if (!roomId) return

    isLatestMessageVisible.value = false

    const maxAttempts = 3
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const cache = imkit.messageMultiLists.get(imkit.selectedRoomId)
      if (cache?.main == cache?.tail) return

      // Anchor on the last real message: sortedMessages appends typing
      // placeholders whose id is the typing user's uid — not a message id the
      // server could resolve. bypassTotalGuard: we only get here while
      // main !== tail — a real inter-segment gap — and after a bg-suspend the
      // cached numberOfTotalMessages is stale, which would short-circuit this
      // forward heal into an empty page.
      const page = await imkit.loadMessages({
        roomId,
        afterMessageId: lastRealMessage.value?.id,
        bypassTotalGuard: true
      })
      if (page !== null) return
      // null = skipped: a concurrent load (e.g. a reconnect resync) held the
      // endpoint and nothing was fetched. Wait for it to settle and retry —
      // it may itself have healed the gap, which the loop re-checks above.
      await waitForRequestIdle(`/rooms/${roomId}/messages/v3`)
      if (room.value?.id !== roomId) return
    }
    // Exhausted retries with the gap still unhealed: surface it — silence here
    // is indistinguishable from "already at the latest".
    console.warn(
      `[imkit] tobottom gave up after ${maxAttempts} colliding loads; forward gap in room ${roomId} not healed`
    )
  }

  const waitForPaint = () =>
    new Promise<void>((resolve) =>
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
    )

  const finishLoad = async (
    roomId: string,
    numberOfUnread: number,
    resetInitialLoaded: boolean,
    gapUnhealed = false
  ) => {
    const uid = getUid()
    const hasLastRead = !!room.value?.lastReadMessageId[uid]
    const hasUnread = settings.value.enableReadReceipt && numberOfUnread > 0
    const shouldShowDivider = hasUnread && hasLastRead
    // A background resync (resetInitialLoaded=false, e.g. a socket reconnect)
    // with nothing new must not disturb the unread divider the reader may be
    // using as a place marker, nor zero the count that re-inserts it on
    // prepend — a 2s WiFi blip would otherwise delete it mid-read.
    const keepUnreadDivider = !resetInitialLoaded && numberOfUnread === 0
    if (!keepUnreadDivider) {
      initialUnreadCount.value = numberOfUnread
    }
    // Never acknowledge messages the user cannot have seen: a reconnect
    // recovery can run while the tab is hidden (socket re-auth in a background
    // window). Same convention as the live-message path; the <60s visibility
    // return marks the room read once the user actually comes back.
    // gapUnhealed extends the same guarantee to a reader AT the tail when the
    // disconnect gap was too wide for the bounded backfill: the fetched latest
    // page is shown, but an unfetched hole still sits above it, so advancing
    // lastRead would acknowledge messages still buried in that hole. The
    // receipt is sent later, once forward paging merges the segments.
    const canMarkRead = typeof document === 'undefined' || !document.hidden
    if (hasUnread && canMarkRead && !gapUnhealed) {
      imkit.updateLastRead(roomId)
    }
    if (shouldShowDivider) {
      await imkit.insertUnreadMessage(numberOfUnread)
    } else if (!keepUnreadDivider) {
      imkit.removeUnreadMessage()
    }
    if (room.value?.isSuperuser) {
      imkit.getBlockList(room.value.id)
    }
    for (const message of imkit.deliveringMessages.values()) {
      if (message.roomId === roomId) {
        imkit.pushMessage(message)
      }
    }
    await waitForPaint()
    if (shouldShowDivider && resetInitialLoaded) {
      const unreadDividerId = `unread-divider-${selectedRoomId.value}`
      const index = sortedMessages.value.findIndex(
        (message) => message.id === unreadDividerId
      )
      if (index !== -1) {
        // Two passes for the same reason scrollToBottom takes two: the rows
        // between here and the divider are still on the 69px estimate, so the
        // first landing is off by the estimate error. Correcting it after the
        // reveal is exactly the jump this positioning exists to avoid.
        vl.value?.scrollToIndex(index, { align: 'start' })
        await nextTick()
        vl.value?.scrollToIndex(index, { align: 'start' })
        isInitialLoaded.value = true
        return
      }
    }
    // Anchor to the bottom on an initial load; on a background resync
    // (resetInitialLoaded=false, e.g. a socket reconnect) only follow the tail
    // when the user is already near the bottom — don't yank a reader of history.
    if (resetInitialLoaded || isNearBottom()) {
      // Awaited: scrollToBottom's second pass is what actually lands on the
      // tail, and revealing between the two passes shows the first pass's
      // estimate error as a jump.
      await scrollToBottom()
    }
    isInitialLoaded.value = true
  }

  // Returns the room's unread count, or null when a load was skipped because
  // it collided with an in-flight request — nothing was recovered and the
  // caller must retry instead of treating the room as up to date.
  const fetchAndLoadMessages = async (
    roomId: string,
    bypassTotalGuard = false
  ): Promise<number | null> => {
    // The reconnect gap is "fetched latest page ↔ pre-fill tail segment":
    // anchor on the pre-fill tail's newest message so the backfill stops once
    // they share a segment. Keying on segment count alone would burn the page
    // budget on permanently disjoint jump-to-message residue every reconnect.
    const tailAnchorId = bypassTotalGuard
      ? (imkit.messageMultiLists.get(roomId)?.tail?.tail?.id ?? null)
      : null
    await imkit.fetchRoom(roomId)
    if (imkit.selectedRoomId !== roomId) return 0
    const numberOfUnread = room.value?.numberOfUnread ?? 0

    // On a reconnect recovery the cached numberOfTotalMessages is stale (the dead
    // socket never bumped it), so the latest-page refetch must bypass the
    // stale-total short-circuit; on a normal initial load the guard is wanted.
    const latestPage = await imkit.loadMessages({
      roomId,
      ...(bypassTotalGuard && { bypassTotalGuard })
    })
    if (latestPage === null) return null
    if (imkit.selectedRoomId !== roomId) return numberOfUnread

    const maxPages = 10
    let pages = 0
    // Keep paging backward while either we're short of the unread count OR (on
    // a reconnect recovery only) the latest page landed as a disjoint segment
    // from the pre-fill tail — a gap larger than one page opened during the
    // disconnect, which the single latest page can't bridge. The gap counts as
    // closed once the pre-fill tail's newest message shares a segment with the
    // new tail; stale jump-to-message residue keeps the segment count > 1
    // forever and must not retrigger the backfill. Bounded by maxPages so a
    // huge gap still terminates.
    const hasDisjointGap = () => {
      if (!bypassTotalGuard || !tailAnchorId) return false
      const multi = imkit.messageMultiLists.get(roomId)
      if (!multi || (multi.length ?? 1) <= 1) return false
      return !multi.tail?.contains(tailAnchorId)
    }
    while (
      (realMessages.value.length < numberOfUnread || hasDisjointGap()) &&
      pages < maxPages
    ) {
      const firstRealMessage = imkit.messageMultiLists
        .get(roomId)
        ?.main?.firstRealMessage()
      if (!firstRealMessage) break

      const prevCount = realMessages.value.length
      const page = await imkit.loadMessages({
        roomId,
        beforeMessageId: firstRealMessage.id,
        ...(bypassTotalGuard && { bypassTotalGuard })
      })
      if (page === null) return null
      if (realMessages.value.length === prevCount) break
      if (imkit.selectedRoomId !== roomId) return numberOfUnread
      pages++
    }
    return numberOfUnread
  }

  // fetchAndLoadMessages with one retry after a colliding in-flight load
  // settles. A null ("skipped, nothing recovered") coerced to 0 unread would
  // drop the divider and skip updateLastRead off a load that never ran; a
  // second null means something is still busy — defer to the pending-resync
  // machinery rather than loop.
  const fetchAndLoadMessagesSettled = async (
    roomId: string,
    bypassTotalGuard = false
  ): Promise<number | null> => {
    const first = await fetchAndLoadMessages(roomId, bypassTotalGuard)
    if (first !== null) return first
    await waitForRequestIdle(`/rooms/${roomId}/messages/v3`)
    if (imkit.selectedRoomId !== roomId) return null
    return fetchAndLoadMessages(roomId, bypassTotalGuard)
  }

  const backgroundRefresh = async (roomId: string) => {
    isBackgroundRefreshing.value = true
    try {
      const numberOfUnread = await fetchAndLoadMessagesSettled(roomId)
      if (imkit.selectedRoomId !== roomId) return
      if (numberOfUnread === null) {
        markPendingResync(roomId)
        return
      }
      await finishLoad(roomId, numberOfUnread, true)
    } catch (error) {
      console.error('Background refresh failed:', error)
    } finally {
      isBackgroundRefreshing.value = false
    }
  }

  // finishLoad anchors an initial load on the unread divider rather than the
  // tail. The cached-path reveal below has to predict the same answer from
  // cached room state: revealing at the tail and letting the refreshed load
  // jump to the divider a round trip later is the very jump the reveal exists
  // to remove. The prediction can only be wrong when the cached unread count
  // is stale, which costs the old behaviour, never worse.
  const expectsUnreadDivider = () => {
    const uid = getUid()
    return (
      settings.value.enableReadReceipt &&
      (room.value?.numberOfUnread ?? 0) > 0 &&
      !!room.value?.lastReadMessageId[uid]
    )
  }

  // Position the cached rows on the tail and reveal them WITHOUT waiting for
  // backgroundRefresh: the cached tail is already the final anchor, so there
  // is nothing the network can tell us that changes where the list belongs.
  // Deliberately not awaited by reloadData — the cached path's whole point is
  // to hand control back immediately and refresh behind the reader.
  const revealCachedTail = async (roomId: string) => {
    await waitForPaint()
    if (imkit.selectedRoomId !== roomId) return
    // backgroundRefresh landed first and has already anchored the list; a
    // second scroll here would fight whatever it chose.
    if (isInitialLoaded.value) return
    await scrollToBottom()
    isInitialLoaded.value = true
  }

  const reloadData = async (roomId: string, resetInitialLoaded = true) => {
    const cachedList = imkit.messageMultiLists.get(roomId)
    const hasCachedMessages = cachedList?.main && cachedList.main.length > 0

    if (hasCachedMessages && resetInitialLoaded) {
      // ChatRoom swaps rooms in place — the scroll container is never
      // unmounted — and sortedMessages is derived straight from the store, so
      // the incoming room's cached rows paint the instant selectedRoomId
      // changes, at the offset the PREVIOUS room left behind. Until this
      // branch lowered isInitialLoaded, the list stayed revealed through that
      // whole window and only reached the tail once backgroundRefresh's round
      // trip returned. That is the reported jump, and it is confined to rooms
      // that have cached messages — hence "only some rooms".
      isInitialLoaded.value = false
      imkit.clearChatRoom()
      imkit.removeUnreadMessage()
      backgroundRefresh(roomId)
      // When a divider is expected the tail is the wrong anchor, so stay
      // hidden and let finishLoad do the positioning and the reveal.
      if (!expectsUnreadDivider()) {
        void revealCachedTail(roomId)
      }
      return
    }

    if (resetInitialLoaded) {
      isInitialLoaded.value = false
    }
    imkit.clearChatRoom()
    let numberOfUnread: number | null
    try {
      numberOfUnread = await fetchAndLoadMessagesSettled(roomId)
    } catch (error) {
      // A thrown load (network blip / 500) must NOT be committed as a
      // successful, read, scrolled empty room: a bare finally would run
      // finishLoad with the initial 0 unread (removing the divider, marking the
      // cleared list read+loaded) and then rethrow as an unhandled rejection out
      // of the ChatRoom watcher. Coerce to the skipped-load path so finishLoad
      // is skipped (isInitialLoaded stays false, the divider is kept).
      // markPendingResync records the room, but for a from-scratch (cacheless)
      // open it has NO immediate consumer: isAtTail is structurally false with
      // no installed list, so the retry watch can't fire. It is picked up only
      // by a later reconnect / >60s-visibility resync, not as an automatic
      // retry of this failure — so the body stays blank until then or a manual
      // room re-select. An inline load-error/retry affordance is a tracked
      // sibling (see HIGH plan).
      console.error('Reload data failed:', error)
      numberOfUnread = null
    }
    if (numberOfUnread === null) {
      markPendingResync(roomId)
    } else {
      await finishLoad(roomId, numberOfUnread, resetInitialLoaded)
    }
  }

  // True while the open room is scrolled to its newest segment (main === tail).
  // A latest-page reload sets main to the newest segment, so it is only safe to
  // run — without yanking the reader — when they are already at the tail.
  const isAtTail = computed(() => {
    const multi = imkit.messageMultiLists.get(selectedRoomId.value)
    return !!multi?.main && multi.main === multi.tail
  })

  // Non-destructively backfill the open room after the socket was dead: refetch
  // the latest page and merge it onto the cached list (no clearChatRoom → no
  // flicker). insert+merge heals BOTH a tail gap and an interior gap — a message
  // older than the cached tail that a live message arriving right after reconnect
  // sealed off (the canonical "A and C shown, B dropped" symptom) — which a
  // tail-only forward-fill cannot reach. finishLoad then advances lastRead when
  // unread remains (so the recovered tail's read receipt is sent and the badge
  // doesn't resurrect) and only follows the tail when the reader is near bottom.
  const softFillOpenRoom = async (roomId: string) => {
    const multi = imkit.messageMultiLists.get(roomId)
    // Reading history (main is an older segment): a latest-page reload would
    // move main to the newest segment and yank the reader to the bottom. Defer
    // until they return to the tail; resyncRooms still refreshes the list entry.
    if (multi?.main && multi.main !== multi.tail) {
      markPendingResync(roomId)
      return
    }
    const mainBefore = multi?.main ?? null
    const readerParked = vl.value ? !isNearBottom() : false
    const numberOfUnread = await fetchAndLoadMessages(roomId, true)
    if (numberOfUnread === null) {
      // Collided with an in-flight load: nothing was recovered — retry once it
      // clears instead of advancing lastRead over a still-missing gap.
      markPendingResync(roomId)
      return
    }
    if (imkit.selectedRoomId !== roomId) return
    // A reader scrolled up inside one merged segment passes the main!==tail
    // check above, but when the gap is too wide for the bounded backfill the
    // fetched latest page stays disjoint and becomes main — collapsing their
    // rendered history to one page. Give them their segment back and finish
    // the heal once forward paging merges the segments at the tail.
    // …but only when the reader's segment is still in the chain: when merge()
    // absorbed it into the fetched page its messages live on in the new main,
    // and restoring the consumed (detached) segment would deadlock the heal —
    // main === tail could never become true again.
    const multiAfter = imkit.messageMultiLists.get(roomId)
    if (
      readerParked &&
      mainBefore &&
      multiAfter &&
      multiAfter.length > 1 &&
      multiAfter.main !== mainBefore &&
      multiAfter.hasSegment(mainBefore)
    ) {
      multiAfter.main = mainBefore
      markPendingResync(roomId)
      return
    }
    // Reader is at the tail but the gap was too wide to bridge: the fetched
    // latest page became a disjoint segment and the reader's prior tail still
    // lives upstream behind an unfetched hole. Show the latest page (don't yank
    // their segment back — they want the newest), but tell finishLoad not to
    // advance lastRead over the hole's still-unseen messages. Deliberately NOT
    // markPendingResync here, unlike the parked-reader branch above: there the
    // restore sets main to an older segment so isAtTail is false and gates the
    // retry watch; here the reader is already at the tail (main === tail), so the
    // gate is open and a re-enrolled resync would re-fire at once — on a gap
    // wider than the page budget the soft-fill stays disjoint and that loops.
    // Forward paging heals the hole; the deferred receipt is then sent by the
    // next inbound message, room re-entry, or reconnect once it is closed.
    const gapUnhealed =
      !!mainBefore &&
      !!multiAfter &&
      multiAfter.length > 1 &&
      multiAfter.main !== mainBefore &&
      multiAfter.hasSegment(mainBefore)
    await finishLoad(roomId, numberOfUnread, false, gapUnhealed)
  }

  // Backfill the open room after the socket was dead. Driven by the
  // reconnectResyncTick watch — bumped by a genuine socket reconnect AND by the
  // >60s visibility return (both via resyncAfterReconnect), so the two converge
  // on one guarded, deduped recovery instead of racing each other.
  // True while any loader that would conflict with a reconnect soft-fill is
  // busy. A blocked resync is deferred per room (markPendingResync) — never
  // dropped — and the retry watch below re-runs it once this clears.
  const resyncBlocked = computed(
    () =>
      isReconnectResyncing.value ||
      isNavigating.value ||
      isNavigatingToMessage.value ||
      isPrepending.value ||
      isBackgroundRefreshing.value ||
      isRequesting.value
  )

  const resyncOpenRoom = () => {
    const roomId = selectedRoomId.value
    if (!roomId) return
    // Don't clobber an in-flight soft-fill, navigation, pagination or room
    // refresh. Remember the deferral and retry once the blocker clears (the
    // retry watch below) — a reconnect during a slow fill can carry messages
    // newer than that fill's snapshot, so dropping it would re-strand them.
    if (resyncBlocked.value) {
      markPendingResync(roomId)
      return
    }
    clearPendingResync(roomId)
    isReconnectResyncing.value = true
    void softFillOpenRoom(roomId)
      .catch((error) => {
        // Network is often still flaky right after a reconnect; a failed
        // backfill must self-heal on the next reconnect, not throw unhandled.
        console.error('Reconnect resync soft-fill failed:', error)
      })
      .finally(() => {
        isReconnectResyncing.value = false
      })
  }

  // A socket reconnect (sleep, network drop) bumps reconnectResyncTick. This is
  // the reliable signal — it fires regardless of why the socket dropped, unlike
  // visibilitychange which never fires on laptop sleep.
  watch(
    () => imkit.reconnectResyncTick,
    () => resyncOpenRoom()
  )

  // Retry a deferred recovery once its blocker clears: every conflicting
  // loader settled AND the reader is back at the tail of the room the deferral
  // belongs to (so a latest-page reload won't yank them). Without this, a
  // reconnect that lands mid-navigation or while reading history would drop
  // the missed-message gap until the next reconnect.
  watch([selectedRoomId, resyncBlocked, isAtTail], () => {
    if (!pendingResyncRoomIds.value.has(selectedRoomId.value)) return
    if (resyncBlocked.value) return
    if (!isAtTail.value) return
    resyncOpenRoom()
  })

  const onVisibilityChange = () => {
    if (document.hidden) {
      visibilityHiddenAt = dayjs().unix()
    } else {
      const hiddenInterval = dayjs().unix() - visibilityHiddenAt
      if (hiddenInterval > 60) {
        const socket = getSocket()
        socket.connect()
        // A long hidden interval is a pseudo-reconnect. When the socket still
        // reports connected it may be half-open (mobile bg-suspend) and no
        // reconnect/auth will ever fire — force the recovery directly. When it
        // is genuinely dead, connect() leads to an auth success whose single
        // recovery path runs resyncAfterReconnect; firing it here too would
        // run the full recovery twice (a second GET /rooms + open-room refill)
        // on every long tab return.
        if (socket.connected) {
          void imkit.resyncAfterReconnect().catch((error) => {
            console.error('Visibility resync failed:', error)
          })
        }
      } else if (
        selectedRoomId.value &&
        room.value &&
        room.value.numberOfUnread > 0
      ) {
        imkit.updateLastRead(selectedRoomId.value)
        imkit.updateRoom({
          id: selectedRoomId.value,
          numberOfUnread: 0,
          isMentioned: false
        })
      }
    }
  }

  const followTailAfterUpdate = (
    announceIfBlocked = false,
    restartEntry = false
  ) => {
    const revision = scrollRevision
    const roomId = selectedRoomId.value
    nextTick(() => {
      if (isUnmounted || roomId !== selectedRoomId.value) return
      if (isNativeScrollPreparing) return
      // Loading a history target and publishing navigationTargetId happen in
      // the same tick. Recheck here, after the target watcher has claimed the
      // scroll, so a tail-follow queued by the list update cannot overwrite it.
      if (isNavigating.value || isNavigatingToMessage.value) {
        if (!isNativeScrollActive) stopEntryScroll()
        if (announceIfBlocked) isLatestMessageVisible.value = true
        return
      }
      if (revision !== scrollRevision) return
      if (vl.value && vl.value.scrollSize <= vl.value.viewportSize) {
        stopEntryScroll()
      }
      void scrollToBottom({
        animation: isEntryScroll ? 'entry' : undefined,
        restartEntry
      })
    })
  }

  watch(reducedMotion, (reduce) => {
    if (reduce && navigationScroll.isRunning()) navigationScroll.finish()
    if (reduce && isEntryScroll) void scrollToBottom()
  })

  watch(
    [
      () => sortedMessages.value.length,
      () => imkit.loadingLinkPreviews.size,
      () => realMessages.value.length,
      lastRealMessage,
      // AI streaming mutates the tail message's text in place — same node, same
      // list length, same object reference (M44/M63) — so none of the sources
      // above fire per token. Track its text length too, so a growing reply
      // keeps re-anchoring to the bottom instead of scrolling off-screen.
      () =>
        (lastRealMessage.value as { text?: string } | undefined)?.text?.length
    ],
    ([, , newRealLen, , newTextLength], [, , oldRealLen, , oldTextLength]) => {
      const entry = lastRealMessage.value
        ? getMessageEntryAnimation(lastRealMessage.value)
        : undefined
      // A batch shares one list scroll. Consume its earlier entries too, so
      // removing the newest message cannot replay a previously visible one.
      for (
        let index = isInitialLoaded.value ? (oldRealLen ?? newRealLen) : 0;
        index < newRealLen - 1;
        index++
      ) {
        const batched = getMessageEntryAnimation(realMessages.value[index]!)
        if (batched) batched.played = true
      }
      if (!isInitialLoaded.value) {
        if (entry) entry.played = true
        return
      }

      const isNewSingleMessage =
        oldRealLen !== undefined && newRealLen - oldRealLen === 1

      if (isBackgroundRefreshing.value) {
        if (entry) entry.played = true
        isLatestMessageVisible.value = false
        return
      }

      if (entry && !entry.played) {
        entry.played = true
        if (isNavigating.value || isNavigatingToMessage.value) {
          if (!isNativeScrollActive) stopEntryScroll()
          if (entry.origin === 'incoming') isLatestMessageVisible.value = true
          return
        }
        // Move the list and the opaque bubble together. Sending from history
        // still jumps directly; confirmations retain the current entry scroll.
        const scroller = scrollEl.value
        // The composer can change the viewport before virtua's size cache
        // catches up. Read the current DOM before the new row is rendered.
        const atBottom =
          scroller && scroller.clientHeight > 0
            ? scroller.scrollHeight -
                scroller.scrollTop -
                scroller.clientHeight <
              BOTTOM_OFFSET_THRESHOLD
            : isNearBottom()
        if (entry.origin === 'incoming' && !isEntryScroll && !atBottom) {
          isLatestMessageVisible.value = true
          return
        }
        // Removing a typing row can clamp the DOM offset before its scroll
        // event arrives. Start reversal detection from this accepted position,
        // so that delayed clamp cannot cancel the new reply's entry.
        if (!isEntryScroll && scroller) prevScrollTop = scroller.scrollTop
        isEntryScroll =
          !reducedMotion.value &&
          Date.now() - entry.createdAt <= 1000 &&
          (isEntryScroll || atBottom)
        isLatestMessageVisible.value = false
        followTailAfterUpdate(entry.origin === 'incoming', true)
        return
      }

      if (
        isEntryScroll &&
        newRealLen === oldRealLen &&
        lastRealMessage.value?.type === MessageType.AIStreaming &&
        newTextLength !== oldTextLength
      ) {
        // Growing text must stay attached to the tail instead of restarting
        // the initial entry scroll for every streamed chunk.
        stopEntryScroll()
        followTailAfterUpdate()
        return
      }

      if (isNewSingleMessage && lastRealMessage.value?.senderId === getUid()) {
        isLatestMessageVisible.value = false
        followTailAfterUpdate()
        return
      }

      if (!vl.value || !scrollEl.value) return
      // A DOM scroll can land before Virtua receives its scroll event. Typing
      // rows must follow the current viewport, not the previous cached offset.
      const scroller = scrollEl.value
      const atBottom =
        scroller.clientHeight > 0
          ? scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight <
            BOTTOM_OFFSET_THRESHOLD
          : isNearBottom()

      if (isNewSingleMessage) {
        isLatestMessageVisible.value = !atBottom
      }

      if (
        (atBottom || isEntryScroll) &&
        !isNavigating.value &&
        !isNavigatingToMessage.value
      ) {
        followTailAfterUpdate()
      }
    },
    // Cached messages can arrive while the host has unmounted ChatRoom.
    // Consume their entries before initial reveal so an echo cannot replay them.
    { immediate: true }
  )

  watch(isNavigatingToMessage, (navigating) => {
    if (navigating) stopEntryScroll()
  })

  watch(navigationTargetId, (newId) => {
    if (!newId) return

    stopEntryScroll()
    isNavigating.value = true
    const element = document.querySelector(
      `[data-message-id="${newId}"]`
    ) as HTMLElement | null
    const listElement = scrollEl.value
    if (element && listElement) {
      const elementRect = element.getBoundingClientRect()
      const listRect = listElement.getBoundingClientRect()
      if (
        elementRect.top < listRect.top ||
        elementRect.bottom > listRect.bottom
      ) {
        const index = sortedMessages.value.findIndex(
          (message) => message.id === newId
        )
        if (index !== -1) void scrollToIndexWithNativeAnimation(index, 'start')
      }
    } else {
      const index = sortedMessages.value.findIndex(
        (message) => message.id === newId
      )
      if (index !== -1) void scrollToIndexWithNativeAnimation(index, 'start')
    }
    imkit.$patch({ navigationTargetId: '' })

    setTimeout(() => {
      const currentElement = document.querySelector(
        `[data-message-id="${newId}"]`
      ) as HTMLElement | null
      if (currentElement) {
        currentElement.classList.remove('animate-message-highlight')
        void currentElement.offsetWidth
        currentElement.classList.add('animate-message-highlight')
        currentElement.addEventListener(
          'animationend',
          () => {
            currentElement.classList.remove('animate-message-highlight')
            isNavigating.value = false
          },
          { once: true }
        )
      } else {
        isNavigating.value = false
      }
    }, 100)
  })

  // Observed whatever `scrollAnchoringEnabled` says. The flag gates the
  // re-anchor-to-the-newest-message branch only — `wasAtBottom` is set in
  // `onVlScroll` and stays false for its whole life while the flag is off, so
  // with the flag off this observer does nothing but hold the bottom edge when
  // the container is resized under it.
  //
  // Holding that edge is not optional, because the resize is the SDK's own:
  // `useViewportHeight` shrinks the chat root when a software keyboard opens,
  // and a scroller that keeps its offset through a 320px shrink is left 320px
  // short of the newest message — the composer then covers what you were just
  // reading (issue #20). A host cannot opt out of a correction for something
  // the SDK did to it.
  //
  // Watched rather than read once in `onMounted`: the scroller lives inside
  // ChatRoom's `v-if="room"`, so on a fixed-roomId mount — tribo's and
  // pinchat's entry path — it is still null when this composable mounts and
  // only appears once the room lands in the store. Reading it at mount there
  // leaves the observer unattached for the life of the instance.
  let restoreScrollTo: (() => void) | undefined
  watch(
    scrollEl,
    (el, previous) => {
      stopEntryScroll()
      restoreScrollTo?.()
      restoreScrollTo = undefined
      if (previous) {
        resizeObserver.unobserve(previous)
        previous.removeEventListener('wheel', onUserScrollIntent)
        previous.removeEventListener('touchstart', onUserScrollIntent)
        previous.removeEventListener('keydown', onUserScrollIntent)
      }
      prevClientHeight = 0
      prevScrollTop = 0
      if (el) {
        const ownScrollTo = Object.getOwnPropertyDescriptor(el, 'scrollTo')
        const scrollTo = el.scrollTo.bind(el)
        // Virtua measures destinations before issuing smooth requests.
        // Route each request to the animation that owns the current scroll.
        el.scrollTo = (options: ScrollToOptions | number = {}, y?: number) => {
          if (typeof options === 'object') {
            if (options.behavior === 'smooth') {
              if (isNativeScrollPending) {
                const followTail = isNativeScrollToTail
                nativeScrollStartOffset = el.scrollTop
                nativeScrollHasAdvanced = false
                nativeScrollTargetOffset = options.top ?? el.scrollTop
                isNativeScrollPending = false
                // Native iOS smooth scrolling can flash blank across a long
                // virtual row. Keep offset writes on the row-painting clock.
                const isIOS =
                  /iPad|iPhone|iPod/.test(navigator.userAgent) ||
                  (navigator.platform === 'MacIntel' &&
                    navigator.maxTouchPoints > 1)
                if (isIOS) {
                  if (
                    !navigationScroll.start(options.top ?? el.scrollTop, {
                      followTail
                    })
                  )
                    isNativeScrollActive = false
                } else scrollTo(options)
                return
              }
              const pending = isEntryMeasurementPending
              isEntryMeasurementPending = false
              if (isEntryScroll) entryScroll.start()
              // The clock can finish before Virtua measures the final row.
              // Settle that destination once, unless user intent canceled it.
              else if (pending) {
                const tail = Math.max(0, el.scrollHeight - el.clientHeight)
                // A reader's reverse scroll event can still be queued. Check
                // the DOM before settling, excluding viewport/range clamps.
                if (
                  el.clientHeight === finishedEntryViewportSize &&
                  tail >= finishedEntryOffset - 1 &&
                  el.scrollTop < finishedEntryOffset - 1
                ) {
                  stopEntryScroll()
                  return
                }
                scrollTo({
                  top: tail,
                  behavior: 'instant'
                })
              }
              return
            }
            scrollTo(options)
          } else scrollTo(options, y ?? 0)
        }
        restoreScrollTo = () => {
          if (ownScrollTo) Object.defineProperty(el, 'scrollTo', ownScrollTo)
          else Reflect.deleteProperty(el, 'scrollTo')
        }
        resizeObserver.observe(el)
        el.addEventListener('wheel', onUserScrollIntent, { passive: true })
        el.addEventListener('touchstart', onUserScrollIntent, { passive: true })
        el.addEventListener('keydown', onUserScrollIntent)
      }
    },
    { immediate: true }
  )

  onMounted(() => {
    document.addEventListener('visibilitychange', onVisibilityChange)
  })

  onUnmounted(() => {
    isUnmounted = true
    stopEntryScroll()
    restoreScrollTo?.()
    document.removeEventListener('visibilitychange', onVisibilityChange)
    resizeObserver.disconnect()
    scrollEl.value?.removeEventListener('wheel', onUserScrollIntent)
    scrollEl.value?.removeEventListener('touchstart', onUserScrollIntent)
    scrollEl.value?.removeEventListener('keydown', onUserScrollIntent)
  })

  return {
    jumpToLatest,
    isInitialLoaded,
    isLatestMessageVisible,
    isNearBottom,
    isPrepending,
    isRequesting,
    isScrollToBottomVisible,
    messageListKey,
    onVlResize,
    onVlScroll,
    onVlScrollEnd,
    reloadData,
    scrollToBottom,
    setVl,
    sortedMessages,
    tobottom,
    totop,
    vl
  }
}
