const NAVIGATION_SCROLL_DURATION_MS = 360

/** Keep virtual-row painting and navigation on the same animation clock. */
export const createMessageNavigationScroll = ({
  getOffset,
  getMaxOffset,
  setOffset,
  onCancel
}: {
  getOffset: () => number
  getMaxOffset: () => number
  setOffset: (offset: number) => void
  onCancel: () => void
}) => {
  let frame: number | undefined
  let generation = 0
  let target = 0
  let followsTail = false
  const clamp = (offset: number) =>
    Math.max(0, Math.min(getMaxOffset(), offset))

  const getTarget = () => clamp(followsTail ? getMaxOffset() : target)

  const cancel = () => {
    generation++
    if (frame !== undefined) cancelAnimationFrame(frame)
    frame = undefined
  }

  const finish = () => {
    cancel()
    setOffset(getTarget())
  }

  const start = (
    offset: number,
    { followTail = false }: { followTail?: boolean } = {}
  ) => {
    cancel()
    target = offset
    followsTail = followTail
    let from = getOffset()
    if (Math.abs(from - getTarget()) <= 1) {
      setOffset(getTarget())
      return false
    }
    const currentGeneration = generation
    const startedAt = performance.now()
    let previousOffset = from
    let previousMax = getMaxOffset()
    const step = (timestamp: number) => {
      if (generation !== currentGeneration) return
      const current = getOffset()
      const max = getMaxOffset()
      if (Math.abs(current - previousOffset) > 1) {
        if (max === previousMax) {
          cancel()
          onCancel()
          return
        }
        // Virtua can correct old row sizes after a history segment changes.
        from += current - previousOffset
      }
      const progress = Math.max(
        0,
        Math.min(1, (timestamp - startedAt) / NAVIGATION_SCROLL_DURATION_MS)
      )
      const eased =
        progress < 0.5 ? 4 * progress ** 3 : 1 - (-2 * progress + 2) ** 3 / 2
      // New row measurements can move the tail after Virtua chooses its target.
      setOffset(clamp(from + (getTarget() - from) * eased))
      previousOffset = getOffset()
      previousMax = getMaxOffset()
      if (generation !== currentGeneration) return
      frame = progress < 1 ? requestAnimationFrame(step) : undefined
    }
    frame = requestAnimationFrame(step)
    return true
  }

  return { start, cancel, finish, isRunning: () => frame !== undefined }
}
