<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { Reaction } from '../classes/message'
import User from '../classes/user'
import { PORTAL_HOST_SELECTOR } from '../runtime/portalHost'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'

defineOptions({
  name: 'ReactionSheet'
})

interface Props {
  reactions: Reaction[]
  /** Initial emoji to show when opening (if null, shows "All" tab) */
  initialEmoji?: string | null
}

interface SumReaction {
  reaction: string
  count: number
  clients: string[]
}

const props = withDefaults(defineProps<Props>(), {
  initialEmoji: null
})

const emit = defineEmits<{
  (e: 'close'): void
  (e: 'selectEmoji', emoji: string): void
}>()

const userId = computed(() => getUid())

/**
 * Only your own reaction is actionable here — there is nothing you may do to
 * someone else's. Rows are gated on this for the click, the cursor AND the
 * hover fill: a hover that leads nowhere reads as an affordance that is
 * broken rather than absent.
 */
const isOwnReaction = (clientId: string) => clientId === userId.value

// Toggling an emoji the user already reacted with is what removes it, so this
// reuses the same path the chips do rather than adding a delete of its own.
const onRowClick = (item: { clientId: string; emoji: string }) => {
  if (!isOwnReaction(item.clientId)) {
    return
  }
  emit('selectEmoji', item.emoji)
}

const imkit = useImkitStore()
const { t } = useI18n()

const users = computed(() => imkit.users as Record<string, User>)

// Aggregate reactions by emoji
const sumReactions = computed(() => {
  const reactionMap = new Map<string, SumReaction>()

  props.reactions.forEach((reaction) => {
    const existing = reactionMap.get(reaction.reaction)
    if (existing) {
      existing.count += 1
      if (!existing.clients.includes(reaction.client)) {
        existing.clients.push(reaction.client)
      }
    } else {
      reactionMap.set(reaction.reaction, {
        reaction: reaction.reaction,
        count: 1,
        clients: [reaction.client]
      })
    }
  })

  return Array.from(reactionMap.values())
})

// Total reaction count for "All" tab
const totalCount = computed(() => {
  return sumReactions.value.reduce((sum, r) => sum + r.count, 0)
})

// Current active tab: null means "All", otherwise the emoji string
// Initialize synchronously to avoid visual jump during slide-up animation
const activeTab = ref<string | null>(
  props.initialEmoji &&
    sumReactions.value.some((r) => r.reaction === props.initialEmoji)
    ? props.initialEmoji
    : null
)

// Get users to display based on active tab
const displayUsers = computed(() => {
  if (activeTab.value === null) {
    // "All" tab: show all users with their reactions
    const userReactions: { clientId: string; emoji: string }[] = []
    props.reactions.forEach((r) => {
      userReactions.push({ clientId: r.client, emoji: r.reaction })
    })
    return userReactions
  } else {
    // Specific emoji tab: show only users who sent this emoji
    const reaction = sumReactions.value.find(
      (r) => r.reaction === activeTab.value
    )
    if (!reaction) return []
    return reaction.clients.map((clientId) => ({
      clientId,
      emoji: activeTab.value!
    }))
  }
})

/**
 * The hint rides INSIDE your own row, as a second line under the name, rather
 * than as a row of its own above it. A separate line had to be spliced into
 * the list — which meant a hand-built render list, because `key` on a
 * `<template v-for>` belongs to the template and TransitionGroup could not
 * then tell the two branches apart. As a subtitle it needs none of that: it is
 * part of the row it describes, so it cannot drift from it and the plain
 * `v-for` comes back.
 */

const getUserName = (clientId: string): string => {
  const user = users.value[clientId]
  return user?.nickname ?? clientId
}

const getUserAvatar = (clientId: string): string => {
  const user = users.value[clientId]
  return user?.avatarUrl ?? ''
}

// Sheet visibility state
const isVisible = ref(false)
const isClosing = ref(false)

onMounted(() => {
  // Trigger entrance animation after mount
  nextTick(() => {
    isVisible.value = true
    // Enable indicator transition after slide-up animation completes
    setTimeout(() => {
      enableIndicatorTransition.value = true
    }, 300)
  })
})

const closeSheet = () => {
  isClosing.value = true
  setTimeout(() => {
    emit('close')
  }, 280) // Match animation duration
}

// Handle backdrop click
const onBackdropClick = () => {
  closeSheet()
}

// Handle escape key
const onKeyDown = (e: KeyboardEvent) => {
  if (e.key === 'Escape') {
    closeSheet()
  }
}

onMounted(() => {
  document.addEventListener('keydown', onKeyDown)
})

onUnmounted(() => {
  document.removeEventListener('keydown', onKeyDown)
})

// Tab indicator position tracking
const tabsRef = ref<HTMLElement | null>(null)
const indicatorStyle = ref({ left: '0px', width: '0px' })
// Disable indicator transition during initial slide-up, enable after sheet appears
const enableIndicatorTransition = ref(false)

const updateIndicatorPosition = () => {
  if (!tabsRef.value) return

  const activeElement = tabsRef.value.querySelector(
    '.tab-active'
  ) as HTMLElement
  if (activeElement) {
    indicatorStyle.value = {
      left: `${activeElement.offsetLeft}px`,
      width: `${activeElement.offsetWidth}px`
    }
  }
}

watch(activeTab, () => {
  nextTick(updateIndicatorPosition)
})

onMounted(() => {
  nextTick(updateIndicatorPosition)
})

// Skip animation on initial render, enable after first tab switch
const enableListAnimation = ref(false)

watch(activeTab, () => {
  enableListAnimation.value = true
})

// Staggered list animation hooks
const onBeforeEnter = (el: Element) => {
  if (!enableListAnimation.value) return

  const element = el as HTMLElement
  element.style.opacity = '0'
  element.style.transform = 'translateY(24px) scale(0.95)'
}

const onEnter = (el: Element, done: () => void) => {
  if (!enableListAnimation.value) {
    done()
    return
  }

  const element = el as HTMLElement
  const index = Number(element.dataset.index) || 0
  const delay = 80 + index * 40 // Start after leave animation, 40ms stagger

  element.style.transition = 'none'

  requestAnimationFrame(() => {
    element.style.transition = `opacity 0.35s cubic-bezier(0.22, 1, 0.36, 1) ${delay}ms, transform 0.4s cubic-bezier(0.22, 1, 0.36, 1) ${delay}ms`
    element.style.opacity = '1'
    element.style.transform = 'translateY(0) scale(1)'
  })

  setTimeout(done, 400 + delay)
}

const onLeave = (el: Element, done: () => void) => {
  if (!enableListAnimation.value) {
    done()
    return
  }

  const element = el as HTMLElement

  // Quick fade out without stagger for cleaner transition
  element.style.transition = 'opacity 0.15s ease-out, transform 0.15s ease-out'
  element.style.opacity = '0'
  element.style.transform = 'scale(0.96)'

  setTimeout(done, 150)
}
</script>

<template>
  <Teleport :to="PORTAL_HOST_SELECTOR">
    <div
      class="fixed inset-0 z-9999"
      :class="[isVisible ? 'pointer-events-auto' : 'pointer-events-none']"
    >
      <!-- Backdrop -->
      <div
        class="absolute inset-0 bg-black/40 transition-opacity duration-300 dark:bg-black/60"
        :class="[isVisible && !isClosing ? 'opacity-100' : 'opacity-0']"
        @click="onBackdropClick"
      />

      <!--
        Was `bg-white/98` + `dark:bg-zinc-800/98`, an opacity-suffixed raw pair
        the codemod does not reach, plus a two-variant arbitrary `shadow-[...]`
        with inline rgba — the only non-`shadow-raised` shadow in src — and
        `rounded-t-[20px]`, which is numerically `rounded-xl` and now says so.

        `bg-panel` is opaque where the old fill was 98% white. The 2% was doing
        nothing a user could see through `backdrop-blur-xl`, and it cost the
        pair a token.
      -->
      <!--
        A bottom sheet below `sm`, a centred dialog at `sm` and up.

        Every property that differs between the two modes is written as a
        `max-sm:` / `sm:` PAIR, with nothing unprefixed. That is not stylistic:
        an unprefixed utility and a variant one are ordered differently in the
        dev stylesheet than in the built one, so `flex sm:hidden` resolved to
        `flex` under `pnpm dev` while `dist/lib.css` had the two in the
        opposite order. A rule that works in production and not in dev (or the
        reverse) is worse than one that never works, so no property is left to
        that ordering. `max-sm:` and `sm:` are exactly complementary — one
        media query matches, never both — so which wins is not a cascade
        question at all.
      -->
      <!-- Sheet -->
      <div
        data-testid="reaction-sheet-panel"
        class="absolute flex flex-col overflow-hidden bg-panel shadow-raised backdrop-blur-xl select-none max-sm:right-0 max-sm:bottom-0 max-sm:left-0 max-sm:max-h-[70vh] max-sm:min-h-[40vh] max-sm:rounded-t-xl max-sm:transition-transform max-sm:duration-300 sm:top-1/2 sm:left-1/2 sm:max-h-[min(70vh,32rem)] sm:w-[min(26rem,calc(100vw-2rem))] sm:-translate-x-1/2 sm:-translate-y-1/2 sm:rounded-lg sm:border sm:border-border sm:transition-[opacity,transform] sm:duration-200"
        :class="[
          isVisible && !isClosing
            ? 'max-sm:translate-y-0 sm:scale-100 sm:opacity-100'
            : 'max-sm:translate-y-full sm:scale-95 sm:opacity-0'
        ]"
      >
        <!-- Drag handle. A grab affordance for a sheet that is dragged, so it
             has no meaning on the desktop dialog. -->
        <div
          data-testid="reaction-sheet-handle"
          class="shrink-0 justify-center pt-3 pb-3 max-sm:flex sm:hidden"
        >
          <div class="h-[5px] w-9 rounded-full bg-border-strong" />
        </div>

        <!-- Title, desktop only. Without it the panel still read as a sheet
             that had wandered onto a desktop: the handle is what named it on
             mobile, and dropping that left nothing at the top at all. -->
        <div
          class="shrink-0 px-5 pt-4 pb-1 text-xl font-semibold text-content max-sm:hidden"
        >
          {{ t('reactions') }}
        </div>

        <!-- Tabs -->
        <div
          ref="tabsRef"
          class="scrollbar-hide relative flex shrink-0 gap-1 overflow-x-auto overflow-y-visible border-b border-border px-4 pt-1 pb-3 sm:pt-4"
        >
          <!-- All tab -->
          <button
            class="relative z-1 flex shrink-0 cursor-pointer items-center gap-1.5 rounded-full border-none bg-transparent px-4 py-2.5 whitespace-nowrap transition-all duration-200 active:scale-[0.96]"
            :class="{ 'tab-active': activeTab === null }"
            @click="activeTab = null"
          >
            <span
              class="text-base font-medium transition-colors duration-200"
              :class="[
                activeTab === null ? 'text-content' : 'text-content-subtle'
              ]"
            >
              {{ t('all') }}
            </span>
            <span
              class="text-base font-semibold transition-colors duration-200"
              :class="[
                activeTab === null ? 'text-content' : 'text-content-subtle'
              ]"
            >
              {{ totalCount }}
            </span>
          </button>

          <!-- Emoji tabs -->
          <button
            v-for="reaction in sumReactions"
            :key="reaction.reaction"
            class="relative z-1 flex shrink-0 cursor-pointer items-center gap-1.5 rounded-full border-none bg-transparent px-4 py-2.5 whitespace-nowrap transition-all duration-200 active:scale-[0.96]"
            :class="{ 'tab-active': activeTab === reaction.reaction }"
            @click="activeTab = reaction.reaction"
          >
            <span class="text-xl leading-none">{{ reaction.reaction }}</span>
            <span
              class="text-base font-semibold transition-colors duration-200"
              :class="[
                activeTab === reaction.reaction
                  ? 'text-content'
                  : 'text-content-subtle'
              ]"
            >
              {{ reaction.count }}
            </span>
          </button>

          <!-- Animated indicator -->
          <div
            class="absolute bottom-3 z-0 h-11 rounded-full bg-surface-hover"
            :class="[
              enableIndicatorTransition
                ? 'transition-all duration-250 ease-out'
                : ''
            ]"
            :style="indicatorStyle"
          />
        </div>

        <!-- User list -->
        <div
          class="scrollbar-hide pb-safe flex-1 overflow-y-auto overscroll-contain py-2"
        >
          <TransitionGroup
            name="list"
            tag="div"
            class="flex flex-col"
            @before-enter="onBeforeEnter"
            @enter="onEnter"
            @leave="onLeave"
          >
            <div
              v-for="(item, index) in displayUsers"
              :key="`${activeTab ?? 'all'}-${item.clientId}-${item.emoji}-${index}`"
              :data-index="index"
              :data-testid="
                isOwnReaction(item.clientId)
                  ? 'reaction-row-own'
                  : 'reaction-row-other'
              "
              class="reaction-item flex items-center gap-3.5 px-5 py-3"
              :class="
                isOwnReaction(item.clientId)
                  ? 'cursor-pointer transition-colors active:bg-surface-hover sm:hover:bg-surface-hover'
                  : ''
              "
              @click="onRowClick(item)"
            >
              <!-- Avatar -->
              <div class="h-11 w-11 shrink-0">
                <img
                  v-if="getUserAvatar(item.clientId)"
                  :src="getUserAvatar(item.clientId)"
                  :alt="getUserName(item.clientId)"
                  class="h-full w-full rounded-full object-cover"
                  @error="
                    ($event.target as HTMLImageElement).style.display = 'none'
                  "
                />
                <div
                  v-else
                  class="flex h-full w-full items-center justify-center rounded-full bg-surface-muted text-xl font-semibold text-content-subtle"
                >
                  {{ getUserName(item.clientId).charAt(0).toUpperCase() }}
                </div>
              </div>

              <!-- Name, with the unsend hint beneath it on your own row -->
              <div class="flex min-w-0 flex-1 flex-col">
                <span class="truncate text-base font-medium text-content">
                  {{ getUserName(item.clientId) }}
                </span>
                <span
                  v-if="isOwnReaction(item.clientId)"
                  data-testid="reaction-sheet-hint"
                  class="truncate text-xs text-content-subtle"
                >
                  {{ t('reactionUnsendHint') }}
                </span>
              </div>

              <!-- Emoji -->
              <span class="emoji-bounce shrink-0 text-2xl">{{
                item.emoji
              }}</span>
            </div>
          </TransitionGroup>
        </div>
      </div>
    </div>
  </Teleport>
</template>

<style scoped>
/* Hide scrollbar */
.scrollbar-hide {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.scrollbar-hide::-webkit-scrollbar {
  display: none;
}

/* Safe area padding for iOS */
.pb-safe {
  padding-bottom: max(8px, env(safe-area-inset-bottom));
}

/* Reaction item base styles */
.reaction-item {
  will-change: transform, opacity;
}

/* FLIP move animation for list reordering */
.list-move {
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Ensure leaving items don't affect layout during move */
.list-leave-active {
  position: absolute;
  width: 100%;
}

/* Emoji subtle entrance effect */
.emoji-bounce {
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) 0.15s;
}
</style>
