<script setup lang="ts">
import { computed } from 'vue'
const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const fontSize = computed((): string => {
  const size: string = props.content.size
  const sizes: { [size: string]: string } = {
    xxs: '12px',
    xs: '13px',
    sm: '14px',
    md: '16px',
    lg: '19px',
    xl: '22px',
    xxl: '29px',
    '3xl': '35px',
    '4xl': '48px',
    '5xl': '74px'
  }
  return sizes[size] ?? '16px'
})
</script>

<template>
  <div class="basis-0" :style="{ flexGrow: content.flex ?? 0 }">
    <p
      :class="[
        'text-content',
        content.weight === 'bold' ? 'font-bold' : 'font-normal',
        content.wrap
          ? 'overflow-clip overflow-hidden break-words whitespace-normal'
          : 'truncate overflow-hidden whitespace-nowrap'
      ]"
      :style="{ fontSize, color: content.color, 'text-size-adjust': '100%' }"
    >
      {{ content.text }}
    </p>
  </div>
</template>

<style scoped></style>
