import type Message from './message'
import MessageLinkedList from './messageLinkedList'

export default class MessageMultiList {
  head: MessageLinkedList | null
  tail: MessageLinkedList | null
  main: MessageLinkedList | null
  length: number

  constructor(linkedList: MessageLinkedList | null = null) {
    this.head = linkedList
    this.tail = linkedList
    this.main = linkedList
    this.length = linkedList ? 1 : 0
  }

  numberOfMessages(): number {
    let count = 0
    let current = this.head
    while (current) {
      count += current.length
      current = current.next
    }
    return count
  }

  concate(linkedList: MessageLinkedList, anchorId?: string) {
    // Resolve the cursor after the request completes: navigation may change
    // main, and a merge may replace the segment that originally held it.
    const target = anchorId ? this.segmentContaining(anchorId) : this.main
    if (!target) return false
    target.concate(linkedList)
    return true
  }

  private segmentContaining(id: string): MessageLinkedList | null {
    let current = this.head
    while (current) {
      if (current.contains(id)) return current
      current = current.next
    }
    return null
  }

  finds(id: string) {
    return this.segmentContaining(id)?.finds(id)
  }

  // Whether a segment is still linked in the chain. merge() relinks an
  // absorbed segment's nodes into the survivor and splices it out, so a stale
  // reference (e.g. a snapshot taken before an await) must be re-validated
  // before repointing main at it.
  // Typed `unknown` because callers hold reactive-proxy-unwrapped references
  // whose type drops private members; identity comparison needs no shape.
  hasSegment(segment: unknown): boolean {
    let current: MessageLinkedList | null = this.head
    while (current) {
      if (current === segment) return true
      current = current.next
    }
    return false
  }

  replace(targetId: string, message: Message) {
    const targetSegment = this.segmentContaining(targetId)
    if (!targetSegment) return
    if (targetId !== message.id) {
      const dupSegment = this.segmentContaining(message.id)
      // The replacement already landed in another segment (e.g. a reconnect
      // REST refill raced the POST response): keep that copy, drop the
      // obsolete node so no two nodes share one id.
      if (dupSegment && dupSegment !== targetSegment) {
        targetSegment.remove(targetId)
        return
      }
    }
    targetSegment.replace(targetId, message)
  }

  remove(id: string) {
    const segment = this.segmentContaining(id)
    if (!segment) return
    segment.remove(id)
    // A segment drained to empty must leave the chain: every walker derefs
    // segment.head, and merge() can never absorb an empty list (canCombine
    // rejects length 0).
    if (segment.length === 0 && this.length > 1) {
      this.unlinkSegment(segment)
    }
  }

  private unlinkSegment(segment: MessageLinkedList) {
    if (segment.prev) {
      segment.prev.next = segment.next
    } else {
      this.head = segment.next
    }
    if (segment.next) {
      segment.next.prev = segment.prev
    } else {
      this.tail = segment.prev
    }
    if (this.main === segment) {
      this.main = segment.next ?? segment.prev
    }
    segment.prev = null
    segment.next = null
    this.length--
  }

  unshift(linkedList: MessageLinkedList, anchorId?: string) {
    // Resolve the cursor after the request completes: navigation may change
    // main, and a merge may replace the segment that originally held it.
    const target = anchorId ? this.segmentContaining(anchorId) : this.main
    if (!target) return false
    target.unshift(linkedList)
    return true
  }

  insert(linkedList: MessageLinkedList) {
    if (this.length === 0) {
      this.head = this.tail = this.main = linkedList
      this.length = 1
      return
    }
    if (linkedList.length === 0) return
    // An empty room's first load caches a single empty segment (the
    // constructor counts a truthy empty list); walking it would deref its null
    // head. It carries nothing — replace it wholesale.
    if (this.length === 1 && this.head!.length === 0) {
      this.head = this.tail = this.main = linkedList
      return
    }
    let current: MessageLinkedList | null = this.tail
    while (current && current.head!.createdAt > linkedList.head!.createdAt) {
      current = current.prev
    }
    if (current) {
      if (current === this.tail) {
        this.tail = linkedList
      }
      linkedList.next = current.next
      if (linkedList.next) {
        linkedList.next.prev = linkedList
      }
      current.next = linkedList
      linkedList.prev = current
    } else {
      linkedList.next = this.head
      if (linkedList.next) {
        linkedList.next.prev = linkedList
      }
      this.head = linkedList
    }
    this.main = linkedList
    this.length++
  }

  merge() {
    if (this.length <= 1) return
    let current: MessageLinkedList | null = this.tail
    while (current) {
      if (current.prev && current.canCombine(current.prev)) {
        current.combine(current.prev)
        if (current.prev === this.main) {
          this.main = current
        }
        current.prev = current.prev.prev
        if (current.prev) {
          current.prev.next = current
        } else {
          this.head = current
        }
        this.length--
        break
      }
      current = current.prev
    }
    if (current) {
      this.merge()
    }
  }

  isValid() {
    if (this.head && this.head.prev) {
      return false
    }
    if (this.tail && this.tail.next) {
      return false
    }
    let length = 0
    let current = this.head
    while (current) {
      if (current.prev && current.prev.next !== current) {
        return false
      }
      if (current.next && current.next.prev !== current) {
        return false
      }
      length++
      current = current.next
    }
    return length === this.length
  }
}
