<script setup lang="ts">
import { ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const imkit = useImkitStore()
const vfm = useVfm()
const isRequesting = ref(false)

const dismissModal = () => {
  localStorage.setItem('notification-permission-skipped', 'true')
  vfm.closeAll()
}

const requestPermission = async () => {
  if (isRequesting.value) return
  if (typeof window === 'undefined' || typeof Notification === 'undefined') {
    dismissModal()
    return
  }
  isRequesting.value = true
  try {
    await imkit.subscribe()
    if (
      Notification.permission === 'granted' ||
      Notification.permission === 'denied'
    ) {
      localStorage.setItem('notification-permission-skipped', 'true')
    }
    vfm.closeAll()
  } catch (error) {
    console.error('Error requesting notification permission:', error)
  } finally {
    isRequesting.value = false
  }
}
</script>

<template>
  <!-- pinchat's copy and handlers on the shared ConfirmDialogShell. The keys
       are pinchat's (they carry an extra line naming where the browser's
       notification setting lives, which the mainline copy omits); the chrome,
       button variants and tokens come from the shell. -->
  <ConfirmDialogShell
    :title="`${$t('allowOfflineNotifications')} ?`"
    :cancel-label="$t('askLater')"
    :confirm-label="$t('allowNotifications')"
    confirm-variant="primary"
    :loading="isRequesting"
    :disabled="isRequesting"
    @cancel="dismissModal"
    @confirm="requestPermission"
  >
    <p class="whitespace-break-spaces">
      {{ $t('notificationPermissionDescription') }}
    </p>
    <p class="mt-3 text-content-muted">
      {{ $t('notificationSettingsPath') }}
    </p>
  </ConfirmDialogShell>
</template>
