<script setup lang="ts">
/**
 * Moved onto ConfirmDialogShell. It had its own dialog: `rounded-xl` shell
 * with no border or shadow, a centred title under an alert icon, a close ✕,
 * and a full-width button — none of which the fourteen other dialogs in this
 * app do. The shell's shape is left-aligned text, no icon, no ✕, and an
 * auto-width button bottom-right.
 *
 * The alert icon goes with it. That is the shell's own documented decision
 * (see its doc comment): the shape is meant to read as a question rather than
 * an incident, and an error dialog is not an exception to that — every other
 * error branch in this app already uses the same shell without one.
 *
 * `primary`, not the default `danger`: this is an acknowledgement of a failed
 * payment, not a destructive action the user is about to take.
 */
import { useVfm } from 'vue-final-modal'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
</script>

<template>
  <confirm-dialog-shell
    :title="$t('paymentFailed')"
    :confirm-label="$t('confirm')"
    confirm-variant="primary"
    confirm-test-id="payment-error-confirm"
    @confirm="vfm.closeAll()"
    @cancel="vfm.closeAll()"
  >
    {{ $t('paymentFailedDescription') }}
  </confirm-dialog-shell>
</template>
