import { contrastRatio, deriveOwnBubble } from '../runtime/theme'

/**
 * Per-link colours for the visitor's own message bubble, as the pinchat guest
 * config pre-bakes them (`chat_bubble_color` -> `background`,
 * `chat_bubble_text_color` -> `color`, `chat_bubble_border_color` -> `border`).
 */
export type ChatOwnBubbleColors = {
  background?: string
  color?: string
  border?: string
}

/**
 * Build the token overrides that make the own-message bubble follow a link's
 * configured colours.
 *
 * Returns `undefined` when the link configures nothing, so the derived palette
 * stands.
 *
 * This re-points `--color-message-own` / `--color-message-own-content` on the
 * chat root instead of passing a style down to MessageCell. The bubble is
 * already painted `bg-message-own text-message-own-content`, and the same
 * tokens reach every other surface that echoes the own bubble (the quoted
 * preview, the mobile action overlay), which a prop on one component would not.
 *
 * `border` is deliberately NOT consumed. The redesigned own bubble draws no
 * outline at all — adding one would change the geometry of every sent message,
 * including the squared corner of a grouped run — so there is nothing for the
 * value to colour. The default config sets it equal to `background`, so this is
 * invisible for a link that has not deliberately set the two apart.
 */
export function chatOwnBubbleStyle(
  self: ChatOwnBubbleColors | undefined | null,
  dark = false
): Record<string, string> | undefined {
  const background = self?.background?.trim()
  const configured = self?.color?.trim()
  if (!background && !configured) return undefined
  // A text-only override was chosen against the light configured fill. In
  // dark mode there is no fill seed to adapt, so keep the palette's verified
  // pair instead of applying that light-mode foreground by itself.
  if (!background && dark) return undefined

  // The configured fill is a SEED, not a finished colour: `deriveOwnBubble`
  // adapts it to the mode the same way `deriveTokens` adapts the `ownBubble`
  // palette seed. Applied verbatim it only suited the mode it was picked in —
  // the shipped presets are pale pastels that glowed at 10-14:1 on a dark
  // canvas, brighter than the agent's own bubbles.
  const derived = background ? deriveOwnBubble(background, dark) : undefined
  // A configured text colour was chosen for the configured fill. If that fill
  // is invalid, applying either half would replace a valid derived token with
  // an unverified pair. Leave the complete palette standing instead.
  if (background && !derived) return undefined

  const style: Record<string, string> = {}
  if (derived) style['--color-message-own'] = derived.fill
  // A configured text colour is honoured in LIGHT, where it was chosen and can
  // be seen against the fill it was chosen for. In dark the fill has moved, so
  // the derived foreground — which is held to 4.5:1 against it — wins.
  style['--color-message-own-content'] =
    (dark ? derived?.content : configured || derived?.content) ||
    // Only a fill configured: pick the better of black and white rather than
    // leaving the derived foreground, which was chosen for a different fill.
    ((background &&
    contrastRatio('#ffffff', background) >= contrastRatio('#000000', background)
      ? '#ffffff'
      : '#000000') as string)
  return style
}
