<script setup lang="ts">
import { Search } from 'lucide-vue-next'
import { VList } from 'virtua/vue'
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Folder from '../../classes/folder'
import type Room from '../../classes/room'
import { useImkitStore } from '../../stores/imkit'
import RoomCell from './RoomCell.vue'

const vfm = useVfm()
const props = defineProps<{ folderId: string }>()
const imkit = useImkitStore()
const folder = ref<Folder | undefined>()
const folderName = ref('')
const roomSearchKeyword = ref('')
const sortedRooms = computed(() => {
  const rooms = folder.value
    ? folder.value.roomIds
        .map((id: string) => imkit.rooms[id])
        .concat(imkit.sortedRooms)
    : imkit.sortedRooms
  return rooms
    .filter((room): room is Room => !!room && !room.isPinchatAi)
    .sort((a, b) =>
      !!a.pref?.sticky === !!b.pref?.sticky
        ? b.updatedAt - a.updatedAt
        : a.pref?.sticky
          ? -1
          : 1
    )
})
const filteredRooms = computed(() => {
  const keyword = roomSearchKeyword.value.trim().toLowerCase()
  if (!keyword) return sortedRooms.value
  return sortedRooms.value.filter((room) =>
    (room.displayName ?? '').toLowerCase().includes(keyword)
  )
})
const selectedCount = computed(
  () => Object.keys(imkit.selectedRoomIdsForCreateFolder).length
)
const isValid = computed(
  () =>
    folderName.value.length > 0 &&
    Object.keys(imkit.selectedRoomIdsForCreateFolder).length > 0
)

const submit = async () => {
  try {
    await imkit.updateFolder({
      folderKey: folder.value?.id || `folder_${Date.now()}`,
      name: folderName.value
    })
  } catch (error) {
    // updateFolder POSTs to /me/pref/* and throws on failure. The confirm @click
    // fires this unawaited and then closes the modal, so a rejection would become
    // an unhandled rejection with the modal already gone. Swallow it (logged, not
    // surfaced — no toast infra in this SDK, same as MassTextingModal); the
    // selection is left intact for a retry (updateFolder clears it on success).
    console.error('Failed to update folder', error)
  }
}
folder.value = imkit.folders[props.folderId]
if (folder.value) {
  folderName.value = folder.value.name
  const seedTime = Date.now()
  const seeded = folder.value.roomIds
    .filter((roomId: string) => !imkit.rooms[roomId]?.isPinchatAi)
    .reduce(
      (acc: { [roomId: string]: Date }, roomId: string, index: number) => {
        acc[roomId] = new Date(seedTime + index)
        return acc
      },
      {}
    )
  // Use the FUNCTION form to REPLACE the selection with exactly this folder's
  // rooms. The object form ($patch({ selectedRoomIdsForCreateFolder: {...} }))
  // is recursively MERGED by Pinia, so a stale selection left by a prior flow
  // would survive and then be saved into the folder by updateFolder (which reads
  // selectedRoomIdsForCreateFolder). Assigning replaces.
  imkit.$patch((state) => {
    state.selectedRoomIdsForCreateFolder = seeded
  })
} else {
  // Create mode must never inherit room picks from an earlier cancelled flow.
  // Replace rather than merge so opening a fresh create dialog always begins
  // with no rooms selected.
  imkit.$patch((state) => {
    state.selectedRoomIdsForCreateFolder = {}
  })
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg border border-border p-5 flex flex-col gap-3 w-[360px] shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="text-xl font-semibold text-content">
      {{ folder ? $t('editFolder') : $t('createFolder') }}
    </div>
    <p class="text-xs text-content-muted">
      {{ $t('createFolderExplain') }}
    </p>
    <label class="flex flex-col gap-1.5">
      <span class="text-xs font-semibold text-content-muted">
        {{ $t('folderName') }}
      </span>
      <div
        class="flex items-center gap-2 rounded-md border border-border bg-surface px-3.5 py-2.5 focus-within:border-accent focus-within:ring-2 focus-within:ring-accent-subtle"
      >
        <input
          v-model="folderName"
          type="text"
          maxlength="30"
          class="grow bg-transparent text-base text-content placeholder-content-subtle outline-none"
          :placeholder="$t('folderName')"
        />
        <span class="shrink-0 text-xs text-content-muted"
          >{{ folderName.length }}/30</span
        >
      </div>
    </label>
    <div class="flex flex-col gap-1.5">
      <span class="text-xs font-semibold text-content-muted">
        {{ $t('addRoomsToFolder') }}
      </span>
      <div class="relative">
        <Search
          class="pointer-events-none absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-content-subtle"
        />
        <input
          v-model="roomSearchKeyword"
          type="text"
          :aria-label="$t('searchInConversation')"
          :placeholder="$t('searchInConversation')"
          class="h-10 w-full rounded-md border border-border bg-surface py-2.5 pr-3.5 pl-9 text-base text-content placeholder-content-subtle outline-none focus:border-accent focus:ring-2 focus:ring-accent-subtle"
        />
      </div>
    </div>
    <div
      class="flex h-56 flex-col overflow-hidden rounded-md border border-border"
    >
      <VList
        v-slot="{ item }"
        :data="filteredRooms"
        :item-size="44"
        class="grow overflow-auto"
      >
        <RoomCell :source="item" />
      </VList>
    </div>
    <div class="flex items-center justify-between gap-2">
      <span class="text-xs text-content-muted">
        {{ $t('selectedCount', { n: selectedCount }) }}
      </span>
      <div class="flex items-center gap-2">
        <button
          class="inline-flex h-10 cursor-pointer items-center justify-center rounded-md bg-surface-muted px-4 text-base font-medium text-content transition-colors"
          @click="
            () => {
              vfm.closeAll()
            }
          "
        >
          {{ $t('cancel') }}
        </button>
        <button
          class="inline-flex h-10 items-center justify-center rounded-md bg-accent px-4 text-base font-medium text-white transition-colors disabled:cursor-not-allowed disabled:bg-surface-muted disabled:text-content-faint"
          :disabled="!isValid"
          @click="
            () => {
              submit()
              vfm.closeAll()
            }
          "
        >
          {{ folder ? $t('confirm') : $t('create') }}
        </button>
      </div>
    </div>
  </vue-final-modal>
</template>
